(window.AQIDA_TEXTS = window.AQIDA_TEXTS || {})["533"] = {"atoms": {"533.1": {"x": [[5, "السيد أحمد بن السيد رمضان بن منصور بن السيد محمد بن شمس الدين محمد بن السيد رئيس بن السيد زين الدين بن ناصب الدين بن ناصر الدين بن محمد بن قاسم بن محمد بن رئيس إبراهيم بن محمد بن سيدي مرزوق الكفافي بن سيدي موسى بن عبد الله المحض بن الإمام حسن المثنى بن الحسن السبط ابن الإمام علي بن أبي طالب كرم الله وجهه. المالكي المرزوقي الحسني من جهة أبيه الحسيني من جهة أمه، البصير بقلبه، مفتي المالكية بمكة البهية، تولاها بعد موت أخيه السيد محمد سنة 1261 هـ إحدى وستين ومائتين وألف، الإمام الورع الزاهد، المدرس بالمسجد الحرام صاحب التصانيف الشهيرة. ولد بـ (سنباط) أثناء عام خمس بعد المائتين والألف، كما أفاد بذلك أخوه السيد محمد في بعض تآليفه، الآتي ترجمته في حرف الميم نقلاً عن والدهما، وكنيته أبو الفوز كنّى به شيخ السجادة الوفائية أبو الإقبال أحمد وفا ولقبه المرزوقي نسبة إلى العارف بالله مرزوق الكفافي المتقدم ذكره المدفون بكفافة على شاطئ البحر"]], "pg": [5, 5]}, "533.2": {"x": [[6, "المالح بأرض الحجاز، له تلامذة وأصحاب كثيرون وزاوياته مائة وأربعون زاوية، مفرقة في البلدان، وتفصيلها مذكور في كتاب مشتمل على نسبه. ومن تصانيف السيد أحمد المترجم: متن عقيدة العوام وشرحها (تحصيل نيل المرام)، وقد كنت ألفت حاشية عليه حين قراءتي له، سميتها فيض الملك العلام، وشرح على مولد شرف الأنام، ورسالة تتعلق بلفظة بافضل سماها (بيان الأصل في لفظ بافضل)، وشرح مسمى بـ (تسهيل الأذهان على متن تقويم اللسان في النحو للخوارزمي البقالي)، وشرح على الأجرومية سماه الفوائد المرزوقية، ومنظومة في قواعد الصرف والنحو، ومتن نظم في علم الفلك شرحه أخوه السيد محمد المذكور شرحاً لطيفاً، وقد توفي بمكة سنة 1262 هـ اثنين وستين ومائتين وألف ودفن بالمعلاة رحمه الله ولم يعقب إلا ابنة واحدة هي جدة بعض جماعات بيت السيد الكتبي. وممن أخذ عن المترجم، وقرأ عليه الشيخ أحمد دهان، والسيد أحمد دحلان، والشيخ طاهر التكروري، والشيخ أحمد الحواني القراء الشامي. وكان المترجم يدرس بجوار مقام المالكي وفي آخر عمره كان يقرأ في تفسير العلامة البيضاوي. [1]\r____________\r[1] انتهى من كتاب (اختصار النور والزهر). ص 113 - 114."], [7, "ترجمة الشيخ نواوي الجاوي صاحب الشرح\rنواوي الجاوي البنتني، ابن عمر بن علي الشافعي، نزيل مكة المكرمة. ولد ببلده، وقدم مكة صغيراً، وجاور بها سنين عديدة، ونشأ بها، وصار ذا ثروة واقتنى كتباً كثيرة وأكب على كسب العلوم على عدة مشايخ وتحصيلها، واجتهد حتى صار إماماً في المنطوق والمفهوم، منهم السيد أحمد النحراوي، وأحمد الدمياطي، وقرأ على الشيخ حسب الله ودرس وأفاد، وتخرج به كثير من طلبة الجاوة، وكان تدريسه بداره، ودرسه يحتوي على مائتي طالب بل أكثر كما شاهدت بنفسي مراراً مع تواضع وانكسار وخمول، وتكررت منه رحلات إلى مصر والشام، وأخذ عن أفاضلها وليس له اشتغال إلا بالتدريس والإفادة والتآليف والعبادة مع طبع أرق من النسيم. [1]\r____________\r[1] انتهى من كتاب (اختصار النور والزهر) ص 504."], [9, "منظومة عقيدة العوام\r"]], "pg": [6, 9]}, "533.3": {"x": [[9, "للشيخ أحمد المرزوقي المالكي المكي\rأبدأُ باسمِ اللهِ والرحمنِ…وبالرحيمِ دائمِ الإحسانِ\rفالحمدُ للهِ القديمِ الأولِ…والآخرِ الباقيْ بلا تَحَوُّلِ\rثُمَّ الصلاةُ والسلامُ سَرْمَدا…على النبيِّ خيرِ مَنْ قَدْ وَحَّدَا\rوَآلِهِ وصحبِهِ وَمَنْ تَبِعْ…سبيلَ دينِ الحَقِّ غيرَ مبتدعْ\rوبعدُ فاعلمْ بوجوبِ المعرفةْ…مِنْ واجبٍ للهِ عشرينَ صفةْ\rفاللهُ موجودٌ قديمٌ باقيْ…مخالفٌ للخلقِ بالإطلاقِ\rوقائمٌ غنيْ وواحدٌ وَحَيْ…قادرْ مُرِيْدٌ عالمٌ بِكُلِّ شَيْ\rسميعٌ البصيرْ والمتكلمُ…لَهُ صفاتٌ سبعةٌ تَنْتَظِمُ\rفقدرةٌ إرادةٌ سَمْعٌ بَصَرْ…حياةٌ العلمُ كلامٌ اسْتَمَرْ\rوجائزٌ بفضلِهِ وعدلِهِ…تركٌ لكلِّ ممكنٍ كَفِعْلِهِ\rأرسلَ أنبيا ذويْ فَطانةْ…بالصدقِ والتبليغِ والأمانةْ\rوجائزٌ في حقهمْ من عرضِ…بغيرِ نقصٍ كخفيفِ المرضِ"], [10, "عِصْمَتُهُمْ كسائرِ الملائكةْ…واجبةٌ وفاضلوا الملائكةْ\rوالمستحيلُ ضِدُّ كُلِّ واجبِ…فاحفظْ لخمسينَ بحكمٍ واجبِ\rتفصيلُ خمسةٍ وعشرينَ لَزِمْ…كُلَّ مُكَلَّفٍ فَحَقِّقْ واغتنِمْ\rهُمْ آدَمٌ إدريسُ نوحٌ هودٌ معْ…صالحْ وإبراهيمُ كُلٌّ مُتَّبَعْ\rلوطٌ وإسماعيلُ إسحاقُ كذا…يعقوبُ يوسفُ وأيوبُ احتذى\rشعيبُ هارونُ وموسى وَاليَسَعْ…ذو الكفلِ داودُ سليمانُ اتَّبَعْ\rإلياسُ يونُسْ زكريَّا يحيى…عيسى وَطَهَ خَاتِمٌ دَعْ غَيّا\rعليهمُ الصلاةُ والسلامُ…وَآلِهِمْ ما دامتْ الأيامُ\rوَالمَلَكُ الذي بلا أبٍ وأمْ…لا أَكْلَ لا شُرْبَ ولا نومَ لَهُمْ\rتفصيلُ عشرٍ منهمُ جبريلُ…مِيْكَالُ إسرافيلُ عَزرائيلُ\rمُنْكَرْ نَكِيْرٌ ورقيبٌ وكذا…عتيدُ مالكٌ ورضوانُ احتذى\rأربعةٌ مِنْ كُتُبٍ تفصيلُها…توارةُ موسى بالهدى تنزيلُها\rزبورُ داودَ وإنجيلُ على…عيسى وفرقانٌ على خيرِ الملا\rوصحفُ الخليلِ والكليمِ…فيها كلامُ الحَكَمِ العليمِ\rوَكُلُّ ما أتى به الرسولُ…فحقُّه التسليمُ والقَبولُ\rإيمانُنا بيومٍ آخِرٍ وَجَبْ…وَكُلُّ ما كان به من العَجَبْ"], [11, "خاتمةٌ في ذِكْرِ باقي الواجبِ…مما على مكلفٍ مِنْ واجبِ\rنبيُّنا محمدٌ قدْ أُرسلا…للعالَمين رحمةً وَفُضِّلَا\rأبوهُ عبدُ اللهِ عبدُ المطلبْ…وهاشمٌ عبدُ منافٍ يَنْتَسِبْ\rوَأُمُّهُ آمنةُ الزُّهْرِيَّةْ…أَرْضَعَتْهُ حليمةُ السعديةْ\rمولدُهُ بمكةَ الأمينةْ…وفاتُهُ بطَيبةَ المدينةْ\rأَتَمَّ قبلَ الوحيِ أربعينا…وعمرُهُ قَدْ جاوزَ الستينا\rوسبعةٌ أولادُه فمنهمُ…ثلاثةٌ مِنَ الذكورِ تُفْهَمُ\rقاسمْ وعبدُ اللهِ وهو الطيبُ…وطاهرٌ بذينِ ذا يُلَقَّبُ\rأَتَاهُ إبراهيمُ من سُرِيَّةْ…فَأُمُّهُ مَارِيَّةُ القِبْطِيَّةْ\rوغيرُ إبراهيمَ مِنْ خديجةْ…هم ستةٌ فخذْ بهمْ وَلِيْجَةْ\rوأربعٌ مِنَ الإناثِ تُذْكَرُ…رضوانُ ربي للجميعِ يُذْكَرُ\rفاطمةُ الزهراءُ بعلُها عليْ…وابناهما السِّبْطَانِ فضلُهم جَلِيْ\rفزينبٌ وبعدَها رُقَيَّةْ…وَأُمُّ كُلثومٍ زَكَتْ رَضِيَّةْ\rعَنْ تِسْعِ نسوةٍ وفاةُ المصطفى…خُيِّرْنَ فاخترنَ النبيَّ المُقْتَفَى\rعائشةٌ وحفصةٌ وسودةْ…صفيةٌ ميمونةٌ ورملةْ\rهندٌ وزينبٌ كذا جُوَيْرِيَّةْ…للمؤمنينَ أمهاتٌ مَرْضِيَّةْ"], [12, "حمزةُ عَمُّهُ وعباسٌ كذا…عمتهُ صَفِيَّةٌ ذَاتُ احْتِذَا\rوقبلَ هجرةِ النبيِّ الإسرا…من مكةٍ ليلاً لقدسٍ يُدْرَى\rوبعدَ إسراءٍ عروجٌ للسما…حتى رأى النبيُّ رَبّاً كَلَّمَا\rمِنْ غَيْرِ كيفٍ وانحصارٍ وافترضْ…عليهِ خمساً بعدَ خمسينَ فَرَضْ\rوَبَلَّغَ الأمةَ بالإسراءِ…وَفَرْضِ خمسةٍ بلا امتراءِ\rقَدْ فَازَ صِدِّيْقٌ بتصديقٍ لَهُ…وبالعُروجِ الصدقُ وافى أَهْلَهُ\rوهذهِ عقيدةٌ مختصرةْ…وللعوامِ سهلةٌ مُيَسَّرَةْ\rناظمُ تلكَ أحمدُ المرزوقيْ…من ينتمي للصادقِ المَصْدُوْقِ\rو الحمدُ للهِ وَصَلَّى سَلَّمَا…على النبيِّ خيرِ مَنْ قَدْ عَلَّمَا\rوَالآلِ والصحبِ وَكُلِّ مُرْشِدِ…وَكُلِّ مَنْ بخيرِ هديٍ يقتدي\rوأسألُ الكريمَ إخلاصَ العملْ…ونفعَ كُلِّ مَنْ بِهَا قَدِ اشْتَغَلْ\rأبياتُها مَيْزٌ بِعَدِّ الجُمَّلِ…تاريخُها لِيْ حَيُّ غُرٍّ جُمَّلِ\rسَمَّيْتُهَا عقيدةَ العَوَامِ…مِنْ واجبٍ في الدينِ بالتمامِ"], [13, "بسم الله الرحمن الرحيم\rالحمد لله الذي أنعم على عباده المؤمنين بالعرفان، وأكرمهم من مزيد فضله برؤيته في الجنان. وأشهد أن لا إله إلا الله الملك العلام، وأشهد أن سيدنا محمداً عبده ورسوله صاحب أعلى المقام، والصلاة والسلام على من أرسله الله رحمة للأنام، إذ لولاه لكانت أحوالهم أقبح من الأنعام، وعلى آله البررة الكرام، وأصحابه مصابيح الظلام، والتابعين لهم بإحسان إلى يوم تنطق فيه جميع الأعضاء، ويبكم فيه اللسان، صلاةً وسلاماً دائمين متلازمين ما دامت الأوقات والأوان.\r\rأما بعد، فيقول الفقير لغفران العزيز الجبار، لكثرة الذنوب والأوزار، محمد نووي الشافعي: هذا شرح منيف، وفتق ظريف على المنظومة الملقبة (بعقيدة العوام) للشيخ العالم اللوذعي السيد أحمد المرزوقي المالكي، وسميته (نور الظلام على عقيدة العوام) وقصدي به النفع لي ولمثلي من المبتدئين وإن كنت لست أهلاً لذلك. نفع الله به كل سالك.\r\r(اعلم) أن سبب هذه المنظومة أن الناظم رأى النبي صلى الله عليه وسلم في المنام آخر ليلة الجمعة من أول جمعة"], [14, "من شهر رجب سادس يوم حساباً من شهور سنة ألف ومائتين وثمان وخمسين هجرية، وأصحابه رضي الله عنهم واقفون حوله. وقال له النبي صلى الله عليه وسلم: (اقرأ منظومة التوحيد التي من حفظها دخل الجنة، ونال المقصود من كل خير وافق الكتاب والسنة، فقال له: وما تلك المنظومة يا رسول الله؟ فقال الأصحاب له: اسمع مِنْ رسول الله ما يقول، فقال رسول الله صلى الله عليه وسلم: قل: أبدأُ باسم الله والرحمن، فقال: أبدأ باسم الله والرحمن، إلى آخرها وهو قوله:\rوصحف الخليل والكليمِ…فيها كلام الحكم العليمِ\rورسول الله صلى الله عليه وسلم يسمعه، فلما استيقظ من منامه قرأ ما رآه في منامه، فوجده محفوظاً عنده من أوله إلى آخره. ثم لما كانت ليلة الجمعة التي هي ليلة الثامن والعشرين حساباً من شهر ذي القعدة رأى الناظم النبي صلى الله عليه وسلم مرة ثانية وقت السحر في المنام، فقال له النبي صلى الله عليه وسلم: (اقرأ ما جمعتَه) - أي في قلبك - فقرأه من أوله إلى آخره وهو واقف بين يديه صلى الله عليه وسلم وأصحابه رضي الله عنهم واقفون حوله يقولون آمين بعد كل بيت من هذه المنظومة، فلما ختم قراءته قال له النبي صلى الله عليه وسلم: وفقك الله تعالى لما يرضيه، وَقَبِلَ منك ذلك، وبارك عليك وعلى المؤمنين، ونفع بها العباد .. [1] آمين. ثم سُئل الناظم\r____________\r[1] كيف لا يكون ذلك؟ وقد حوت هذه المنظومة خلاصة عقيدة أهل ="], [15, "بعد اطلاع الناس على تلك المنظومة فأجاب سؤالهم، فزاد عليها منظومة من قوله:\rوكل ما أتى به الرسولُ…فحقه التسليم والقبولُ\rإلى آخر الكتاب؟ قال الناظم رضي الله تعالى عنه:\r____________\r= السنة والجماعة، ورؤيا النبي صلى الله عليه وآله وسلم حق كما قال صلى الله عليه وعلى آله وسلم: (من رآني في المنام فقد رآني فإن الشيطان لا يتمثل بي) رواه البخاري والترمذي وأحمد، وقال صلى الله عليه وآله وسلم: (من رآني فقد رأى الحق فإن الشيطان لا يتزيى بي). رواه البخاري ومسلم وأحمد.\rوالرؤيا الصالحة كالتي وقعت للمؤلف الناظم السيد أحمد المرزوقي - رحمه الله - من المبشِّرات كما قال صلى الله عليه وآله وسلم: (لم يبق من النبوة إلا المبشِّرات، قالوا: وما المبشرات؟ قال: الرؤيا الصالحة) رواه البخاري، وهي جزء من ستة وأربعين جزءاً من النبوة كما ورد في الحديث المروي في الصحيحين. ومثل هذه الرؤيا لم تقع للناظم فقط بل ولغيره فإن الإمام الشاطبي لما أتم منظومته الشهيرة بالشاطبية رأى أنه يقرأها أمام النبي صلى الله عليه وآله وسلم فقال له صلى الله عليه وآله وسلم: من حفظها دخل الجنة."], [16, "أبدأ باسم الله والرحمن…"]], "pg": [9, 16]}, "533.4": {"x": [[16, "وبالرحيم دائم الإحسان\r\rأي أبدأ في تأليف هذه المنظومة مستعيناً بمسمى اسم الله، كما فسَّر بذلك البيجوري. والإتيان بالبسملة منظومة هو خلاف الأولى [1] نبه على ذلك البيجوري.\r\rواعلم أن الاسم عينُ المسمى كما عليه أكثر الأشاعرة. قال تعالى: {سَبِّحِ اسْمَ رَبِّكَ} وقال أيضاً: {مَا تَعْبُدُونَ مِنْ دُونِهِ إِلَّا أَسْمَاءً} وظاهر أن التسبيح والعبادة للذوات. وقيل الاسم غير المسمى لقوله تعالى: {لَهُ الْأَسْمَاءُ الْحُسْنَى\r} ولا بد من المغايرة بين الشيء وما هو له، ولتعدد الأسماء مع اتحاد المسمى، ولو كان عينه لاحترق فم من قال: (نار) إلى غير ذلك من المفاسد.\r\rوالتحقيق أنه إن أُريد من الاسم اللفظ فهو غير مسماه قطعاً - أي بلا خلاف - وإن أريد به ما يُفهم منه فهو عين المسمى، قاله الشنواني. قال السيوطي: فمعنى (الله) مَنْ تقادَمَ وجوده، وتعاظم ذاته وصفاته، وعم جودُه. ومعنى (الرحمن) من عظم إحسانه، ودام امتنانُه. ومعنى (الرحيم)"], [17, "مَنْ سَدَّ كل فاقة، ولم يحمل دون طاقة، وقال أحمد الصاوي: و (الله) هو الاسم الجامع، لأن جميع الأسماء مندرجة فيه و (الرحمن) المنعم بجلائل النعم كماً وكيفاً دنيوية وأخروية، ظاهرة وباطنة، و (الرحيم) هو المنعم بدقائق النعم كماً وكيفاً دنيوية وأخروية، ظاهرة وباطنة .. والدقائق ما تفرعت عن الأصول التي هي الجلائل كالزيادة في الإيمان والعلم والمعرفة والتوفيق والعافية والسمع والبصر. اهـ. قال أحمد الملوي: و (الرحمن) أبلغ من الرحيم لأن زيادة أحد المتفقين اشتقاقاً ونوعية تدل على زيادة المعنى لأن معناه المنعم الحقيقي البالغ في الرحمة غايتها، وذلك لا يصدق على غيره تعالى، بل رجح بعضهم عَلميته، ولما دل على جلائل النعم وأصولها ذكر الرحيم، ليتناول ما دق ولطف ليكون كالتتمة .. والأبلغية إنما تؤخذ باعتبار الكمية - أي العدد - ولذا قيل يا رحمن الدنيا لأنه يعم المؤمن والكافر، ورحيم الآخرة لأنه لا يخص الكافر. وتارة باعتبار الكيفية - أي الصفة - ولذا قيل يا رحمن الدنيا والآخرة، ورحيم الدنيا لأن النعم الأخروية كلها جسام وأما الدنيوية فجليلة وحقيرة، قال البيضاوي: وَنِعَمُ الله تعالى وإن كانت لا تُحصى تنحصر في جنسين: دنيوي وأخروي، فالدنيوي قسمان: وهبي وكسبي، فالوهبي قسمان: روحاني كنفخ الروح في العبد وإشراقه بالعقل، وما يتبعه من القوى كالفهم"], [18, "والفكر والنطق، وجسماني كخلق البدن والقوى الحالّة فيه والهيئات العارضة له من الصحة وكمال الأعضاء. والكسبي تزكية النفس عن الرذائل، وتحليتها بالأخلاق المَرْضِيَّةِ، وتزيين البدن بالهيئات المطبوعة والحلى المستحسنة وحصول الجاه والمال. والأخروي أن يغفر ما فرط من العبد ويرضى عنه ويبوئه في أعلى عليين مع الملائكة المقرَّبين أبد الآبدين. وقول الناظم (دائم الإحسان) أي متتابع الإعطاء والإنعام من غير انصرام، فهو تكميل للبيت."], [19, "فالحمد لله القديم الأولِ…"]], "pg": [16, 19]}, "533.5": {"x": [[19, "الآخر الباقي بلا تحولِ\r\rأي فأثني على الله بلساني على هذه النعمة، مع تعظيمي إياه وأقر وأعتقد أن كل ثناء ثابت له.\rافتتح الناظم بالحمد أداءً لحق شيء مما يجب عليه من شكر النعماء التي تأليف هذه المنظومة أثر من آثارها، والحمد لغة الثناء باللسان على الجميل الاختياري مع جهة التبجيل والتعظيم، سواء كان في مقابلة نعمة أم لا. فمثال الأول ما إذا أكرمك زيد بشيء فقلت: (زيد كريم) فإنه في مقابلة نعمة، ومثال الثاني ما إذا وجدت زيداً يصلي صلاة تامة فقلت: (زيد رجل صالح) فإنه ليس في مقابلة نعمة، ولا يحصل الحمد إلا بخمس دعائم: حامد ومحمود وهما معلومان، ومحمود به كثبوت العلم أو الصلاح مثلاً، ومحمود عليه وهو الإكرام، وخرج به ما إذا كان على سبيل الاستهزاء والسخرية، ولذلك قلنا مع جهة التبجيل والتعظيم. وأقسام الحمد أربعة: حمدُ قديم لقديم وهو حمد الله نفسه لنفسه كقوله سبحانه وتعالى: {نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ}، وحمد قديم لحادث كقوله تعالى في حق نبينا محمد صلى الله عليه وسلم: {وَإِنَّكَ لَعَلى خُلُقٍ عَظِيمٍ}، وحمد حادث لقديم كقول سيدنا عيسى عليه السلام: {تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ\rإِنَّكَ أَنتَ عَلَّامُ الْغُيُوبِ}، وحمد حادث لحادث كقول رسول الله"], [20, "صلى الله عليه وسلم في حق سيدنا أبي بكر الصديق رضي الله تعالى عنه: (ما طلعت الشمس ولا غربت من بعدي على رجل أفضلَ من أبي بكر الصديق).\r\rوأما الحمد اصطلاحاً فهو فعل ينبئ عن تعظيم المنعم بسبب كونه منعماً على الحامد أو غيره، كولده وزوجته سواء كان ذِكراً باللسان أو محبة بالجنان، أو عملاً وخدمة بالأركان التي هي الأعضاء.\r\rوالشكر في اللغة مرادف للحمد في الاصطلاح، لكن يقال فيه بسبب كونه منعماً على الشاكر أو غيره، والشكر في الاصطلاح: صرف العبد جميع ما أنعم الله به عليه من السمع وغيره إلى ما خُلق لأجله، ويمكن تصويره ممن حمل جنازة متفكراً في مصنوعات الله، ناظراً لما بين يديه لكيلا يزل بالميت ماشياً برجليه إلى القبر، شاغلاً لسانه بالذكر، وأذنه باستماع ما فيه ثواب، كالأمر بالمعروف والنهي عن المنكر، ذكره أحمد الملوي لكن قال البراوي: فإن قلت: لا يتصور اجتماع الأعضاء في الطاعة في آن واحد، قلت: يتصور ذلك في الإحسان المأمور به في الحديث بأن تعبد الله كأنك تراه، ومستحضراً أنه يراك، فإذا عَبَدَ كذلك صارت أعضاؤه وحواسه ممتثلة لله، ولا يتصور في غير ذلك خلافاً لمن زعمه.\r\rواعلم أن النُسَبَ بين الحمد والشكر لغة واصطلاحاً"], [21, "ستة؛ أحدها بين الحمد الاصطلاحي والشكر اللغوي. فالنسبة بينهما الترادف، وثانيها بين الحمدين، وثالثها بين اللغويين. فالنسبة في هذين القسمين عموم وخصوص من وجه، وهو أن يجتمع كل منهما في مادة، وينفرد كل منهما في مادة أخرى، كما في خاتم حديد، فيجتمع الحمدان في الثناء باللسان في مقابلة الإحسان، وينفرد الحمد اللغوي في الثناء بالكلام في غير مقابلة الإكرام، وينفرد الحمد الاصطلاحي في الخدمة بالأعضاء في مقابلة العضاء، ويجتمع اللغويان في الثناء باللغة في مقابلة العطية، وينفرد الحمد اللغوي في الثناء بالفصاحة في غير مقابلة المباحة، وينفرد الشكر اللغوي في العمل بالأركان في مقابلة الامتنان. فالحمد اللغوي أخص مصدر أو هو اللسان وحده، وأعم متعلقاً وهو النعمة وغيرها. والحمد الاصطلاحي بالعكس كالشكر اللغوي، لأنه يكون باللسان والجنان والأركان لكنه في مقابلة النعمة فقط. ورابعها بين الشكر الاصطلاحي والحمد اللغوي، وخامسها بين الاصطلاحيين، وسادسها بين الشكرين، فالنسبة في هذه الأقسام الثلاثة: عموم وخصوص مطلق، وهو أن تجتمع كلها في مادة وينفرد أحدها في مادة أخرى كما في شجر أراك ولا عكس، فتجتمع كلها في الشكر الاصطلاحي لأنه أخص من الجميع، كما قد عرفت"], [22, "تصويره فلا يكون مصدره غيره كمصدره لأنه لا بد فيه من صرف جميع النعمة في زمن واحد. وينفرد الحمد اللغوي في الثناء باللسان من غير مقابلة الإحسان، وينفرد الحمد الاصطلاحي ومثله الشكر اللغوي في المحبة بالجنان في مقابلة الإحسان، ولا ينفرد أحد هذين عن الآخر، لأنهما مترادفان كما علمت.\r\rمن غريب الاتفاق أن أحرف الحمد خمسة، وقد ابتدئ به في القرآن خمس سور: الأولى سورة الفاتحة، والثانية سورة الأنعام وهي قوله تعالى: {الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَجَعَلَ الظُّلُمَاتِ وَالنُّورَ}، والثالثة سورة الكهف وهي: {الْحَمْدُ لِلَّهِ الَّذِي أَنزَلَ عَلَى عَبْدِهِ الْكِتَابَ}، والرابعة سورة سبأ وهي: {الْحَمْدُ لِلَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ}، والخامسة سورة الملائكة وهي: {الْحَمْدُ لِلَّهِ فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ جَاعِلِ الْمَلَائِكَةِ رُسُلًا}. واختتم به خمس سور أيضاً: الأولى سورة بني إسرائيل وهي قوله تعالى: {وَقُلِ الْحَمْدُ لله الَّذِي لَمْ يَتَّخِذْ وَلَدًا} الآية، والثانية سورة النمل وهي: {وَقُلِ الْحَمْدُ لِلَّهِ سَيُرِيكُمْ آيَاتِهِ فَتَعْرِفُونَهَا}، والثالثة سورة الصافات وهي: {وَسَلَامٌ عَلَى الْمُرْسَلِينَ. وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ}، والرابعة سورة الزمر وهي قوله تعالى: {وَقِيلَ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ}، والخامسة سورة الجاثية وهو: {فَلِلَّهِ الْحَمْدُ رَبِّ"], [23, "السَّمَاوَاتِ وَرَبِّ الْأَرْضِ رَبِّ الْعَالَمِينَ}. قال أحمد الملوي: (والحمد لله ثمانية أحرف، وأبواب الجنة ثمانية! فمن قالها عن صفاء قلب استحق ثمانية أبواب الجنة، أي يخيَّر بينها إكراماً له وإنما يدخل من الباب الذي علم الله أنه يدخل منه) اهـ. وقول الناظم القديم الأول إلى آخره، قال الحليمي: معنى القديم أنه الموجود الذي ليس لوجوده ابتداء، والموجود الذي لم يزل. اهـ. والأول هو الذي لا افتتاح لوجوده، والآخر هو الذي لا اختتام لوجوده، والباقي الدائم الذي لا يزول، ومعنى بلا تحول أي بلا تغير، وهو تفسير للباقي لأن معنى التحوُّل الانتقال من حال إلى حال.\r\rفائدة: اعلم أن الأشياء على أربعة أقسام: شيء لا أول له ولا آخر له وهو ذات الله تعالى وصفاته، وشيء له أول وآخر وهو ذات المخلوقين وصفاتهم، وشيء ليس له أول وله آخر وهو عدمنا الأزلي فينتهي بوجودنا، وشيء له أول وليس له آخر وهو الدار الآخرة. [2]\r____________\r[1] وإنما أتى الناظم بها نظماً مع أنها خلاف الأولى لسماعها من النبي صلى الله عليه وآله وسلم في الرؤيا السابقة التي ذكرها الشارح، ولأنه أراد أن منظومته تحفظ وتتلى على الصغار والعوام فضلاً عن غيرهم وهم لم يبدأوا المنظومة بالبسملة إلا إذا كانت نظماً.\r[2] وما فيها من عذاب ونعيم فكل باقٍ شرعاً لا عقلاً لأن العقل يجوز عدمها."], [24, "ثم الصلاة والسلام سرمدا…"]], "pg": [19, 24]}, "533.6": {"x": [[24, "على النبي خيرِ مَنْ قد وحَّدا\rوآله وصحبه ومن تَبِعْ…سبيلَ دينِ الحَقِّ غيرَ مبتدعْ\r\rأي رحمة الله المقرونة بالتعظيم، وتحيته اللائقة به صلى الله عليه وسلم كائنتان على من ذكر. والمعنى أن الناظم أنشأ الصلاة والسلام عليهم، فكأنه قال: أطلب منك يا الله الرحمة المقرونة بالتعظيم، والتحية العظمى التي بلغت الدرجة القصوى لتعظيمها هؤلاء المذكورين.\r\rوقوله (سرمداً) أي دائماً. وقوله (على النبي) بتشديد الياء من النبوة وهو المكان المرتفع، سُمِّيَ النبي به لأنه مرفوع الرتبة، أو رافع رتبة من تبعه، أو بالهمز من النبأ بتحريك الباء وهو الخبر لأنه مُخبِر عن الله تعالى. فهو على كليهما فعيل، بمعنى فاعل أو مفعول. وعبَّر الناظم بالنبي ولم يعبر بالرسول إشارةً إلى أنه يستحق الصلاة والسلام بوصف النبوة، كما يستحقهما بوصف الرسالة، وموافقة لقوله تعالى: {إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ}. وقوله (خير من قد وحدا) بدل من النبي أو صفة له، ويجوز النصب على أنه مفعول لفعل محذوف والتقدير أمدحُ أو أعني، ويجوز الرفع على أنه خبر لمبتدأ محذوف والتقدير هو، وهذا هو الأولى من جهة التعظيم، ليكون الاسم الشريف مرفوعاً وعمدة، كما أن مدلوله مرفوع الرتبة وعمدة الخلق، والمعنى أن النبي صلى الله عليه وسلم هو أفضل جميع الموحدين، لأنه لما"], [25, "شق سيدنا جبريل وميكائيل صدره الشريف عند حليمة بعد أن فصلته من الرضاع اعتبرا فضله وشرفه صلى الله عليه وسلم، وقاساه بفضل غيره فرجح وزاد بألف من أمته ذوي الفضل والشرف، فمن أمته بقية الأنبياء والمرسلين، ولذا قال محمد البوصيري في البردة من بحر البسيط:\rفاق النبيين في خَلْقٍ وفي خُلُقٍ…ولم يُدانوه في علمٍ ولا كَرَمِ\rوكلُّهم من رسول الله ملتمِسٌ…غرفاً من البحرِ أو رشفاً من الدِّيَمِ\r\rوالمعنى أنه صلى الله عليه وسلم فَضُلَ النبيين وغلبهم في صورته وشكله ولونه، وفي خصاله الحميدة كالعلم والحياء والجود والشفقة والحلم والعدل والعفة، ولم يقاربوه في ذلك كله، وكلهم آخذ من رسول الله صلى الله عليه وسلم مغترفاً من البحر أو مَاصّاً من المطر الدائم. والمراد من البحر والمطر هنا علمه وحلمه صلى الله عليه وسلم.\r\rقوله: (وآله وصحبه…الخ) المراد بالآل هنا: جميع المؤمنين ومنهم الأنبياء وأممهم. وبـ (صحبه): الذين اجتمعوا به صلى الله عليه وسلم بعد الرسالة مؤمنين، ولو قبل الأمر بالدعوة في حال حياته في الأرض، ولو في ظلمة أو كانوا عُمْياً، وإن لم يشعروا به أو كانوا غير مميزين أو مارين أو نائمين، أو لم يجتمعوا به لكن رأوا النبي صلى الله عليه وسلم أو رآهم النبي ولو مع بعد المسافة، ولو ساعة واحدة، ويدخل في الصحابي ابن أم مكتوم ونحوه من العميان، وكُنِّيت أمه به لكتم بصره، واسمه عبد الله، أحد المؤذنين له صلى الله عليه وسلم، ويدخل عيسى والخضر وإلياس عليهم الصلاة والسلام،"], [26, "وتدخل الملائكة الذين اجتمعوا به صلى الله عليه وسلم في الأرض، فعيسى عليه الصلاة والسلام آخر الصحابة من البشر الظاهرين. وأما الملائكة فباقون إلى النفخة، والخضر يموت عند رفع القرآن وقيل بل مات.\r\rوالحاصل أن الخضر وإلياس حيَّان على المعتمد، ولكن إلياس رسول بنص القرآن. قال تعالى: {وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ}. وأما الخضر فقيل هو ولي، وقيل نبي، وقيل رسول، وخير الأمور أوسطها.\r\rتنبيه: الخضر بفتح الخاء المعجمة وكسر الضاد المعجمة، ويجوز إسكان الضاد مع كسر الخاء أو فتحها. وإنما لُقب به لأنه جلس على فروة بيضاء، فإذا هي تهتز من خلفه خضراء، والفروة وجه الأرض. وكنيته أبو العباس، واسمه (بَلْيَا) بموحدة مفتوحة ولام ساكنة ومثناة تحتية (ابن مَلْكَان) بفتح الميم وإسكان اللام وبالكاف. وسُمع من بعض العارفين: مَنْ عرف اسمه واسم أبيه وكنيته ولقبه دخل الجنة. وهو يتعبد بشريعة نبينا من يوم بعثه الله تعالى.\r\rوالمراد بالتابعين في قول الناظم (ومن تبع) جميع من أتى بعد الصحابة من المؤمنين إلى يوم الجزاء.\r\rقوله: (سبيل دين الحق)؛ قال الفيومي في المصباح: والسبيل الطريق، ويُذكَّر ويُؤنَّث. قال ابن السكيت: وجمع"], [27, "المؤنث: (سُبُول) كما قالوا: (عنوق) وجمع المذكر (سُبُل) وسبل الدين الأحكام الشرعية. والحق هو كل ما وافق الكتاب والسنة والإجماع أو القياس، وهو خلاف الباطل.\r\rقوله: (غير مبتدع) حال من قوله (وَمَنْ تبع). والمبتدع هو من خرج عن الحق وهو المذموم، قال العلماء: البدعة لغة: ما كان مخترعاً على غير مثال سابق. وشرعاً: ما أُحدِث على خلاف أمر الشارع، وهي من حيث هي منقسمة إلى أقسام خمسة:\r\rأحدها واجب: وهو ما تناولته قواعد الوجوب وأدلته من الشرع، كتدوين القرآن والشرائع إذا خيف عليها الضياع، فإن التبليغ لمن بعدنا من القرون واجب إجماعاً وإهمال ذلك حرام إجماعاً. زاد بعض المتأخرين: ومن البدع الواجبة على الكفاية الاشتغالُ بعلوم العربية المتوقفِ عليها فهمُ الكتاب والسنة، كالنحو والصرف والمعاني والبيان، واللغةُ بخلاف العَروض والقوافي ونحوها، وتمييز صحيح الأحاديث من سقيمها، وتدوين نحو الفقه وأصوله وأدلته، والرد على القدرية والجبرية والمرجئة والمجسمة إذا دعت إلى ذلك حاجة، لأن حفظ الشريعة فرض كفاية، فما زاد على المتعيَّن ولا يتأتى حفظها إلا بذلك، وما لا يتأتى الواجب المطلق إلا به فهو واجب."], [28, "وثانيها حرام: وهو كل بدعة تناولتها قواعد التحريم وأدلته الشرعية، كالمكوس وتقديم الجهال على العلماء، وتولية المناصب الشرعية مَنْ لا يصلح لها بطريق التواتر، وجعل المستند في ذلك كون المنصب كان لأبيه وليس فيه أهلية له.\r\rوثالثها مندوب: وهو ما تناولته قواعد الندب وأدلته، كصلاة التراويح جماعة، وإقامة صور الأئمة والقضاة وولاة الأمور على خلاف ما كان عليه الصحابة - رضوان الله عليهم - بسبب أن المصالح والمقاصد الشرعية لا تحصل إلا بعظمة الولاة في نفوس الناس، وكان الناس في زمن الصحابة رضي الله عنهم إنما يَعْظُمون بالدين وسابق الهجرة والإسلام، ثم اختل النظام حتى صاروا لا يعظمون إلا بالصور. زاد بعضهم: ومن البدع المندوبة إحداث نحو الرُّبُطِ والمدارس وكل إحسان لم يعهد في الزمان الأول، والكلام في دقائق التصوف.\r\rورابعها مكروه: وهو ما تناولته أدلة الكراهة من الشريعة وقواعدها، كتخصيص الأيام الفاضلة على غيرها بنوع من العبادة، زاد بعضهم: ومن البدع المكروهة زخرفة المساجد، وتزويق المصاحف.\r\rوخامسها مباح: وهو ما تناولته أدلة الإباحة وقواعدها من الشريعة، كاتخاذ المناخل للدقيق، ففي الآثار أول"], [29, "شيء أحدثه الناس بعد رسول الله صلى الله عليه وسلم اتخاذ المناخل، لأن لين العيش وإصلاحه من المباحات، فوسائله مباحة. ذكر ذلك إبراهيم اللقاني. قال ابن حجر: (ومن المباحة التوسع في لذيذ المآكل والمشارب) وتوسيع الأكمام - وهو أطراف يد القميص - وقد يختلف العلماء في ذلك فيجعله بعضهم مكروهاً وبعضهم سنة، وكذا المصافحة عقب العصر والصبح على ما قاله ابن عبد السلام .. أي إذا صافح من معه قبلها .. أما من ليس معه قبلها فمصافحته مندوبة لأنها عند اللقاء سنة إجماعاً، وكونه خصَّها ببعض الأحوال وفرَّط في أكثرها لا يخرج ذلك البعض عن كونها مشروعة."], [33, "صفحة 33\r"]], "pg": [24, 33]}, "533.7": {"x": [[33, "الفصل الأول في صفات الله تعالى\rوبعدُ فاعلمْ بوجوبِ المعرفةْ…"]], "pg": [33, 33]}, "533.8": {"x": [[33, "مِنْ واجبٍ لله عشرينَ صفةْ\rأي وبعد ذكر البسملة والحمدلة والصلاة والسلام فأقول لك: اعلم - أي اعرف وتيقن - أيها المكلف عشرين صفةً واجبةً لله تعالى على التفصيل؛ لأن المعرفة واجبة على كل مكلف، واحذر عن التقليد فيكون إيمانك مختلفاً فيه. فقوله: (اعلم) بمعنى (اعرف) كقوله تعالى: {لَا تَعْلَمُونَهُمُ اللَّهُ يَعْلَمُهُمْ} أي لا تعرفونهم الله يعرفهم، فلذلك أتبعه الناظم قوله بوجوب المعرفة وحينئذ فيتعدى إلى مفعول واحد. قال الفيومي في المصباح: وإذا كان (علم) بمعنى اليقين تعدى إلى اثنين، وإذا كان بمعنى عَرَفَ تعدى إلى مفعول واحد. انتهى.\rوإنما عبر الناظم بـ (اعلم) تنبيهاً للسامع على أن ما يُلقى إليه من القول يلزم حفظه؛ لأنه أصل كل خير، وإشارة إلى أن كسب العلم أفضل الأكساب، ولم يقل: (افهم) لأن الأمر بالفهم يستدعي كلاماً سابقاً يُفْهَمْ ولم يوجد هنا. ولم يقل: (ادر) لأن الأمر بالدراية يقتضي تحصيل العلم على التأني؛ لأن الدراية هي العلم الحاصل بعد التفكر، ولم يقل: (اقرأ) لأن الأمر بالقراءة يقتضي تحصيل الألفاظ، ولم يقل: (احفظ) لأن الحفظ صون الشيء عن الضياع ولو الألفاظ فقط، ولم يقل: (اسمع) لأن الأمر بالسمع يقتضي تحصيل اللفظ فقط،"], [34, "والمقصود هنا تحصيل المعاني على وجه الجزم بسرعة.\r\rوقوله: (بوجوب المعرفة) متعلق بـ (اعلم) فالباء للملابسة - أي متلبساً بوجوبها - وقوله: (من واجب) بيان للعشرين، وقوله: (عشرين) مفعول به لاعلم، وقوله: (صفة) تمييز مفسر لما وقع عليه عشرون وهو منصوب بعشرين كما قاله الشربيني، يعني أنه يجب على كل ملكف بالشرع أن يعرف عشرين صفة مفصلة، مع اعتقاد أن لله تعالى واجباتٍ وكمالاتٍ لا تتناهى، وحقيقة المعرفة هي الجزم الموافق للحق عن دليل. وأما التقليد فهو اعتقاد مضمون قول الغير وفعله وتقريره من غير معرفة دليل. وخرج بذلك التلامذة بعد أن يرشدهم الأشياخ للأدلة فهم عارفون لا مقلدون. واختُلف فيمن قلَّد في علم العقائد على ستة أقوال:\r\rالأول: الاكتفاء بالتقليد مع العصيان إن كان فيه أهلية النظر، وإلا فلا عصيان. هذا هو الذي اعتمده العلماء، قال عوض الغمراوي:\rإن رُمْتَ علمَ الأصلِ كن مجتهدا…ولا تقلدْ فالخِلافُ قد بدا\rوالقولةُ الصحيحةُ الشهيرةْ…عِصيانه إن كان ذا بصيرةْ\rقوله (إن رمت) - أي طلبت - فبابه قال، وقوله (ذا بصيرة) أي صاحب علم، ويُجمَع على بصائر بخلاف البصر الذي هو الرؤية فيجمع على أبصار."], [35, "الثاني: عدم الاكتفاء به، فيكون المقلد كافراً وعليه السنوسي. قال عبد الرحمن المنيلي: وهذا القول مبني على منع التقليد، وإن المعرفة شرط في صحة الإيمان، والحق خلافه.\r\rالثالث: الاكتفاء به مع العصيان مطلقاً أي سواء كان فيه أهلية للنظر أم لا. قال المنيلي: وهو مردود، ثم قال أيضاً: ومحل الخلاف إنما هو في المقلد الذي عنده طمأنينة نفس بأن كان بحيث لو رجع مقلِّدُه لم يرجع وإلا كان كافراً اتفاقاً.\r\rالرابع: أن من قلَّد القرآن والسنة القطعية صح إيمانه لاتباعه القطعي، ومن قلد غير ذلك لم يصح إيمانه لعدم أمن الخطأ على غير المعصوم.\r\rالخامس: الاكتفاء به من غير عصيان مطلقاً لأن النظر شرط كمال، فمن كان فيه أهلية النظر ولم ينظر فقد ترك الأولى، كذا ذكره الباجوري. وقال المنيلي: وعلى هذا يكون النظر الموصل إلى المعرفة مستحباً.\r\rالسادس: إن إيمان المقلد صحيح ويحرم عليه النظر، وهو محمول على المخلوط بالفلسفة."], [36, "فاللهُ موجودٌ قديمٌ باقي…"]], "pg": [33, 36]}, "533.9": {"x": [[36, "مخالفٌ لِلْخَلْقِ بالإطلاقِ\rوقائمٌ غنيْ وواحدٌ وَحَيْ…قادرْ مريدٌ عالمٌ بِكُلِّ شَيْ\rسميعٌ البصيرُ والمتكلمُ…لَهُ صفاتٌ سبعةٌ تنتظمُ\r\rيعني إذا أردت معرفة العشرين صفةً فأقول لك: الله موجود إلى آخرها، فالوجود أمر اعتباري يعتبره المعتبر في ذهنه أي يقدره فيه، نظيره الثوب مثلاً إذا كان في صندوق ثم أخرج منه فإنه يتصف بالظهور، فهذا الظهور ليس وصفاً زائداً على الثوب، إلا أن العقل يقدره وصفاً زائداً. هذا ما حققه العلماء من قول الأشعري - رضي الله تعالى عنه - ودليله قوله تعالى: {لَا إِلَ\rهَ إِلَّا أَنَا}، وأيضاً لو لم يكن سبحانه وتعالى موجوداً ما كان شيء من الخلق.\r\rوَالقِدَمُ: هو عدم الأوّلية لوجوده تعالى، فلم يخلق نفسه ولا خلقه غيره. قال الله تعالى: {لَمْ يَلِدْ وَلَمْ يُولَدْ}.\r\rوالبقاء: هو عدم الانقضاء لوجوده تعالى. قال تعالى: {وَيَبْقَى وَجْهُ رَبِّكَ ذُو الْجَلالِ وَالإِكْرَامِ}.\r\rوالمخالفة للحوادث: هو عدم مماثلة شيء من الحوادث له سبحانه وتعالى، فليس لحماً ولا عظماً ولا طويلاً ولا قصيراً ولا متوسطاً، فهو تعالى ذات ليس فيها شيء من صفات الحوادث، وكل ما خطر ببالك من صفات"], [37, "الحوادث لا تصدِّق إن في الله شيئاً من ذلك، وليس له مكانٌ أصلاً فليس داخلاً في الدنيا ولا خارجاً عنها. قال الله تعالى: {وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} وقال تعالى: {لَيْسَ كَمِثْلِهِ شَيْءٌ}.\r\rقوله: (بالإطلاق) أي من غير تقييد ببعض الوجوه، بمعنى أنه تعالى مخالف للخلق في جميع الوجوه، فليس سبحانه وتعالى مخالفاً للخلق في وجه، ومماثلاً في وجه آخر، تنزه الله عن ذلك.\r\rوالقيام بالنفس: هو الاستغناء عن ذات يقوم بها كقيام العرض بسائر الذوات، والاستغناء عن الموجِد، فلا ينشأ تعالى عن غيره كما نشأ وجود الحادث عنه تعالى، لأن وجوده تعالى ذاتي، فقوله: (غني) مفسر لقوله: (قائم) أي أن معنى قيام الله تعالى بنفسه استغناؤه عن كل ما سواه، وافتقار كل ما سواه إليه، ولذلك يعبَّر عن القيام بالنفس بالاستغناء المطلق. قال الله تعالى: {وَعَنَتِ الْوُجُوهُ لِلْحَيِّ الْقَيُّومِ} أي خضعت.\r\rوالوحدانية: هي عدم التعدد في الذات والصفات والأفعال، فليست ذاته مركبة من أجزاء، وليس في الخلق ذات كذاته تعالى؛ لأن الخلق جسم مركب وليس في ربنا شيء من ذلك، وليست صفاته متعددة من جنس واحد كقدرتين أو إرادتين، بل له قدرة واحدة"], [38, "يوجِد بها ويُعدِم، وليس لأحد صفة كصفاته تعالى، ولا مؤثرَ معه في فعل من الأفعال، بل هو الموجِد للأفعال كلها فيخلق الطاعة والمعصية والنفع والضر والغنى والفقر، وليست النار محرقة، ولا السكين قاطعة، ولا الطعام مشبعاً، فالله هو الخالق وحده، لكن جعل بمراده هذا سبباً في هذا، ويجوز أن لا يوجد الإحراق مع النار. قال الله تعالى: {وَإِلَهُكُمْ إِلَهٌ وَاحِدٌ لَّا إِلَهَ إِلَّا هُوَ الرَّحْمَنُ الرَّحِيمُ}.\r\rوالحياة: صفة تصحح للذات التي قامت بها أن تعلم وتقدر، قال الله تعالى: {وَتَوَكَّلْ عَلَى الْحَيِّ الَّذِي لَا يَمُوتُ}.\r\rوالقدرة: صفة تصحح للذات أن تفعل وتترك، قال الله تعالى: {وَاللَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ}.\r\rوالإرادة: صفة تقتضي ترجيح أحد الجائزين على الآخر، قال تعالى: {إِنَّ رَبَّكَ فَعَّالٌ لِمَا يُرِيدُ}.\r\rوالعلم: صفة ينكشف بها الشيء عند تعلقها به، قال الله تعالى: {إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ}، وأن الله قد أحاط بكل شيء علماً، فقول الناظم (عالم بكل شيء) أي سواء كان مجملاً أو مفصلاً، ممكناً كان أو ممتنعاً أو واجباً.\r\rالسمع والبصر: صفتان يزيد الانكشاف بهما على الانكشاف بالعلم، قال الله تعالى: {وَهُوَ السَّمِيعُ الْبَصِيرُ}."], [39, "والكلام: هو صفة أزلية قائمة بذاته تعالى يُعبَّر عنها بالنظم المخصوص المسمى بالقرآن وبكلام الله تعالى أيضاً، قال الله تعالى: {وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا}، فكلامه تعالى ليس بحرف ولا صوت، بل بكلام قديم لا أول له ولا آخر له. وأما معنى قوله تعالى: {وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا} أي أسمعه كلامه القديم بجميع أعضائه من جميع الجهات، وكان جبريل معه فلم يسمع ما كلَّم الله به موسى، وسمع كلامَه القديم أيضاً سيدُنا محمد صلى الله عليه وسلم ليلة الإسراء. وليس الله في مكان ولا جهة، بل المكان للسامع الحادث، ويُسمع كلامه القديم أيضاً في القيامة والجنة بغير صوت ولا حرف ولا قرب ولا بعد، كما نرى ذاته تعالى في الآخرة من غير شبه ولا مثل ولا داخل الجنة ولا خارجاً عنها.\r\rفهذه ثلاث عشرة صفة، وإنما ذكرها الناظم بأسماء الصفات المستندة لله تعالى تبعاً للكتاب والسنة لورودها فيهما. كذلك ولأن المقصود في اعتقاد المكلف اتصاف الله تعالى بها، وتسهيلاً على العوام كما قال محمد الفضالي، وإذا أردت أن تعلم صفاته تعالى للعامة فأت بها أسماءً مشتقة من الصفات المذكورة فيقال: الله تعالى موجود قديم باق مخالف للحوادث، مستغنٍ عن كل شيء، واحد قادر مريد عالم حي سميع بصير متكلم.\r\rقال البيجوري: قوله: (فأت بها) أي بدوالِّها، وقوله: (أسماء مشتقة) أي حال كون تلك الدوال أسماء مشتقة، وإنما"], [40, "كانت تلك الأسماء دالة على الصفات لأنها دالة على الذات المتصفة بهذه الصفات، بل نقل عن الأشعري أن مدلول القادر مثلاً نفس الصفة التي هي القدرة من حيث اتصاف الذات بها، لكن المشهور عند الأشاعرة أن مدلوله الذات باعتبار اتصافها بتلك الصفة، والحاصل أن الأقسام ثلاثة: ما يدل على الذات ويشعر بالصفة كقادر، وما يدل على الذات ولا يشعر بالصفة كلفظ الجلالة، وما يدل على الصفة فقط كالقدرة، أفاده اليوسي. انتهى.\r\rقوله: (غني) بسكون الياء وكذا قوله: (وحي) وقوله: (قادر) بسكون الراء وقوله: (شي) بحذف الهمزة وقوله: (والمتكلم) بسكون التاء وكلها للوزن، ومعنى قول الناظم: (له صفات سبعة تنتظم) أي لله سبحانه تبارك وتعالى سبع صفات تتوالى في بيت واحد من غير مفارقة بينها، كما نُظم الخرز في خيط واحد، وتسمى هذه الصفات السبع بالمعاني، وهي كل صفة وجودية قائمة بالذات أوجبت لموصوفها حكماً، بحيث لو كشف عنا الحجاب لرأيناها كما هو شأن الموجودات، ويسمى ذلك الحكم معنوية؛ لأنها منسوبة للمعاني، فالمعنوية هي كونه تعالى قادراً وكونه مريداً وكونه عالماً وكونه حياً وكونه سميعاً وكونه بصيراً وكونه متكلماً، فالمعاني كالأصل والمعنوية كالفرع؛ لأن المعاني وجودية تعقل، والمعنوية أحوال لا تكون كذلك إلا"], [41, "بالنسبة لمعانيها التي أوجبتها.\r\rفإن قلتَ: لِمَ قال الناظم: (له صفات سبعة تنتظم) مع أنه قال أولاً: (عشرين صفة) ولم يستوف عددها؟ وما فائدة ذكر هذه الصفات السبع مع كونها داخلة في الأسماء المذكورة أولاً، فلا حاجة إلى ذكرها؟ قلت: إنما قال ذلك لحكمة لطيفة، وهي الاهتمام بشأن هذه الصفات السبع، وإنما ذكرها الناظم مع كونها داخلة في الأسماء السبعة لأن المقصود في هذا العلم ذكر العقائد على وجه التفصيل، لأن خطر الجهل فيه عظيم، والرد على قول المعتزلة فإنهم أنكروها فقالوا: إنه تعالى قادر بذاته، مريد بذاته من غير قدرة ولا إرادة وهكذا إلى آخرها. وأما جمهور أهل السنة فقالوا: إنه تعالى قادر ومريد بصفات وجودية قائمة بالذات، يصح أن يرى. وبالجملة فنقول كمن قال:\r\rاعتصامُ الورى بمغفرتكْ…عَجَزَ الواصفون عن صِفَتِكْ\r\rتُبْ علينا فإننا بَشَرٌ…ما عرفناكَ حَقَّ معرفتِكْ\r\rثم اعلم أن المعتزلة لم يقولوا بثبوت المعنوية كما قد أوهمه بعض العبارات، أي لم يقولوا إن الله قادر بصفات معنوية، وإنما قالوا قادر بذاته من غير قدرة كما تقدم، ولم يكفروا بذلك لأنهم أثبتوا القادرية. ثم شرع الناظم في بيان صفات المعاني فقال:"], [42, "فقدرةٌ إرادةٌ سمعٌ بصرْ…"]], "pg": [36, 42]}, "533.10": {"x": [[42, "حياةٌ العلمُ كلامٌ استمرْ\r\rأي إذا أردت تفصيل صفات المعاني السبعة فأقول لك: هي قدرة إلى آخرها، وهذه الصفات السبعة كل واحدة لها سبعة مطالب إلا الحياة وحدها فلها ستة مطالب، فالقدرة لها سبعة مطالب: نشهد ونعتقد أن قدرة الله موجودة وقديمة وباقية ومخالفة لقدرتنا الحادثة، وغنية عن المخصص، وواحدة وعامة التعلق بجميع الممكنات. والإرادة لها سبعة مطالب: نشهد ونعتقد أن إرادة الله موجودة وقديمة وباقية ومخالفة لإرادتنا الحادثة، وغنية عن المخصص، وواحدة وعامة التعلق بجميع الممكنات. والسمع له سبعة مطالب: نشهد ونعتقد أن سمع الله موجود وقديم وباق ومخالف لسمعنا الحادث، وغني عن المخصص، وواحد وعام التعلق بجميع الموجودات سواء كانت ذواتاً أو أصواتاً، فذاتك مثلاً منكشفة بسمعه تعالى، والبصر له سبعة مطالب: نشهد ونعتقد أن بصر الله موجود وقديم وَبَاقٍ ومخالف لبصرنا الحادث، وغني عن المخصص، وواحد وعام التعلق بجميع الموجودات، والحياة لها ستة مطالب: نشهد ونعتقد أن حياة الله موجودة وقديمة وباقية ومخالفة لحياتنا الحادثة، وغنية عن المخصص، وواحدة ولا تعلق لها بشيء. والعلم له سبعة مطالب: نشهد ونعتقد أن علم الله موجود وقديم وباق ومخالف لعلمنا الحادث، وغني عن"], [43, "المخصص، وواحد وعام التعلق بجميع الواجبات والجائزات والمستحيلات. والكلام له سبعة مطالب: نشهد ونعتقد أن كلام الله موجود وقديم وباق ومخالف لكلامنا الحادث، وغني عن المخصص، وواحد وعام التعلق بجميع الواجبات والجائزات والمستحيلات، فالواجب ذات الله وصفاته وأسماؤه، والمستحيل كالشريك والولد والنقائص، والجائز كذواتنا وصفاتنا وأسمائنا، فيدل كلام الله على الواجب كـ: {أَنَا اللَّهُ لَا إِلَ\rهَ إِلَّا أَنَا}، وعلى المستحيل كـ: {إِنَّ اللَّهَ ثَالِثُ ثَلاثَةٍ}، وعلى الجائز كـ: {وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ}، وقوله: (استمر) أي دام كلامه تعالى ولا ينقطع، وليس معنى {وَكَلَّمَ اللَّهُ مُوسَى تَكْلِيمًا} أنه ابتدأ الكلام له بعد أن كان ساكتاً فبعدما كلمه انقطع كلامه وسكت، تنزه الله عن ذلك تنزهاً عظيماً، وإنما المعنى أنه تعالى بفضله أزال المانع عن موسى عليه السلام، وخلق له سمعاً وقوة حتى أدرك به كلامه القديم ثم منعه بعد وَرَدَّهُ إلى ما كان عليه قبل سماع كلامه، وهذا معنى كلامه تعالى لأهل الجنة.\r\rأخرج الطبراني عن ابن جبير عنه عليه الصلاة والسلام أنه قال: (أوحى الله إلى موسى عليه السلام أني جعلت فيك عشرة آلاف سمع حتى سمعت كلامي، وعشرة آلاف لسان حتى أجبتني). وأخرج القضاعي أن الله كلَّم موسى بمائة ألف وأربعين ألف كلمة، ومعنى ذلك أنه فهم"], [44, "معنى يعبر عنه بهذه العدة بحسب كشف الحجاب لا التبعيض في الصفة. وروي أن موسى عليه السلام عند قدومه من المناجاة كان يسد أذنيه لئلا يسمع كلام الخلق، إذ صار عنده كأقبح ما يكون من أصوات البهائم المنكرة، فلم يستطع سماعه بسبب ما ذاق من اللذات التي لا يحاط بها عند سماع كلام من ليس كمثله شيء، وصار يسمع دبيب النملة السوداء في الليل المظلم من مسيرة عشرة فراسخ. وقد أشرق وجهه بالنور، فما رآه أحد إلا عَمِيَ، فكان يمسح الرائي وجهه مما عليه، فيرد الله عليه بصره، فتبرقع لئلا تذهب أبصار الناس عند رؤيته، وبقي البرقع على وجهه إلى أن مات، ولولا أنه سبحانه وتعالى ينسيه ما ذاق عند مناجاته مما لا يقدر على وصفه لما أمكن أن يأنس إلى شيء من المخلوقات أبداً، ولما انتفع به أحد، فسبحانه من لطيف، ما أوسع كرمه وأعظم جلاله!\r\rوالحاصل أن صفات المعاني السبعة تنقسم على أربعة أقسام: قسم لا يتعلق بشيء وهو: الحياة، وقسم يتعلق بالممكنات وهي: القدرة والإرادة، وقسم يتعلق بالموجودات وهي: السمع والبصر، وقسم يتعلق بالواجبات والجائزات والمستحيلات وهو: العلم والكلام.\r\rوالتعلق على ثلاثة أقسام: تعلق تأثير، وتعلق انكشاف، وتعلق دلالة. فتعلق التأثير تعلق القدرة والإرادة، فتتعلق القدرة بالمعدوم فتوجده وبالموجود فتعدمه، وتتعلق الإرادة بالممكن فتخصصه ببعض ما يجوز عليه كالطول"], [45, "والقصر وغيرهما، وتعلق الانكشاف تعلق السمع والبصر والعلم، فيسمع تعالى ذاته وجميع صفاته الوجودية من قدرة وسمع وغيرهما، ولا نعرف كيفية التعلق، ويسمع ذواتنا وصفاتنا، ويبصر تعالى ذاته وصفاته الوجودية من قدرة وبصر وغيرهما، ولا ندري كيفية التعلق، ويبصر ذواتنا وصفاتنا أيضاً، ويعلم ذاته تعالى وصفاته بعلمه، ويعلم الموجودات كلها من الممكنات والمعدومات كلها بعلمه، ويعلم المستحيلات بمعنى أنه يعلم انتفاءها لا ثبوتها، وإلا لانقلب العلم جهلاً تنزه الله عنه. وتعلق الدلالة تعلق الكلام، بمعنى أنه لو كشف عنا الحجاب وسمعنا الكلام القديم لفهمناها منه.\r\rثم اعلم أن الممكنات على أربعة أقسام: ممكن موجود بعد عدم كالسماوات والأرض، وممكن معدوم بعد وجود كالذي انقضى، وممكن سيوجد كالقيامة، وممكن علم الله أنه لا يوجد ككفر الأنبياء مثلاً.\r\rفائدة: قال الشرقاوي: والحاصل أن أقسام العدم أربعة: عدم المخلوقات الأزلي لا تتعلق به القدرة والإرادة اتفاقاً لأنه ليس ممكناً بل واجب، وعدمها فيما لا يزال قبل وجودنا يتعلقان به؛ بمعنى أنه في قبضتهما إن شاءتا أبقتاه وإن شاءتا أزالتاه وجعلتا الوجود مكانه، وعدمها بعد وجودها تتعلقان به، وعدم الممكنات التي علم الله أنها لا توجد"], [46, "كإيمان أبي جهل تتعلقان به بالنظر إلى ذاته، واستحالة وقوعه المقضية لكون عدمه واجباً إنما هي عارضة، والعارض لا ينافي الإمكان الذاتي، وقيل لا تتعلقان نظراً إلى استحالة وقوعه. انتهى. قلت: هذا الخلاف ليس حقيقياً بل هو لفظي، فحمل قول من قال إنهما تتعلقان به على أنهما تتعلقان تعلقاً صلوحياً، وحمل قول من قال إنهما لا تتعلقان به على أنهما لا تتعلقان تعلقاً تنجيزياً. انتهى.\r\rفرع\rاختلف العلماء في الإدراك، أي إدراك المذوقات والمشمومات والملموسات، هل له تعالى إدراك أو لا؟ فذهب القاضي وإمام الحرمين ومن وافقهما إلى أن له تعالى إدراكاً زائداً على العلم يتعلق بكل موجود، كصفتي السمع والبصر، بمعنى أن إدراكه تعالى لتلك الأمور بإدراك زائد على العلم. وذهب جماعة من الأئمة إلى نفيه لإغناء صفة العلم عنه؛ لأن إحاطة العلم بمتعلقاتها كافية عنه، فيكون إدراكه تعالى لتلك الأمور بعلمه، وذهب المقترح وابن التلمساني وبعض المتأخرين إلى الوقف والتفويض لتعارض الأدلة، فهؤلاء القوم لا يجزمون بثبوت الإدراك ولا يجزمون بنفيه، وهذا القول أسلم وأصح من القولين الأولين. وأما قوله تعالى: {لَّا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ} فمعناه: يحيط بها علماً وسمعاً وبصراً. وكما اختُلف في الإدراك اختُلف في الكون مدركاً، والأصح الوقف عن ذلك، قاله البيجوري وغيره."], [47, "وجائزٌ بفضلهِ وعدلهِ…"]], "pg": [42, 47]}, "533.11": {"x": [[47, "تركٌ لِكُلِّ ممكنٍ كفعلهِ\r\rأي يجب على كل مكلف أن يعتقد أن الله تعالى يجوز أن يخلق الخير والشر، ويجوز أن يخلق الإسلام في زيد والكفر في عمرو، والعلمَ في أحدهما والجهلَ في الآخر، وإثابتُه تعالى للمطيع فضلٌ منه، وعقابُه للعاصي عدلٌ منه؛ لأنه النافع الضار، وإنما هذه الطاعة والمعاصي علامةٌ على أن الله تعالى يثيب ويعاقب من اتصف بهما، فمن أراد سعادته وفَّقه لطاعته، ومن أراد شقاوته خلق فيه المعصية. فجميع الأمور من أفعال الخير والشر بخلق الله تعالى؛ لأن الله تعالى خلق العبد وما عَمِلَهُ، قال تعالى: {وَاللَّهُ خَلَقَكُمْ وَمَا تَعْمَلُونَ}، فهو الذي يصدر عنه النفع والضر، فلا خير ولا شر ولا نفع ولا ضر إلا وهو منسوب إليه سبحانه وتعالى، فحينئذ ينبغي للعبد أن يكون اعتمادُه عليه تعالى وحده، فلا يرجو ولا يخشى أحداً غيره تعالى.\r\rوحُكي عن سيدنا موسى عليه وعلى نبينا أفضل الصلاة والسلام أنه شكا ألم سنِّه إلى الله تعالى، فقال: (خذ الحشيشة الفلانية، وضعها على سنك)، فسكن الوجع في الحال، ثم بعد مدة عاد ذلك الوجع فأخذ تلك الحشيشة ووضعها على سنه فزاد الوجع أضعاف ما كان، فاستغاث إلى الله تعالى فقال: (إلهي، ألست أمرتني بهذا ودللتني عليه؟!) فقال تعالى: (يا موسى أنا الشافي وأنا"], [48, "المعافي وأنا الضار وأنا النافع، قصدتني في المرة الأولى فأزلتُ مرضك، والآن قصدت الحشيشة وما قصدتني؟!) اهـ.\r\rولما فرغ الناظم مما يتعلق بمولانا شرع فيما يتعلق برسله فقال:"], [51, "صفحة 51\rالفصل الثاني في الأنبياء والرسل عليهم الصلاة والسلام\r"]], "pg": [47, 51]}, "533.12": {"x": [[51, "أرسلَ أنبيا ذوي فطانةْ…بالصدقِ والتبليغِ والأمانةْ\rأي يجب على كل مكلف أن يعتقد أن الله أرسل إلى المكلفين أنبياء مرسلين موصوفين بصفات أربعة واجبة في حقهم عليهم الصلاة والسلام، وهي: الفطانة بفتح الفاء، والصدق، والتبليغ، والأمانة.\rفمعنى الفطانة الذكاء والحذق، بحيث يكون فيهم قدرة إلى إلزام الخصوم ومحاججتهم وإبطال دعاويهم. ومعنى الصدق مطابقة خبرهم للواقع وضده الكذب، هذا هو معنى الصدق، وأما معنى الحق فهو مطابقة الواقع للخبر وضده الباطل. ومعنى التبليغ إيصال ما أمروا بإيصاله للخلق. ومعنى الأمانة عصمتهم ظاهراً وباطناً من محرم أو مكروه، بحيث يستحيل وقوعه منهم.\rواعلم أن جميع ما قيل في حق الرسل يقال في حق الأنبياء إلا التبليغ وضده، فإنهما خاصان بالرسل، إذ النبي الذي ليس برسول لا يبلغ شيئاً، نعم، يجب أن يُخبر بأنه نبي ليُحترم ويُعظَّم. قوله: (أنبيا) بحذف الهمزة الممدودة، وقوله: (ذوي فطانة) بفتح الذال وكسر الواو، أي أصحاب فطانة وهو صفة لأنبيا منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم."], [52, "وجائزٌ في حقهمْ من عَرَضِ…"]], "pg": [51, 52]}, "533.13": {"x": [[51, "أرسلَ أنبيا ذوي فطانةْ…بالصدقِ والتبليغِ والأمانةْ\rأي يجب على كل مكلف أن يعتقد أن الله أرسل إلى المكلفين أنبياء مرسلين موصوفين بصفات أربعة واجبة في حقهم عليهم الصلاة والسلام، وهي: الفطانة بفتح الفاء، والصدق، والتبليغ، والأمانة.\rفمعنى الفطانة الذكاء والحذق، بحيث يكون فيهم قدرة إلى إلزام الخصوم ومحاججتهم وإبطال دعاويهم. ومعنى الصدق مطابقة خبرهم للواقع وضده الكذب، هذا هو معنى الصدق، وأما معنى الحق فهو مطابقة الواقع للخبر وضده الباطل. ومعنى التبليغ إيصال ما أمروا بإيصاله للخلق. ومعنى الأمانة عصمتهم ظاهراً وباطناً من محرم أو مكروه، بحيث يستحيل وقوعه منهم.\rواعلم أن جميع ما قيل في حق الرسل يقال في حق الأنبياء إلا التبليغ وضده، فإنهما خاصان بالرسل، إذ النبي الذي ليس برسول لا يبلغ شيئاً، نعم، يجب أن يُخبر بأنه نبي ليُحترم ويُعظَّم. قوله: (أنبيا) بحذف الهمزة الممدودة، وقوله: (ذوي فطانة) بفتح الذال وكسر الواو، أي أصحاب فطانة وهو صفة لأنبيا منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم."], [52, "وجائزٌ في حقهمْ من عَرَضِ…"]], "pg": [51, 52]}, "533.14": {"x": [[52, "بغيرِ نقصٍ كخفيفِ المرضِ\r\rأي يجب على كل مكلَّف أن يعتقد أن الجائز في حق الرسل والأنبياء عليهم الصلاة والسلام وقوع الأعراض البشرية التي لا تؤدي إلى نقص في مراتبهم العلية، كالمرض الخفيف ونحوه، كالأكل والشرب والبيع والشراء والسفر والقتل والجروح والتزوج ودخول الأسواق، والنوم لكن بأعينهم فقط دون قلوبهم، وخروج المني لكن بامتلاء الأوعية فقط دون الاحتلام لأنه من تلاعب الشيطان، فلا يجوز للشيطان أن يتسلط عليهم، والدليل على جواز ذلك المشاهدة لأن من حضرها شاهد الأعراض البشرية التي وقعت بهم، ومن لم يحضرهم بلغه الخبر المتواتر على ذلك.\r\rوأما الأعراض المستحيلة عليهم كالبرص والجذام وَالعِنَّةِ وسواد الجسم والصمم والعمى والبكم والشلل والعرج والعور واللكنة والشتر والشرم والثرم وكل صفة دنيئة مستحيلةٌ عليهم لأنها نقص، فاللكنة ثقل اللسان، والشتر بالشين المعجمة والتاء المثناة فوق هو انقلاب في جفن العين، والشرم بالشين والراء المهملة هو شق الأنف، والثرم بالثاء المثلثة والراء هو انكسار الثنية أي مقدم الأسنان. فقولنا: (الأعراض) خرج بذلك صفاته سبحانه تبارك وتعالى، فلا تجوز عليهم خلافاً للنصارى حيث وصفوا سيدنا عيسى"], [53, "بها. وقولنا: (البشرية) أخرج صفات الملائكة فلا تجوز عليهم أيضاً. وقولنا: (التي لا تؤدي إلى نقص…الخ) احتراز عن الأعراض التي تؤدي إلى ذلك كما تقدم خلافاً لليهود والجهلة في وصفهم لهم بالنقص، كوصفهم داود بالحسد. فتحصل أن النصارى أفرطوا أي جاوزوا حتى وصفوا عيسى عليه السلام بصفات الألوهية، وأن اليهود فرَّطوا أي قصروا حتى وصفوا الرسل بالنقائص، وهذه الأمة لم تُفرِط ولم تفرِّط وكان بين ذلك قواماً أي اعتدالاً.\r\rثم اعلم أنه لم يكن نبي من الأنبياء أنثى ولا رقيقاً، وأما القول بنبوة ستة نفر من الإناث فهو مرجوح، وتلك الست هن: مريم وآسية وحواء وأم موسى واسمها يوحانذ بالذال المعجمة وهاجر وسارة. وأما لقمان فليس نبياً لأنه كان عبداً ثم عَتَقَ، بل كان تلميذ الأنبياء لأنه ورد أنه كان تتلمذ لألف نبي كما قال عوض الغمرواي:\r\rولم يكن في الأنبيا أنثى ولا…عبدٌ ومجنونٌ وشخصٌ خُبِلَا\r\rلقمانُ ذو القرنين كانا أتقيا…ولم يكونا في الأنام أنبيا\r\rقوله: (خُبِلَا) بالبناء للمجهول أي فسد عضوه، أو ذهب عقله، وقوله: (في الأنام) أي عند العلماء.\r\rتنبيه: قوله: (وجائز) مبتدأ، وقوله: (في حقهم) متعلق بمحذوف صفة مخصصة له كقول ابن مالك في الخلاصة"], [54, "(ورجل من الكرام، عندنا)، قوله: (من عرض) من خبره بمعنى بعض، وهو أقرب إلى مذهب الزمخشري الجاعل من التبعيضية اسماً بمعنى بعض، وهذا أحسن في المعنى، ويحتمل أن تكون للابتداء مثل قوله تعالى: {يُحَلَّوْنَ فِيهَا مِنْ أَسَاوِرَ}، ويجوز أن يكون قوله في حقهم متعلقاً بجائز، فحينئذ يكون قوله (جائز) مبتدأ نكرة من غير اعتماد على نفي واستفهام ومن غير تخصيص بوصف، وهو قليل جداً خلافاً للأخفش والكوفيين، فإنهم حكموا بجواز ذلك من غير قبح، وأما البصريون فمنعوه."], [55, "عِصمتُهم كسائرِ الملائكةْ…"]], "pg": [52, 55]}, "533.15": {"x": [[55, "واجبةٌ وفاضَلوا الملائكةْ\r\rأي يجب على كل مكلف أن يعتقد وجوب عصمة جميع الأنبياء والمرسلين، كوجوب العصمة لجميع الملائكة عليهم الصلاة والسلام. والعصمة لغةً: مطلق اللفظ، واصطلاحاً: حِفْظُ الله لهم من الذنب مع استحالة وقوعه. قوله: (وفاضلوا الملائكة) أي أن الأنبياء والمرسلين أفضل من الملائكة، فأفضلهم سيدنا محمد صلى الله عليه وسلم فيليه سيدنا إبراهيم فسيدنا موسى فسيدنا عيسى فسيدنا نوح، وهؤلاء هم أولو العزم أي الصبر وتحمل المشاق، فيجب معرفة ترتيب هؤلاء الخمسة كما علمت في الأفضلية، وليس آدم منهم لقوله تعالى: {وَلَمْ نَجِدْ لَهُ عَزْمًا}. ويلي أولي العزم بقية الرسل ثم الأنبياء غير الرسل، مع تفاوت مراتبهم عند الله، ثم رؤساء الملائكة كسيدنا جبريل ونحوه كحملة العرش، وهم أربعة الآن فإذا كان يوم القيامة أيدهم الله بأربعة أخرى، قال تعالى: {وَيَحْمِلُ عَرْشَ رَبِّكَ فَوْقَهُمْ يَوْمَئِذٍ ثَمَانِيَةٌ}، وكـ (الكَروبيين) بفتح الكاف وتخفيف الراء، وهم ملائكة حافون بالعرش طائفون به، لُقبوا بذاك لأنهم متصدرون بالدعاء لرفع الكرب عن الأمة، وقيل غير ذلك. ثم أولياء البشر غير الأنبياء كسيدنا أبي بكر وعمر وبقية الصحابة، لقوله صلى الله عليه وسلم: إن الله اختار أصحابي على العالمين سوى النبيين والمرسلين. ثم عوام الملائكة ثم عوام البشر."], [56, "هكذا قال بعض العلماء، لكن قال تاج الدين السبكي: ليس تفضيل البشر على المَلَكِ مما يجب اعتقاده ويضر الجهل به، والسلامة في السكوتِ عن هذه المسألة، والدخولُ في التفضيل بين هذين الصنفين الكريمين على الله تعالى من غير دليل قاطع دخولٌ في خطر عظيم، وحكمٌ في مكان لسنا أهلاً للحكم فيه. اهـ."], [57, "والمستحيلُ ضِدُّ كُلِّ واجبِ…"]], "pg": [55, 57]}, "533.16": {"x": [[57, "فاحفظْ لخمسينَ بحكمٍ واجبِ\r\rأي يجب على كل مُكَلَّفٍ أن يعتقد أن المستحيلَ على الله ورسوله ضِدُّ كل صفة واجبة لله ولرسله، فعدد المستحيلات كعدد الواجبات. وقد نظم ذلك عوض بن أحمد الغمراوي فقال:\rأضدادُها عشرونَ مِثْلُهَا أَتَتْ…لكل وصفٍ ناقضٌ فيما ثَبَتْ\rوهي العَدَمْ حدوثُهُ كذا الفَنَا…وكونُه مماثِلاً جَلَّ لنا\rوعدمُ القِيَامِ أو تَعدادُهُ…وَعَجْزُهُ عن مُمْكِنٍ إيجادُهُ\rكذا كراهةٌ وجهلٌ صَمَمُ…والموتُ أيضاً والعمى وَالبَكَمُ\rوما بَقِيْ مِنْ ضِدِّهَا قد بانا…مِنْ ذا فليس يَقبل البيانا\rوأوجِبَنْ للأنبيا الأمانةْ…والصدقَ والتبليغَ والفَطانةْ\rوضدُّها أَجِلْهُ كالخيانةْ…كذا الكذبْ كِتمانُهم دِيانةْ\rبَلَادَةٌ فذا الذي قد وَجَبَا…لله والرسلِ الكرامِ النُّجَبَا\rقوله: (أضدادها) أي أضداد الواجبات التي تقدم ذكرها، فالضمير فيه عائد على الواجبات، وكذا الضمير في قوله: (مثلها) وقوله: (مماثلاً جل لنا) أي مماثلته تعالى لنا، فالجار والمجرور متعلق بمماثلاً، وقوله: (جل) أي ارتفع مولانا وتنزه عن ذلك. وقوله: (بلادة) هي ضد الفطانة فيقال: (بَلُدَ الرجل) بضم عين الفعل بلادةً فهو بليد أي غير ذكي ولا فطن. وقوله: (فذا الذي قد وجبا) أي فهذا"], [58, "المذكور أولاً قبل هذه الأبيات هو الواجب لله تعالى. وقوله: (النجبا) بضم النون وفتح الجيم جمع نجيب ككريم وكرماء وزناً ومعنى، فهو مفسر للكرام.\r\rتنبيه: قول الناظم: (فاحفظ لخمسين بحكم واجب) أي فَأَدِّ عن ظهر قلبك خمسين عقيدة حال كونك متلبساً بحكم واجب شرعي. قوله: (فاحفظ) بفتح الفاء من باب سمع، واللام في قوله لخمسين زائدة، و (خمسين) مفعول به لاحفظ، ويجوز أن يكون اللام بمعنى إلى كقوله تعالى: {وَلَوْ رُدُّوا لَعَادُوا لِمَا نُهُوا عَنْهُ}، وحينئذ فمفعول احفظ محذوف والتقدير فاحفظ العقائد الواجب عليه حفظها إلى خمسين. وقوله: (بحكمٍ) متعلق باحفظ، أي فقد عرفت أن الواجب لله عشرون، والمستحيل عليه كذلك، والواجب للرسل أربعة، والمستحيل عليهم كذلك، والجائز لله واحد، والجائز للرسل كذلك، فالجملة خمسون."], [59, "تفصيلُ خمسةٍ وعشرينَ لَزِمْ…"]], "pg": [57, 59]}, "533.17": {"x": [[59, "كُلَّ مكلَّفٍ فَحَقِّقْ واغتنمْ\r\rأي يجب على كل مكلف أن يعرف تفصيل خمسة وعشرين من المرسلين، ومعنى لزم وجب وفرض. قوله: (كل) مفعول به للزم؛ لأن لزم إذا كان بمعنى وجب فهو متعدٍّ، وأما إذا كان بمعنى ثبت ودام فهو قاصر. وقوله: (فحقق) أي فتيقَّن عدد هؤلاء الرسل الذين هم خمسة وعشرون، وقوله: (واغتنم) أي اكتسب واربح واطلب عددهم.\r\rواعلم أن ما ذكره الناظم مخالف لما ذكره السحيمي في كتابه المسمى بالمقتدى، وسيأتي ذلك عليك قريباً إن شاء الله تعالى. قال السحيمي: يجب على المؤمن أن يعلم ويُعلِّم صبيانه ونساءه وخدَّامه أسماء الرسل المذكورين في القرآن، حتى يؤمنوا بهم ويصدقوا بجميعهم تفصيلاً، ولا يظنوا أن الواجب عليهم الإيمان بسيدنا محمد فقط، فإن الإيمان بجميع الأنبياء سواء ذُكِرَ اسمهم في القرآن أو لم يذكر واجب على كل مكلف، وهم أي المذكورون في القرآن ستة وعشرون أو خمسة وعشرون ونظمتها من بحر البسيط فقلت:\r\rأسماءُ رُسْلٍ بقرآنٍ عليكَ تَجِبْ…كآدمٍ زكريَّا بعدَ يونُسِهِمْ\r\rنوحٍ وإدريسَ إبراهيمَ وَاليَسَعْ…إسحاقَ يعقوبَ إسماعيلَ صالحِهِمْ\r\rأيوبَ هارونَ موسى مَعْ شُعَيْبِهِمُ…داودَ هودٍ عزيرٍ ثُمَّ يُوْسُفِهِمْ"], [60, "لوطٍ وإلياسَ ذي الكِفْلِ أو اتَّحَدَا…"]], "pg": [59, 60]}, "533.18": {"x": [[60, "يحيى سليمانَ عيسى مَعْ مُحَمَّدِهِمْ\r\rومعنى (أو اتحدا) أن ذا الكفل قيل هو إلياس، وقيل يوشع، وقيل زكريا، وقيل حزقيل ابن العجوز لأن أمه كانت عجوزاً فسألت الله الولد بعد كبرها فوهب لها حزقيل. اهـ.\r\rقال الجلال المحلي: سمِّي \"ذا الكفل\" لأنه تكفل بصيام جميع نهاره وقيام جميع ليله. اهـ.\r\rقال البيجوري: والصحيح في الأنبياء والمرسلين الإمساك عن حصرهم في عدد؛ لأنه ربما أدى إلى إثبات النبوة أو الرسالة لمن ليس كذلك في الواقع، أو إلى نفي ذلك عمن هو كذلك في الواقع، فيجب التصديق بأن لله رسلاً وأنبياء على الإجمال إلا خمسة وعشرين، فيجب معرفتهم تفصيلاً. اهـ. ثم أخذ الناظم في بيان أسمائهم على ترتيب وجود مسمياتهم في أربعة أبيات فقال:"], [61, "هُمْ آدَمٌ إدريسُ نوحٌ هودٌ معْ…"]], "pg": [60, 61]}, "533.19": {"x": [[61, "صالحْ وإبراهيمُ كُلٌّ مُتَّبَعْ\rلوطٌ وإسماعيلُ إسحاقُ كذا…يعقوبُ يوسفُ وأيوبُ احتذى\rشعيبُ هارونُ وموسى وَاليَسَعْ…ذو الكفلِ داودُ سليمانُ اتَّبَعْ\rإلياسُ يونُسْ زكريَّا يحيى…عيسى وَطَهَ خَاتِمٌ دَعْ غَيّا\r\rأي أول الخمسة والعشرين آدم أبو البشر، وثانيهم إدريس الذي هو حي في السماء الرابعة أو السادسة أو السابعة، أو في الجنة أدخل فيها بعد أن أذيق الموت وأحيي ولم يخرج منها وهو جد أبي نوح، وثالثهم نوح الذي أنجاه الله من الغرق بالطوفان، ورابعهم هود الذي أنجاه الله من الريح الصرصر، أي الشديد صوتها، التي أهلكت عاداً، وخامسهم صالح الذي أنجاه الله من صيحة جبريل التي أهلكت ثمود، وسادسهم إبراهيم بن تارَخ بفتح الراء، وسابعهم لوط الذي أنجاه الله من الريح التي ترمي الكافرين بالحجارة الصغار، وثامنهم إسماعيل بن إبراهيم الذي أمه هاجر، وتاسعهم إسحق بن إبراهيم أيضاً الذي أمه سارة، وعاشرهم يعقوب بن إسحق، وحادي عشرهم يوسف بن يعقوب، وثاني عشرهم أيوب بن أموص بن رزاح بن روم بن عيص بن إسحق عليه السلام، وثالث عشرهم شعيب خطيب الأنبياء، ورابع عشرهم هارون بن عمران، وخامس عشرهم موسى بن"], [62, "عمران أيضاً فهو أخو هارون الشقيق وأمهما يوحانذ، وسادس عشرهم يسع بن أقطوب ابن العجوز، وسابع عشرهم ذو الكفل، وثامن عشرهم داود بن إيشا، وتاسع عشرهم سليمان بن داود، وعشرونهم إلياس بن أخي موسى، والحادي والعشرون يونس بن متى الذي أنجاه الله من الغم، والثاني والعشرون زكريا بن أذن، والثالث والعشرون يحيى بن زكريا الذي هو سيد الشهداء يوم القيامة وقائدهم إلى الجنة وذابح الموت يوم القيامة يضجعه ويذبحه بشفرة في يده والناس ينظرون إليه، وإنما اختص دون غيره من الأنبياء بذبح الموت لاشتقاق اسمه من ضده، والرابع والعشرون عيسى بن مريم وهو الذي خلقه الله تعالى بغير أب، والخامس والعشرون نبينا محمد صلى الله عليه وسلم، وهو المعنيّ بقول الناظم (وطه) لأنه اسم من أسماء نبينا محمد صلى الله عليه وسلم قيل معناه بدر؛ لأن الطاء بتسعة والهاء بخمسة فالجملة أربعة عشر، فالبدر هو ليلة أربعة عشر، وقيل معناه شفاء من كل داء، وعن جعفر الصادق: وقيل معناه طوبى لمن اهتدى، وقيل معناه مطمع الشفاعة للأمة.\r\rتنبيه: قول الناظم: (كل متبع) أي كل من المذكورين أوجب الله على أمته أن يتبعوه في أمره ونهيه، وعلى كل مكلف أن يعتقد وصفه بالنبوة والرسالة، فهو تكميل للبيت. وقوله: (احتذى) بالحاء المهملة والذال المعجمة أي اقتدى أيوب بمن تقدم في الذكر، فهو تكميل"], [63, "صفحة 63 للبيت، وكذا قوله: (اتبع).\r\rقوله: (اليسع) الألف واللام فيه زائدتان. قوله: (خاتم) بفتح التاء وكسرها والكسر أشهر. وأما الخاتم التي هي ذات فص فبالفتح لا غير. وقوله: (دع غيا) أي اترك ميلاً عن الحق، فلا تمل عن طريق الصواب، وهو تكميل للبيت. ومعنى قول الناظم: (وطه خاتم) أي أن سيدنا محمداً صلى الله عليه وسلم هو خاتم الأنبياء والمرسلين فلا نبي بعده أبداً، وشريعته باقية إلى قيام الساعة ناسخة لشريعة غيره، ولا ينسخها شريعة غيره، لقوله صلى الله عليه وسلم: (لن تزال هذه الأمة قائمة على أمر الله - أي الدين الحق - لا يضرهم من خالفهم حتى يأتي أمر الله) أي الساعة، ولا يُشْكِلُ ذلك بنزول سيدنا عيسى عليه السلام في آخر الزمان، لأنه إنما ينزل حاكماً بشريعة نبينا ومتبعاً له، ولا ينافي ذلك أنه حين نزوله يحكم برفع الجزية عن أهل الكتاب، ولا يقبل منهم إلا الإسلام أو السيف؛ لأن نبينا أخبرنا بأنها مُغَيَّاة [1] إلى نزول عيسى، فحكمه بذلك إنما هو بشريعة نبينا، ولذلك قال عوض الغمراوي:\r\rفشرعُ طه أحمدَ المختارِ…باقٍ ليومِ الحشرِ والقَرارِ\r\rثم اعلم أن أوضاع جميع أسماء الأنبياء عجمية إلا أربعة، فهي عربية، وهي: محمد وهود وصالح وشعيب،"], [64, "وكلها لا تنصرف إلا سبعة فتنصرف، يجمعها قولك: (صن شمله) فالصاد لصالح والنون لنوح والشين لشعيب وشيث والميم لمحمد واللام للوط والهاء لهود، وهذا هو القاعدة المعتبرة في النحو، لكن في هذه المنظومة ثلاثة أسماء تقرأ بالتنوين وهي: آدم ونوح ولوط، وثلاثة عشر تقرأ بغير تنوين وهي: إدريس وهود وإبراهيم وإسماعيل وإسحق ويعقوب ويوسف وأيوب وشعيب وهارون وداود وسليمان وإلياس، وثمانية تقرأ بالسكون وهو الباقي كصالح ويونس وغيرهما وذلك للضرورة. قال القاسم الحريري في ملحة الإعراب:\rوجائزٌ في صَنْعَةِ الشِّعْرِ الصَّلِفْ…أن يَصْرِفَ الشاعرُ ما لا يَنْصَرِفْ\r\rومعنى الصلف أي المائل عن الاعتدال، قال عبد الله الفاكهي: أي إذا اضطر الشاعر إلى صرف ما لا ينصرف صرفه، لأن الضرورة ترد الأشياء إلى أصلها، وأصل الأسماء الصرفُ، لكن الضرورة قد تكون موجبة للصرف لأجل إقامة الوزن، وأما منع المصروف من الصرف فمذهب البصريين المنع مطلقاً، لأنه خروج عن الأصل بخلاف صرف الممنوع فإنه رجوع إلى الأصل، وجوَّزه بعضهم مطلقاً وبعضهم في الشعر. اهـ."], [65, "عليهمُ الصلاةُ والسلامُ…"]], "pg": [61, 65]}, "533.20": {"x": [[65, "وَآلِهِمْ ما دامتِ الأيامُ\r\rفضمير عليهم وآلهم راجع للمرسلين. وقوله: (ما دامت الأيام): (ما) ظرفية مصدرية، ودام تامة بمعنى بقيت، والأيام جمع يوم، والمراد به هنا الوقت والحين نهاراً كان أو ليلاً، ومعنى هذا البيت أطلب منك يا الله أن ترحم هؤلاء بالرحمة المقرونة بالتعظيم، وأن تؤمنهم وتحييهم بطيب تحية مدة دوام الأوقات والأزمان وبقائها. وهذا هو النسخة الصحيحة من أصل الناظم، وأما ما وجد في بعض النسخ من قوله: (ما دامت الأوقات والأيام) بذكر لفظ (الأوقات) مع حذف لفظ (وآلهم) فهو تحريف من النساخ. قوله: (وآلهم) معطوف على الضمير في قوله عليهم، وهو بغير إعادة الخافض وذلك جائز عند ابن مالك وفاقاً ليونس والأخفش والكوفيين واختاره أبو حيان، وأما عند جمهور البصريين فلا يجوز العطف على ضمير مخفوض إلا بإعادة عامل الخفض، سواء كان حرفاً أو اسماً نحو: فقال لها وللأرض، وعليها وعلى الفلك، قالوا نعبد إلهك وإله آبائك، قال ابن مالك في الخلاصة:\r\rوَعَوْدُ خافضٍ لدى عطفٍ على…ضميرِ خفضٍ لازماً قد جُعِلَا\r\rوليسَ عندي لازماً إذ قد أتى…في النَّظْمِ وَالنَّثْرِ الصحيحِ مُثْبِتَا\r\rأي فمن النظم قول الشاعر:\r\rفاذهب فما بك والأيامِ من عجبٍ…"], [66, "ومن النثر قراءة ابن عباس والحسن وغيرهما: {تساءلون به والأرحام} بالجر.\r\rمسألة\rقال إسماعيل الحامدي: فإن قيل الرحمة للنبي حاصلة، فطلبها تحصيل الحاصل، فالجواب: أن المقصود بصلاتنا عليه طلب صلاة لم تكن، فإنه ما من وقت إلا وهناك رحمة لم تحصل، فلا يزال يترقى في الكمالات إلى ما لا نهاية له، فهو ينتفع بصلاتنا عليه على الصحيح، لكن لا ينبغي للمصلي أن يقصد ذلك، بل يقصل التوسل إلى ربه في نيل مقصوده، ولا يجوز الدعاء للنبي صلى الله عليه وسلم بغير الوارد كرحمه الله، بل المناسب واللائق في حق الأنبياء الدعاء بالصلاة والسلام، وفي حق الصحابة والتابعين والأولياء والمشايخ بالترضي، وفي حق غيرهم يكفي أي دعاء كان. انتهى.\r____________\r[1] مغياة: إلى غاية."]], "pg": [65, 66]}, "533.21": {"x": [[69, "الفصل الثالث في الملائكة عليهم السلام\rوَالمَلَكُ الذي بلا أَبٍ وَأُمْ…"]], "pg": [69, 69]}, "533.22": {"x": [[69, "لا أَكْلَ لا شُرْبَ ولا نومَ لهمْ\r\rأي يجب على كل مكلف أن يعتقد أن الملائكة عليهم السلام خلقهم الله من غير واسطة أب ولا أم، فليسوا رجالاً ولا نساءً ولا خناثى، فمن اعتقد ذكورتهم كان مبتدعاً فاسقاً وفي كفره قولان، ومن اعتقد أنوثتهم كان كافراً بالإجماع؛ لأن الذكورة أشرف من الأنوثة، وقد بيَّن الله تعالى كفر من اعتقد أنوثة الملائكة بقوله تعالى: {وَجَعَلُوا المَلائِكَةَ الَّذِينَ هُمْ عِبَادُ الرَّحْمَنِ إِنَاثًا}، أي واعتقدهم الكافرون إناثاً، وأولى بالكفر من اعتقد خنوثتهم لمزيد التنقيص. وهم غير الجن لا رجال ولا نساء، ولا يأكلون ولا يشربون، ولا ينامون ولا يتناكحون، ولا يتوالدون، ولا تكتب أعمالهم لأنهم الكُتَّابُ، ولا يحاسبون لأنهم الحُسَّابُ، ولا توزن أعمالهم لأنهم لا سيئات لهم، ويحشرون مع الجن والإنس يشفعون في عصاة بني آدم، ويراهم المؤمنون في الجنة، ويدخلون الجنة ويتناولون النعمة فيها بما شاء الله، كذا قاله السحيمي والباجوري، وقال بعضهم تبعاً لمجاهد: إنهم لا يأكلون فيها ولا يشربون ولا ينكحون، وإنهم يكونون فيها كما كانوا في الدنيا، ورده السحيمي بقوله: وهذا يقتضي أن الحور والولدان كذلك. اهـ.\r\rوهم أجسام نورانية لطيفة بأرواح، قادرون على"], [70, "صفحة 70\rالتشكل بأشكال مختلفة في أشكال حسنة، شأنهم الطاعة ومسكنهم السماوات غالباً، ومنهم من يسكن الأرض، صادقون فيما أخبروا به عن الله تعالى، يُسبِّحون الليل والنهار لا ينقطعون، ولا يعصون الله في الأمور التي قد أمرهم، ويفعلون الأمر الذي يؤمرون به، ويموتون بالنفخة الأولى إلا حملة العرش والرؤساء الأربعة، فإنهم يموتون بعدها، وأما قبلها فلا يموت منهم أحد، ولا يلزمنا معرفة حقيقة جنسهم، ولا من أي شيء خلقوا، ويجب الإيمان بأنهم بالغون في الكثرة إلى حد لا يعلمه إلا الله تعالى على الإجمال إلا مَنْ ورد تعيينه باسمه المخصوص، أو نوعه، فيجب الإيمان بهم تفصيلاً، فالأول كجبريل ونحوه مما يأتي في كلام الناظم، والثاني كحملة العرش والحفظة والكتبة.\r\rقوله: (وَالمَلَكُ) بفتحتين: واحد الملائكة، قاله الفيومي في المصباح، ولذا وصف (بالذي) المفيد للمفرد، فإفراد لاعتبار لفظ ملك وجمع ضمير لهم العائد إليه لاعتبار معناه كقوله تعالى: {أُمَّةٌ قَائِمَةٌ يَتْلُونَ} فوصف أمة بالمفرد الذي هو قائمة لاعتبار لفظ أمة وأعيد الضمير في يتلون إليها مجموعاً لاعتبار معناها، وكذا يصح أن يقدر صلة الذي بالمفرد اعتباراً للفظ مَلَك، فيقال: والملك الذي كان، وبالجمع اعتباراً لمعناه فيقال: والملك الذي كانوا، كقوله تعالى: {وَخُضْتُمْ كَالَّذِي"], [71, "صفحة 71\rخَاضُوا}، أي ودخلتم في الباطل كالفريق الذي دخلوا فيه، فأفرد الذي لأنه صفة للفريق المقدر، وهو مفرد لفظاً ولكنه جمع في المعنى، ولذا جمع الضمير العائد إليه في خاضوا، فإن تطابق ضمير الصلة للموصول واجب، سواء المطابق في اللفظ أو في المعنى، فالألف واللام في قول الناظم والملك للجنسية التي لاستغراق الإفراد، وهي التي يصح أن يقع موقعها لفظ كل في الحقيقة، وهذا يصح أن يقال فيه وكل ملك. قوله: (لا أكل لا شرب) بفتح الهمزة والشين لأن المراد هنا الفعل لا المأكول والمشروب الذي هو الطعام.\r\rفرع\rيجب على كل مكلف أن يعرف الولدان؛ وهم خلق جميل في رؤيتهم سرور، لأنهم كاللؤلؤ المفرق، وهم مرد أي لا شعر على وجههم على صورة أولاد الدنيا، لا يشيبون، ولذلك يسمون ولداناً، لا يخطر بقلب أحد منهم فاحشة، لا أب لهم ولا أم. ويجب أن يعرف أيضاً الحور العين، وهن نساء خلقهن الله بقدرته من نور، لا أب لهن ولا أم، قيل إنهن خلقن من نور، وينكحهن المؤمنون، {لَمْ يَطْمِثْهُنَّ إِنْسٌ قَبْلَهُمْ وَلا جَانٌّ}، وكلما أصابوهن وجدوهن أبكاراً، جمالهن عجيب كأنهن الياقوت في صفائهن، واللؤلؤ في بياضهن، يُرَى مخ سُوْقِهِنَّ من وراء لحمهن وعظمهن وجلدهن، كما يرى الشراب الأحمر من الزجاج الأخضر، والثوب الأحمر من الزجاج"], [72, "صفحة 72\rالأبيض، ولو أن شعرة من شعورهن طلعت إلى الأرض لأضاء أهل الأرض، وعليهن سبعون حلة، رؤوسهن مكللة بالدر، مرصعة بالياقوت الأحمر، وسُمِّين بالحور العين لأن أعينهن اشتد بياض بياضها وسواد سوادها."], [73, "صفحة 73\rتفصيلُ عشرٍ منهمُ جبريلُ…ميكالُ إسرافيلُ عَزرائيلُ\r\rمنكرْ نكيرٌ ورقيبٌ وكذا…عتيدُ مالكٌ ورضوانُ احتذى\r\rأي يجب على كل مكلف أن يعتقد عشرة من الملائكة تفصيلاً بمعرفة أسمائهم، وهم أربعة أقسام: المتصرفون والفاتنون والحافظون والخازنون.\r\rفالمتصرفون أربعة: جبريل وميكائيل وإسرافيل وعزرائيل، فجبريل موكل بالوحي أي الخبر الذي يأتي به من عند الله للأنبياء عليهم الصلاة والسلام. قال الجلال السيوطي: وإنه يحضر موت من يموت على وضوء، وما اشتهر من أنه لا ينزل الأرض بعد موت النبي صلى الله عليه وسلم لا أصل له، إلا أن يقال لا ينزل بوحي، ذكره القليوبي. وميكائيل موكل بكيل الأمطار والبحار والأنهار والأرزاق وتصوير الأجنة في الأرحام. وإسرافيل موكل باللوح المحفوظ والنفخ في الصور، وهو قرن من نور وفيه ثقوب على عدد الأرواح، فينفخ فيه النفختين: فالنفخة الأولى تفنى فيها جميع المخلوقات إلا ما شاء الله وهي المستثنيات السبعة، وهي العرش والكرسي واللوح والقلم والجنة والنار والأرواح، والنفخة الثانية تُبعث فيها جميع المخلوقات، فترجع الأرواح لأجسادها لا تخطئ روحٌ جسدَها، وما بين النفختين أربعون سنة، ودليل ذلك قوله تعالى: {وَنُفِخَ فِي الصُّورِ فَصَعِقَ مَن فِي السَّمَاوَاتِ وَمَن"], [74, "صفحة 74\rفِي الْأَرْضِ إِلَّا مَن شَاءَ اللَّهُ ? ثُمَّ نُفِخَ فِيهِ أُخْرَى? فَإِذَا هُمْ قِيَامٌ يَنظُرُونَ}. وعزرائيل موكل بقبض أرواح الخلائق أي بإخراج أرواح كل من له روح من مقرها ولو قملة أو بعوضة أو برغوثاً كما ذهب إليه أهل الحق خلافاً للمعتزلة، حيث ذهبوا إلى أنه لا يقبض أرواح غير أهل الثقلين من الملائكة والطيور وغيرهم، وخلافاً للمبتدعة حيث ذهبوا إلى أنه لا يقبض أرواح البهائم بل يقبضها أعوانه، ذكر ذلك الباجوري. وهو مَلَكٌ عظيم هائل المنظر، رأسه في السماء العليا ورجلاه في تخوم الأرض السفلى، أي منتهاها ووجهه مقابل اللوح المحفوظ، والخلق بين عينيه، وله أعوان بعدد من يموت، يترفق بالمؤمن، ويأتيه في صورة حسنة دون غيره.\r\rوالفاتنون اثنان: منكر ونكير، وهما ملكان أسودان يخرقان الأرض بأنيابهما، لهما شعور مسدولة يجرانها على الأرض، أبصارهما كالبرق الخاطف، وفي رواية أزرقان، أعينهما كقدور النحاس، وأوصواتهما كالرعد القاصف، إن تكلما يخرج من أفواههما كالنار، وأنيابهما كالصياصي أي قرون البقر، وأنفاسهما كالريح العاصف، وفي رواية كاللهب، في يد كل واحد منهما مطرقة من حديد، لو اجتمع عليها الثقلان ما رفعوها، ولو ضرب بها الجبال لذابت، وهما موكلان على سؤال الإنس والجن من أمة الدعوة المؤمنين والمنافقين والكافرين، ومحله"], [75, "صفحة 75\rبعد تمام الدفن وانصراف الناس، فيعيد الله تعالى الروح إلى جميع البدن، كما ذهب إليه الجمهور، وقال ابن حجر: إلى نصفه الأعلى فقط، وغلط من قال يُسأل البدن بلا روح، ومن قال تُسأل الروح بلا بدن، لكن وإن عادت له الروح لا ينتفي إطلاق اسم الميت عليه؛ لأن حياته ليست حياة كاملة بل أمر متوسط بين الموت والحياة كتوسط النوم بينهما، ويرد إليه من الحواس والعقل والعلم ما يتوقف عليه فهمُ الخطاب، ويتحصل معه رد الجواب حين يُسأل، ذكر ذلك الباجوري: ويُجمع من تفرقت أجزاؤه وأكلته السباع، فيُقعدانه فيسألانه بعنف، وينهرانه بجفاء، قاله الغزالي، وقيل يرفقان بالمؤمن وينهران الكافر والمنافق، ويسألان كل إنسان بلغته ويقولان له: من ربك؟ وما دينك؟ ومن نبيك؟ وما قبلتك؟ ومن إخوتك؟ وما إمامك؟ وما منهاجك؟ وما عملك؟ فمن وفقه الله وثبته بالقول الثابت قال: ومن وكلكما علي؟ ومن أرسلكما إلي؟ وهذا لا يقوله إلا العلماء الأخيار، فيقول أحدهما للآخر: (صدق، وقد كفي شرنا)، والمؤمن يقول لهما: (ربي الله وحده لا شريك له، والإسلام ديني، ومحمد نبيي وهو خاتم النبيين، والكعبة قبلتي، والمؤمنون إخوتي، والقرآن إمامي، والسنة منهاجي، وأنا قرأت كتاب الله فآمنت به وصدقته)، ويقولان له إذا وفق للجواب: صدقت ونم نومة العروس"], [76, "صفحة 76\rالذي لا يوقظه إلا أحب الناس إليه. وفي رواية البخاري ومسلم إنهما يقولان له: ما كنت تقول في هذا النبي محمد صلى الله عليه وسلم؟ فيقول المؤمن: أشهد أنه عبد الله ورسوله. انتهى. وأما الكافر والمنافق فيحصل لهما رعب، فيقولان لهما: هاه هاه لا أدري. وفي رواية للترمذي: يقال لأحدهما المنكر وللآخر النكير. وذكر ابن يونس أن ملكي المؤمن يقال لهما مبشر وبشير، وأحوال المسؤولين مختلفة، فمنهم من يسأله الملكان جميعاً تشديداً عليه، ومنهم من يسأله أحدهما تخفيفاً عليه، وكيفية السؤال والجواب مختلفة، فمنهم من يُسأل عن بعض اعتقاداته، ومنهم من يُسأل عن كلها، قال ابن عباس رضي الله عنهما: يُسألون عن الشهادتين، وقال عكرمة: يُسألون عن الإيمان بمحمد صلى الله عليه وسلم وأمر التوحيد.\r\rوإذا مات جماعة في وقت واحد بأقاليم مختلفة سئلوا جميعاً في ذلك الوقت، ولا مانع من ذلك. قال القرطبي: جاز أن تعظم جثتهما ويخاطبان الخلق الكثير مخاطبة واحدة. وقال السيوطي: يحتمل تعدد الملائكة المعدة لذلك كالحفظة ونحوهم…والسؤال مخصوص بمن كان مكلفاً، ولو جناً لا ملكاً…ويُستثنى من المكلفين الأنبياء والصديقون والشهداء، وملازم سورة \"تبارك الملك\" كُلَّ ليلة، أو سورة السجدة .. ومن قرأ سورة الإخلاص في مرضه الذي مات فيه ونحو ذلك. وَسُمِّيَا منكراً ونكيراً لأنهما لا يشبهان خلق الآدميين ولا"], [77, "صفحة 77\rخلق الملائكة، ولا خلق الطير، ولا خلق البهائم، ولا خلق الهوام…بل هما خلق بديع جعلهما الله تذكرة للمؤمن، وهتكاً لستر الكافر، وليس في خلقهما سَكينة للناظرين، ولو لم يلق الكافر من العذاب إلا الرؤية لصورتهما لكفاه ذلك، بل هي من العذاب الأكبر لأنه قد حصل بها اضطراب شديد وارتعاد. والهوام جمع هامة مثل دواب جمع دابة، وقد أطلقت الهوام على ما يؤذي، قال أبو حاتم: ويقال لدواب الأرض جميعاً الهوام ما بين قملة إلى حية. قال حسن العدوي: وأما أهل الإيمان فلهم مبشر وبشير، قيل ومعهما مَلَكٌ آخر يقال له \"ناكور\" ويجيء قبلهما ملك يقال له \"رومان\". قال العلامة الأمير: وحديثه قيل موضوع أي مردود لكذبه…والصحيح أن منكراً ونكيراً للمؤمن وغيره طائعاً وعاصياً، غير أنهما يأتيان للمؤمن الموفق مع رفق من غير إقلاق وإزعاج. انتهى قول العدوي. قال الشيباني في قصيدته من بحر الطويل:\r\rومنكَرٌ ثم النكيرُ بِصِحَّةٍ…هما يَسألانِ العبدَ في القبرِ مُقْعَدَا\r\rوقال عوض بن أحمد الغمراوي:\r\rهما نكيرٌ منكرٌ فيما يَصِحْ…وقبلَهم رُومانُ لكنْ لم يَصِحْ\r\rقوله: (هما) أي الملكان، وقوله: (وقبلهم) بضمير الجمع عائد على الملكين أيضاً، وإنما جمع هذا الضمير إشارة"], [78, "صفحة 78\rإلى القول بتعدد الملائكة المعدة للسؤال كما قال الحليمي: والذي يشبه أن يكون ملائكة السؤال جماعة كثيرة، ويُسمى بعضهم منكراً وبعضهم نكيراً، فيبعث إلى كل ميت اثنان والله أعلم. اهـ.\r\rقوله: (لكن لم يصح) أي الحديث الذي روي في رومان غير صحيح لعدم موثوقية الراوي، ولذلك قال الباجوري: وما قيل من أنه يجيء قبلهما ملك آخر يقال له رومان فحديثه موضوع، وقيل فيه لين. انتهى. وروي أن سبب رفقهما بالمؤمن: لما مات سيدنا عمر بن الخطاب ودفن وانصرف الجماعة، فبقي سيدنا علي كرم الله وجهه ورضي عنه يترقب في القبر؛ ليستمع كلام سيدنا عمر مع هذين الملكين فسمعه يقول: (أيها الملكان، أنا وعدتكما وأوصيكما أن لا تأتيا المؤمن بعد هذا الوقت بصورتكما هذه، بل انقصا من هذه لأني لما رأيتكما بهذه الحالة حصل لي خوف وفزع شديد وأنا صاحب رسول الله، فكيف بسواي إذا رآكما بهذه الصورة؟)، فقالا له: (سمعاً وطاعة، لا نعصي أمرك يا صاحب رسول الله)، فقال سيدنا علي رضي الله عنه: (والله ما يزال عمر ينفع الناس في حياته ومماته). وقال بعضهم: ولا بد من معرفة رومان، وهو الملك الذي يأتي للميت في قبره ويناديه، وذلك بعد أن يُسَوَّى عليه التراب. قال الغزالي في الدرة الفاخرة: وقد روي أن ابن مسعود رضي الله عنه قال: يا رسول الله، ما أول ما يَلقى الميت إذا دخل"], [79, "صفحة 79\rقبره؟ قال: يا ابن مسعود ما سألنيه أحد غيرك .. فأول ما يناديه ملك اسمه رومان يجوس خلال المقابر، يقول: يا عبد الله اكتب عملك .. فيقول ليس معي دواة ولا قرطاس ولا قلم، فيقول: هيهات كفنك قرطاسك، وريقك مدادك، وقلمك إصبعك، فيقطع له قطعة من كفنه ثم يجعل العبد يكتب .. وإن كان غير كاتب في الدنيا فيذكر حينئذ حسناته وسيئاته من يوم ولدته أمه كيوم واحد، ثم يطوي الملك تلك الرقعة ويعلقها في عنقه. ثم قرأ رسول الله صلى الله عليه وسلم: {وَكُلَّ إِنسَانٍ أَلْزَمْنَاهُ طَائِرَهُ فِي عُنُقِهِ} أي عمله. اهـ.\r\rوالحافظون قسمان: أحدهما حافظون للعبد من المضار، وثانيهما حافظون لما يصدر منه من قول أو فعل أو اعتقاد، فالحافظون من المضار عشرة بالليل وعشرة بالنهار. أخرج الطبري من طريق كنانة العدوي أن عثمان سأل النبي صلى الله عليه وسلم عن عدد الملائكة الموكلين بالآدمي فقال: لكل آدمي عشرة بالليل وعشرة بالنهار .. واحد عن يمينه وآخر عن شماله، واثنان من بين يديه ومن خلفه، واثنان على جنبيه، وآخر قابض على ناصيته، فإن تواضع رفعه وإن تكبر وضعه، واثنان على شفتيه وليس يحفظان عليه إلا الصلاة على النبي صلى الله عليه وسلم، والعاشر يحرسه من الحية أن تدخل فاه، أي إذا نام. وقال المهدوي: إن عثمان سأل النبي صلى الله عليه وسلم: كم من ملك على الإنسان؟ فذكر عشرين ملكاً، وذكر الأبي أنه يحفظ لابن عطية: أن كل إنسان يوكل به من"], [80, "صفحة 80\rحين وقوعه نطفة في الرحم إلى موته أربعمائة ملك. قال الباجوري: وحفظهم للعبد إنما هو من المعلق .. وأما المبرم فلا بد من إنفاذه، فيبعدون عنه حتى ينفذ .. والحافظون لِمَا يصدر من العبد من قول أو فعل أو اعتقاد اثنان: رقيب وعتيد، وكل منهما رقيب أي حافظ وعتيد أي حاضر، أي فكل واحد منهما يُسمى بهذين الاسمين لا كما قد يُتوهم من أن أحدهما رقيب والآخر عتيد. قاله الباجوري كالجلال المحلي. قال عوض الغمراوي:\r\rهما رقيبٌ وعتيدٌ عَلِمَا…لِكُلِّ واحدٍ كما قد عُلِمَا\r\rوهما لا يتغيران ما دام العبد حياً، فإذا مات يقومان على قبره يسبِّحان ويهللان ويكبران، ويكتبان ثوابه له إلى يوم القيامة إن كان مؤمناً، ويلعنانه إلى يوم القيامة إن كان كافراً أو منافقاً. وقيل لكل يوم وليلة ملكان: فلليوم ملكان وللَّيلة ملكان، فتكون الملائكة أربعة يتعاقبون عند صلاة العصر وصلاة الصبح، ويؤرخان ما يكتبان من أعمال العباد بالأيام والجمع والأعوام والأماكن. فملك الحسنات من ناحية اليمين، وملك السيئات من ناحية اليسار، فكاتب الحسنات أمين أو أمير على كاتب السيئات، فإذا فعل العبد حسنة بادر ملك اليمين إلى كتابتها، وإذا فعل سيئة قال ملك اليسار لملك اليمين: أكتب؟ فيقول له: اصبر ولا تكتب لعله يستغفر أو يتوب، فإن تاب كتبت حسنة، وإن لم يتب بعد مضي ست ساعات قال له: اكتب،"], [81, "صفحة 81\rأراحنا الله منه، وهذا دعاء عليه بالموت ليتحوَّلا عن مشاهدة هذه المعصية؛ لأنهما يتأذيان منه بذلك.\r\rوفي بعض الآثار أن كتب المباحات على القول به لكاتب السيئات، وتُعرض صحائف الأعمال على رسول الله صلى الله عليه وسلم صباحاً ومساءً، ولم يهملا من أمر العبد شيئاً إلا كتباه سواءً كان قولاً أو فعلاً أو عزماً، فإذا عزم على حسنة يعرفانها بطيب رائحتها، وإذا عزم على سيئة يعرفانها بنتن رائحتها، ولا يفارقان العبد إلا عند إحدى ثلاث حاجات: عند قضاء حاجة الإنسان بولاً أو غائطاً، وعند الجماع، وعند الغسل لوجود كشف العورة عند ذلك، بخلاف الحفظة الأولين غير الكاتبين، فإنهم لا يفارقون العبد بل يلازمونه أبداً، فإذا فارق الكاتبان العبد عند هذه الأفعال فلا يمنع ذلك من كتابة ما يصدر منه؛ لأن الله يجعل لهما علامة على ذلك، وفي غير هذه الأفعال لا يفارقانه، ولو كان بيته فيه جرس أو كلب أو صورة، وأما حديث: لا تدخل الملائكة بيتاً فيه جرس ونحوه فالمراد ملائكة الرحمة، والكتابة حقيقية بآلة وقرطاس ومداد يعلمه الله سبحانه وتعالى، خلافاً لمن قال إنه كناية عن الحفظ والعلم. وفي بعض الأحاديث أن لسانه قلمهما، وريقه مدادهما، والتفويض أولى. واختلف في محلهما من الشخص، فقيل ناجذاه أي آخر أضراسه الأيمن والأيسر، وقيل عاتقاه، وقيل ذقنه، وقيل شفتاه،"], [82, "صفحة 82\rوقيل عنفقته.\r\rوروي عن مجاهد أنه إن قعد كان أحدهما أمامه والآخر وراءه، وإن رقد كان أحدهما عند رأسه والآخر عند رجليه، ويجمع بين هذه الأقاويل بأنهما لا يلزمان محلاً واحداً، والأسلم في أمثال ذلك الوقف، قاله البيجوري.\r\rوالخازنون اثنان: مالك ورضوان؛ فمالك موكل بالنيران السبعة ومعه الزبانية وهم تسعة عشر نفراً، ولكل نفر جنود لا يعلم عددهم إلا الله تعالى لقوله تعالى: {وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ}، وأبواب النيران وطبقاتها سبع، أعلاها جهنم وهي لعُصاة المؤمنين، وتصير خراباً بخروجهم منها، وتحتها لظى وهي لليهود، ثم الحطمة وهي للنصارى، ثم السعير وهي للصابئين (فرقة من اليهود ازدادوا ضلالاً بعبادتهم العجل، وهو ولد البقرة ما دام له شهر)، ثم سقر وهي للمجوس عباد النار، ثم الجحيم وهي لعبدة الأصنام، ثم الهاوية وهي للمنافقين وكل من اشتد كفره كفرعون وهامان وقارون، فأرضها من رصاص، وسقفها من نحاس، وحيطانها من كبريت، وقودها الناس والحجارة، حفظنا الله من الجميع ورزقنا شفاعة الشفيع. ورضوان موكل بالجِنان، وهو رئيس خزنتها، وأبوابها الكبار ثمانية: باب الشهادتين، وباب الصلاة، وباب الصيام، وباب الزكاة، وباب الحج، وباب الأمر بالمعروف والنهي عن المنكر، وباب الصلة، وباب"], [83, "صفحة 83\rالجهاد في سبيل الله، ومن داخلها عشرة أبواب صغار. وهي سبعة جنان متجاورة، فأوسطها وأفضلها الفردوس، وسقف الجميع عرش الرحمن، ويليها جنة المأوى، وجنة الخلد، وجنة النعيم، وجنة عدن، ودار السلام، ودار الجلال، وقيل أربعة، وقيل واحدة وإنما التعدد في الاسم لشرفها ولتحقق معاني تلك الأسماء فيها، فترابها المسك والزعفران، وفي كل قصر منها فرع من شجرة طوبى وأصلها في بيت النبي صلى الله عليه وسلم، يطرح ما تشتهيه الأنفس، فإذا أراد أهل الجنة الأكل قالوا: سبحانك اللهم، ووضعت بين أيديهم مائدة طولها ميل وعرضها ميل، فيها جميع ما يشتهون، فإذا فرغوا من الأكل قالوا: الحمد لله رب العالمين فترفع، وهو معنى قوله تعالى: {دَعْوَاهُمْ فِيهَا سُبْحَانَكَ اللَّهُمَّ وَتَحِيَّتُهُمْ فِيهَا سَلَامٌ ? وَآخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ}.\r\rوبالجملة ففيها ما لا عين رأت، ولا أذن سمعت، ولا خطر على قلب بشر، قال ابن عباس رضي الله عنهما: للجنان سبعة أبواب من الذهب، مرصعة بالجواهر، مكتوب على الباب الأول لا إله إلا الله محمد رسول الله، هو باب الأنبياء والمرسلين والشهداء والصالحين، والباب الثاني باب المصلين بكمال الصلاة، والباب الثالث باب المزكين بطيب أنفسهم، والباب الرابع باب الآمرين بالمعروف والناهين عن المنكر، والباب الخامس لمن"], [84, "صفحة 84\rنهى نفسه عن الشهوات، والباب السادس باب الحجاج والمعتمرين، والباب السابع باب المجاهدين، والباب الثامن باب الموقنين الذين يغضون أبصارهم عن المحارم، ويعملون الخيرات من بر الوالدين وصلة الرحم وغير ذلك. وفيها سبع جنات أولها دار الجلال وهي من لؤلؤة بيضاء، وثانيها دار السلام وهي من ياقوتة حمراء، وثالثها جنة المأوى من زبرجدة خضراء، ورابعها جنة الخلد وهي من مرجان أصفر، وخامسها جنة النعيم وهي من فضة بيضاء، وسادسها جنة الفردوس وهي من ذهب أحمر، وسابعها جنة عدن وهي من درة بيضاء، وأما بناؤها فلبنة من ذهب ولبنة من فضة، ومِلاطها المسك وترابها العنبر والزعفران، وحصباؤها اللؤلؤ والياقوت. اهـ. والمِلاط بكسر الميم: الطين الذي يجعله بين اللبن في البناء، والحصباء بالمد: صغار الحصى.\r\rوعن عمران بن حصين وأبي هريرة قالا: سئل رسول الله صلى الله عليه وسلم عن قوله تعالى: {وَمَسَاكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ} قال: (قصر من لؤلؤة في ذلك القصر سبعون داراً من ياقوتة حمراء، وكل دار سبعون بيتاً من زمردة خضراء في كل بيت سرير، على كل سرير سبعون فراشاً، على كل فرش زوجة من الحور العين، في كل بيت سبعون مائدة، على كل مائدة سبعون لوناً من الطعام، في كل بيت سبعون وصيفاً ووصيفة). انتهى. والوصيف الغلام دون المراهق، والوصيفة"], [85, "صفحة 85\rالجارية. كذلك قال كعب الأحبار: سألت رسول الله صلى الله عليه وسلم عن أشجار الجنة فقال: (لا تيبس أغصانها ولا تتساقط أوراقها، وإن أكبر أشجار الجنة شجرة طوبى، أصلها من درة وأغصانها من زبرجد وأوراقها من سندس، وعليها سبعون ألف غصن، أقصى أغصانها ملتحق بساق العرش، وأدنى أغصانها في السماء ليس في الجنة غرفة ولا قبة إلا وفيها غصن يظل عليها .. وفيها من الثمار ما تشتهي الأنفس). قال الإمام علي كرم الله وجهه: إن أشجار الجنة تكون من فضة وأوراقها بعضها من فضة وبعضها من ذهب .. إن كان أصل الشجرة من ذهب يكون أغصانها من فضة، وإن كان أصلها من فضة يكون أغصانها من ذهب، وأشجار الدنيا أصلها في الأرض وعروقها في الهواء لأنها دار التكليف أي المشقة، وليس كذلك أشجار الجنة فإن أصلها في الهواء وأغصانها في الأرض، كما قال تعالى: {قُطُوفُهَا دَانِيَةٌ} أي ثمرتها قريبة يتناولها القاعد والقائم والمضطجع. وعن ابن عباس رضي الله عنهما قال: قال رسول الله صلى الله عليه وسلم: إن في الجنة حَوراء يقال لها لعبة خلقت من أربعة أشياء: من المسك والكافور والعنبر والزعفران، وعجن طينها بماء الحياة .. جميع الحور لها عشاق، ولو بزقت في البحر بزقة لعذب ماء البحر كله من ريقها مكتوب على نحرها من أحب أن يكون له مثلي فليعمل بطاعة ربي) انتهى. نعوذ بالله"], [86, "صفحة 86\rمن النار ومن عذاب النار، ونسأله أن يدخلنا دار الأبرار مع المتقين الأخيار بجوار النبي المختار عليه من الله تعالى أفضل الصلاة والسلام.\r\rتنبيه\rاعلم أن أسماء الملائكة أعجمية إلا أربعة وهم: رضوان ومالك ونكير ومنكر، لكن رضوان ممنوع من الصرف لِلْعَلَمِيَّةِ وزيادة الألف والنون، بخلاف بقية الأربعة فإنها مصروفة، وهذا أصل القاعدة النحوية. وأما في هذه المنظومة فستة تُقرأ بغير تنوين وهي: جبريل وميكائيل وإسرافيل وعزرائيل وعتيد ورضوان، وثلاثة بالتنوين وهي: نكير ورقيب ومالك، وواحد بالسكون وهو منكر لضرورة الوزن، كما قال ابن مالك في الخلاصة:\r\rولاضطرارٍ أو تناسُبٍ صُرِفْ…ذو المَنْعِ والمصروفُ قد لا ينصرفْ\r\rوقول الناظم: (منهمُ) هو بضم الميم مع الإشباع للوزن. وقوله: (عَزرائيل) بفتح العين كما قرأه بذلك شيخنا أحمد الدمياطي ومعناه عبد الجبار. قوله: (منكر) بفتح الكاف، قاله القليوبي. واعلم أنه قد يوجد في بعض النسخ زيادة ضمير جمع الذكور الغائبين بعد إسرافيل، وهو قوله: (إسرافيل هم) فهو غلط؛ لأن الوزن يستقيم بدونه ولأنه لا معنى له."], [87, "صفحة 87\rالفصل الرابع\rفي الكتب السماوية"], [89, "صفحة 89\rأربعةٌ من كُتُبٍ تفصيلُها…توراةُ موسى بالهدى تنزيلُها\r\rزبورُ داودَ وإنجيلٌ على…عيسى وفرقانٌ على خيرِ المَلَا\r\rأي يجب على كل مكلف أن يعتقد أربعة من الكتب تفصيلاً بأسمائها، وهي التوراة لسيدنا موسى، والزبور لسيدنا داود، والإنجيل لسيدنا عيسى، والفرقان لسيد الخلق سيدنا محمد صلوات الله وسلامه عليهم أجمعين. وأما بقية الكتب فيجب اعتقادها إجمالاً بأن يعتقد أن الله تعالى أنزل كتباً من السماء على الإجمال، وقد اشتهر أن جميع الكتب مائة وأربعة، وقيل إنها مائة وأربعة عشر، قال السحيمي: والأصح عدم حصر الكتب في عدد معين .. فلا يقال إنها مائة وأربعة فقط؛ لأنك إذا فتشت الروايات تجدها تبلغ أربعة وثمانين ومائة. انتهى.\r\rفائدة\rعن وهب بن منبه قال: وجدت في التوراة أربعة أسطر متواليات: أحدها: من قرأ كتاب الله تعالى فظن أن لن يغفر الله له فهو من المستهزئين بآيات الله. والثاني: من تواضع لغني لغناه فقد ذهب ثلثا دينه. والثالث: من حزن على ما فاته سخط قضاء ربه. والرابع: من شكا مصيبة فإنما يشكو ربه. انتهى. وفي التوراة أيضاً: يا ابن آدم، لا تَخَفْ من سلطان ما دام سلطاني باقياً، وسلطاني بَاقٍ لا ينفد أبداً، يا ابن آدم، خلقتك لعبادتي فلا تلعب، يا ابن آدم لا تَخَفْ"], [90, "صفحة 90\rفوات الرزق ما دامت خزائني مملوءة، وخزائني لا تنفد أبداً، يا ابن آدم، خلقت السماوات والأرض ولم أعي بخلقهن، أيُعييني رغيف واحد أسوقه إليك في كل حين؟ يا ابن آدم، كما لا أطالبك بعمل غد فلا تطالبني برزق غد، يا ابن آدم، لي عليك فريضة ولك علي رزق، فإن خالفتني في فريضتي لم أخالفك في رزقك على ما كان منك. يا ابن آدم، إن رضيتَ بما قسمتُه لك أرحتُ قلبك وبدنك، وإن لم ترض بما قسمتُه لك سلطتُ عليك الدنيا حتى تركض فيها كركض الوحش في البرية (أي في الصحراء)، وعزتي وجلالي لا ينالك منها إلا ما قسمته لك، وأنت عندي مذموم.\r\rقوله: (ينفَد) بفتح الفاء وبالدال المهملة أي يفنى وينقطع. قوله: (ولم أعي) مضارع عَيِيَ بكسر عين الفعل من باب تعب، أي لم أجزع. وقوله: (أيُعييني) بضم حرف المضارعة من أعيا الرباعي أي: أيعجزني. وعن الحسن البصري: أنزل الله مائة وأربعة كتب وأودع علومها في أربعة منها، وهي من التوراة والإنجيل والزبور والفرقان، ثم أودع علوم الثلاثة غير القرآن فيه مع زيادات لا تنحصر. وقال الشافعي رضي الله تعالى عنه: جميع ما تقوله الأمة شرح للسنة، وجميع السنة شرح للقرآن، وقال أيضاً: جميع ما حكم به النبي فهو مما فهمه من القرآن. وقال بعضهم: لم يُحِطْ بعلوم القرآن إلا الله، ثم نبيه صلى الله عليه وسلم فيما عدا ما انفرد الله بعلمه، ثم ورث أكثر ذلك عنه أعلام"], [91, "صفحة 91\rالصحابة مع تفاوتهم فيه، كأبي بكر رضي الله عنه فإنه أعلمهم، وعلي كرم الله وجهه، لقوله صلى الله عليه وسلم: (أنا مدينة العلم وعلي بابها)، ومن ثم قال ابن عباس: جميع ما أبرزتُه لكم من التفسير فهو من علي. قال بعضهم: علوم القرآن خمسون علماً وأربعمائة علم وسبعة آلاف علم وسبعون ألف علم، على عدد كلم القرآن مضروبة في أربعة؛ إذ لكل كلمة ظهر وبطن وحد ومطلع، ومما قيل في معنى البطن والظهر: أن ظاهر الكلمة ما ظهر من معانيها لأهل العلم بالظاهر، وباطنها ما تضمنته من الأسرار التي تطلَّع عليها أرباب الحقائق. والمراد بالحد: أحكام الحلال والحرام، والمطلع هو الاطلاع على الوعد والوعيد. وقال بعضهم: أصول علومه ثلاثة: توحيد ووعظ وحكم، ولذا سُمِّيت الفاتحة أم القرآن لاشتمالها على هذه الثلاثة، وكانت الإخلاص ثلثه لاشتمالها على التوحيد فقط.\r\rتنبيه\rقول الناظم: (أربعة): مبتدأ أول، وقوله: (من كتب) متعلق بمحذوف صفة لأربعة، وقوله: (تفصيلها): مبتدأ ثَانٍ، وقوله: (توراة) خبر الثاني، والجملة خبر الأول وهو مضاف، وموسى مضاف إليه. وقوله: (بالهدى): متعلق بمحذوف خبر مقدم، وتنزيلها: مبتدأ مؤخر، وقوله: (زبور): معطوف على توراة بحذف العاطف وهو مضاف، وداود: مضاف إليه، ومثله إنجيل وفرقان، وقوله: الملا: أي أشراف القوم،"], [92, "صفحة 92\rوالمراد به هنا الأنبياء والمرسلون، سُمُّوا بذلك لملاءتهم بما يُلْتَمَسُ عندهم من المعروف، أي أن سيدنا محمداً صلى الله عليه وسلم خير الأنبياء والمرسلين، ولزم أنه صلى الله عليه وسلم خير من غيرهم بالأولى والتوراة، قيل مأخوذ من وري الزند أي خرج ناره فإنها نور وضياء، قال الله تعالى: {إِنَّا أَنْزَلْنَا التَّوْرَاةَ فِيهَا هُدًى وَنُورٌ}، والزند: هو ما يقدح به النار، والإنجيل: وهو بكسر الهمزة وفتحها كما في القاموس من النَّجل؛ وهو استخراج خلاصة الشيء، وسمي كتاب عيسى بذلك لاستخلاصه خلاصة نور التوراة، ومنه قيل للولد نجل أبيه لاستخلاصه منه."], [93, "صفحة 93\rوَصُحُفُ الخليلِ والكليمِ…فيها كلامُ الحَكَمِ العليمِ\r\rأي يجب على كل مكلف أن يعتقد أن الله تعالى أنزل صحفاً على سيدنا إبراهيم وأنزل صحفاً قبل التوراة على سيدنا موسى، ولا يجب معرفة عدد صحفهما تفصيلاً بل يجب اعتقاده إجمالاً فقط؛ لأنه لم يرد تعيين العدد في القرآن بخلاف الكتب الأربعة المتقدم ذكرها، فإنها معيَّنة بنص القرآن، فلذلك تجب معرفتها تفصيلاً، قال محمد باسودان الحضرمي من بحر الرجز:\r\rوَكُلُّ ما به الكتابُ قد وَرَدْ…مُفَصَّلاً وَمُجْمَلاً فُلْيُعْتَقَدْ\r\rقوله: (ورد) بالبناء للفاعل معناه: حضر على المجاز. وقوله: (فليُعتقد) بالبناء للمجهول. فقول الناظم: (وَصُحُفُ) بضمتين: جمع صحيفة، والمراد بالخليل هو سيدنا إبراهيم، وبالكليم هو سيدنا موسى، والحَكَم بفتحتين، قال السيوطي معناه من أحكم التدبير: أي أتقنه في وضع الأسباب التي يفيض عنها المقادير، ومعنى العليم: مَنْ علمه غير مستفاد ومعلوماته ما لها من نفاد. انتهى.\r\rفائدة\rروي من حديث أبي ذر قال: قلت: يا رسول الله، فما كانت صحف إبراهيم؟ قال: كانت هي كلها أمثالاً منها: أيها المَلِكُ المسلط المبتلى المغرور إني لم أبعثك لتجمع الدنيا بعضها على بعض، ولكن"], [94, "صفحة 94\rبعثتك لترد عني دعوة المظلوم فإني لا أردها، ولو كانت من فم كافر. ومنها: على العاقل أن يكون له ساعة يناجي فيها ربه عز وجل، وساعة يحاسب فيها نفسه، وساعة يتفكر فيها صنع الله تعالى، وساعة يخلو أي يتجرد فيها لحاجته من المطعم والمشرب.\r\rومنها: وعلى العاقل أن لا يكون طامعاً أي مؤملاً إلا في ثلاث: تزود لمعاد، وَمَرَمَّةٍ لمعاش، ولذة في غير محرم.\r\rومنها: على العاقل أن يكون بصيراً بزمانه، مقبلاً على شأنه، حافظاً للسانه، وَمَنْ عَدَّ كلامه من عمله قل كلامه إلا فيما يَعنيه. (بفتح أوله من باب رمى، أي ما يتعلق عنايته به كما قال ابن حجر في فتح المبين)، وفي نسخة: ومن حسب كلامه، بدل ومن عد كلامه، والمعنى واحد لأن حَسَبَ يَحْسُبُ إذا كان من باب نصر ينصر، فهو بمعنى عَدَّ، ومصدره حِسبة بكسر الحاء، وحُسباناً بالضم، وهو تعدى إلى مفعول واحد. وأما حَسِبَ الذي بمعنى ظن فهو من باب تعب بكسر عين الفعل في الماضي وفتحها في المضارع في لغة جميع العرب إلا بني كنانة؛ فإنهم يكسرون عين المضارع مع كسر عين الفعل في الماضي أيضاً على غير قياس، ومصدره حِسباناً بكسر الحاء، وهو يتعدى إلى مفعولين لأنه من أفعال القلوب. وقوله: وساعة"], [95, "صفحة 95\rيحاسب فيها نفسه: أي كل صباح على جميع ما عمله ليلاً، وكل مساء على جميع ما عمله نهاراً، فما وجد من حسنة حَمِدَ الله عليها، أو من سيئة استغفر الله منها، وأقرب من ذلك إلى السلامة أن يحاسبها على كل فعل قبل الإقدام عليه، حتى لا يتلبس به إلا بعد معرفة حكم الله فيه، فما كان خيراً فعله، وما كان غير ذلك أمسك عنه، ليريح الملائكة من التعب، ولأن من حاسب نفسه في الدنيا هان عليه عذاب الآخرة. وفي الحديث: (حاسبوا أنفسكم قبل أن تحاسبوا)، ذكر ذلك الباجوري، وقال الشرقاوي: وكان بعضهم يقيد حركاتِه في نهاره في كتاب، فإذا أمسى جعله بين عينيه وحاسب نفسه على ما فيه .. وبعضهم كان يحاسبها على خواطره في اليوم والليلة. قوله: (وَمَرَمَّة) بفتحات وتشديد الميم: أي إصلاح.\r\rقال أبو ذر أيضاً: قلت: يا رسول الله فما كانت صحف موسى؟ قال: (كانت كلها عِبَراً) بكسر العين وفتح الباء، جمع عبْرة بسكونها، مثل سدر وسدرة، أي مواعظ، منها: عجبت لمن أيقن بالنار كيف يفرح! عجبت لمن أيقن بالنار يضحك! عجبت لمن يرى الدنيا وتقلبها بأهلها كيف يطمئن إليها! عجبت لمن أيقن بِالقَدَرِ كيف يتعب! (وفي رواية: كيف يغضب)، عجبت لمن أيقن بالحساب ثم لا يعمل!"], [99, "صفحة 99\rالفصل الخامس\rفي طاعة الرسول صلى الله عليه وسلم\rوفي الإيمان باليوم الآخر\rوَكُلُّ ما أتى بِهِ الرسولُ…فَحَقُّهُ التسليمُ والقَبولُ\r\rقوله: (أتى) بقصر الهمزة أي جاء، ويُستعمل لازماً ومتعدياً، وأما آتى بالمد فمعناه أعطى فيتعدى إلى مفعولين، وليس ما هنا على هذا. قوله: (فحقه التسليم) أي فواجبه علينا الاعتراف أي الإقرار بصحته. قوله: (والقَبول) بالفتح، والضم لغةٌ حكاها ابن الأعرابي، وهذا المصدر نادرٌ، لا يُسمع المصدر مفتوحَ الفاء على هذا الوزن إلا لفظ القَبول خاصة، أي وواجبه علينا أيضاً تصديقه وأخذه، قال تعالى: {وَمَا آتَاكُمُ الرَّسُولُ} أي أعطاكم {فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا}، قال عوض الغمراوي:\r\rوَأَوْجَبَ التصديقَ للأمينِ…في كُلِّ ما جَاءَ بِهِ في الدِّيْنِ\r\rكذا امتثالُ الأمرِ عندَ الأمرِ…والانتِها بنهيِهِ عَنْ أَمْرِ\r\rفالأمينُ هو رسول الله صلى الله عليه وسلم ومعناه المأمون من الفجور، سُمِّيَ بذلك لأنه ليس له غدر، وقوله: (امتثال الأمر عند الأمر) وهو ضد النهي وجمعه أوامر، وقوله: (بنهيه عن أمر) أي حال، وجمعه أمور."], [100, "صفحة 100\rإيمانُنا بيومٍ آخِرٍ وَجَبْ…وَكُلِّ مَا كَانَ بِهِ مِنَ العَجَبْ\r\rأي يجب على كل مكلف أن يصدق بوجود اليوم الآخر، وبجميع ما اشتمل عليه كالحشر والحساب والصراط والميزان والجزاء والجنة والنار والحوض والشفاعة. سُمِّيَ اليوم بذلك لأنه لا ليل بعده ولا نهار، ولا يقال يوم بلا تقييد إلا ما يعقبه ليل، أو لأنه آخر الأوقات المحدودة، أي آخر أيام الدنيا فليس بعده يوم آخَرُ، أو لتأخره عن الأيام المنقضية من أيام الدنيا، وأوله من النفخة الثانية إلى ما لا يتناهى، وهو الحق، وقيل إلى استقرار الخلق في الدارين: الجنة والنار، فمصدره من الدنيا وآخره من الآخرة، وهو يوم القيامة، وسمي به لقيام الموتى فيه من قبورهم، والقبر من الدنيا، وقيل: فاصل بين الدنيا والآخرة، وقيل: أوله من موت الميت، فالقبر من الآخرة، ولذا يقولون: من مات قامت قيامته أي الصغرى، وسمي قيامة على هذا القول، لقيام الميت فيه من الإضجاع إلى القعود لسؤال الملكين، ثم ضم القبر عليه، فأشبه يوم القيامة الكبرى، قال الزمخشري: أوله من وقت الحشر إلى ما لا يتناهى أو إلى أن يدخل أهلُ الجنة الجنةَ وأهلُ النار النارَ، ومقداره بالنسبة إلى الكفار خمسون ألف سنة لشدة أهواله، وهو أخف من صلاة مكتوبة في الدنيا بالنسبة إلى المؤمن الصالح، ويتوسط من عصاة المؤمنين. ثم"], [101, "صفحة 101\rاعلم أن أحوال الناس تختلف بالقول عند القيام من القبور، فبعضهم قالوا: يا ويلنا مَن بعثنا من مرقدنا؟ فتقول لهم الملائكة: هذا ما وعد الرحمن وصدق المرسلون. وبعضهم ينادي: يا حسرتا على ما فرطت في جنب الله، فوجهه يسود، وبعض أهل لا إله إلا الله ينفض رأسه من التراب ويقول: الحمد لله الذي أذهب عنا الحزن، وبعضهم الآخر يقول: لا إله إلا الله والحمد لله، فيبيض وجهه.\r\rقال بعض العلماء: يُحشر الناس عراة لقوله صلى الله عليه وسلم: (تحشرون يوم القيامة حفاة (أي بلا نعل)، عراة (أي بلا ثوب)، غُرْلاً) بضم الغين المعجمة والراء المهملة جمع أغرل، كحُمر جمع أحمر، أي غير مختونين. وقوله صلى الله عليه وسلم: (تُبعث الناسُ حفاة عراة ألجمهم العرق وبلغ شحوم الآذان)، وقال بعضهم: يحشرون في أكفانهم، لقوله صلى الله عليه وسلم: (إن الميت يُبعث في ثيابه التي يموت فيها). قال البيهقي: ويجمع بين هذه الروايات بأن بعضهم يحشر عارياً، وبعضهم بثيابه. وقال ابن حجر: إنهم يبعثون من قبورهم بثيابهم التي ماتوا فيها، ثم تتناثر عنهم عند ابتداء الحشر، ويحشرون عراة. وجمع بعضهم أيضاً بين هذه الروايات فقال: بعضهم يحشر كاسياً، وبعضهم يحشر عارياً، أو يحشرون كلهم عراة، ثم تكسى الأنبياء، وأول من يُكْسَى سيدنا إبراهيم، أو يخرجون من القبور بالثياب التي ماتوا فيها، ثم تتناثر عنهم عند ابتداء الحشر فيحشرون"], [102, "صفحة 102\rعراة، ثم يكون أول من يُكسى إبراهيم ثم بعده نبينا، والحكمة في تقدم إبراهيم بالكسوة أنه لما ألقي في النار جُرِّدَ من ثيابه، وكان ذلك في ذات الله وصبر ورضي، فجُوزي بأن جُعِلَ أولَ من يُدفع عنه العريُ يوم القيامة على رؤوس الأشهاد، ثم يُكسى سيدنا محمد صلى الله عليه وسلم حلةً أعظم من سيدنا إبراهيم لَيُجْبَرَ التأخيرُ بنفاسة الكسوة.\r\rومراتب الناس في المحشر متفاوتة؛ فمنهم الراكب، ومنهم الماشي على رجليه، ومنهم الماشي على وجهه، ويكونون على صور مختلفة على حسب الأعمال، فمنهم من يحشر وهو على صورة القردة وهم الزناة، ومنهم من يحشر على صورة الخنازير وهم أكلة السحت والمكس، ومنهم الأعمى وهو الجائر في الحكم، ومنهم الأصم وهو الذي يعجب بعمله، ومنهم من يمضغ لسانه متدلياً على صدره يسيل القيحُ من فمه وهم الوعاظ الذين تخالف أفعالهم أقوالهم، ومنهم المقطوع الأيدي والأرجل وهم الذين يؤذون الجيران، ومنهم من يصلب على جذوع من نار وهم السعاة بالناس إلى السلطان، ومنهم من هو أشد نتناً من الجيف وهم الذين يُقبلون على الشهوات واللذات أي المحرمة ويمنعون حق الله من أموالهم، ومنهم من يلبس جبة سابغة من قطران لاصقة بجلده وهم أهل الكبر والعجب والخيلاء."], [103, "صفحة 103\rواعلم أن المارين بالصراط مختلفون، فمنهم سالم بعمله، نَاجٍ من نار جهنم، وهم على أقسام؛ فمنهم من يجوز كلمح البصر، ومنهم من يجوز كالبرق الخاطف، ومنهم كالريح العاصف، ومنهم كالطير، ومنهم كالجواء السابق أي الفرس المسرع، ومنهم من يسعى سعياً، ومنهم من يمشي، ومنهم من يمشي حبواً أي على يديه وركبتيه، وذلك على قدر تفاوتهم في الأعمال الصالحة والإعراض عن المعاصي، فكل من كان أسرع إعراضاً عن المعاصي إذا مرت على خاطره كان أسرع مروراً، ومنهم من تخدشه الكلاليب فيسقط، ولكن يتعلق بها فيعتدل، ويمر ويجاوزه بعد أعوام، فمنهم من يَجوزه على مائة عام، ومنهم من يَجوزه على ألف عام وبقدرها يُعْطَوْنَ الأنوار، ومنهم غير السالم وهم متفاوتون أيضاً بقدر الجرائم، ثم منهم من يخلد في النار كالكفار، ومنهم من يخرج منها بعد مدة على حسب ما شاء الله تعالى وهم عصاة المؤمنين، بشفاعة النبي صلى الله عليه وسلم أو غيره من الأخيار، نسأل الله تعالى الشفاعة والتخفيف علينا بمنه وكرمه آمين.\r\rواعلم أن لكل رسول حوضاً تشرب منه أمته، وأعظمها حوض سيدنا محمد صلى الله عليه وسلم، وأن من شرب منه شربة لا يظمأ أبداً، سقانا الله منه. وأما تناول أهل الجنة الشراب فيها فهو للتلذذ لا للعطش؛ فإنهم إذا شربوا في الجنة وجدوا لكل نفسٍ لذةً خلافَ ما يجدونه من الآخر،"], [104, "صفحة 104\rوكذا إذا أكلوا فيجدون لكل لقمة لذة خلاف ما يجدونه من الأخرى.\r\rتنبيه\rقوله: (بيوم) بحذف التنوين للوزن، وقوله: (آخر) صفة له، وقوله: (به) الباء بمعنى في أي في ذلك اليوم، وقوله: (من العَجَب) بيان لِـ (ما) وهو بفتح العين والجيم وهو قياس مصدر عَجِبَ اللازم بكسر عين الفعل من باب تعب، يقال: عجبت من الشيء عجباً، قال ابن مالك في الخلاصة:\r\rوَفِعْلُ اللَّازِمُ بَابُهُ فَعَلْ…كَفَرَحٍ وَكَجَوىً وَكَشَلَلْ\r\rأي يجيء مصدر فعل مكسور العين إذا كان لازماً على فعل بفتح الفاء والعين قياساً، سواء كان صحيحاً أو معتلاً أو مضاعفاً، نحو فرح فرحاً وَجَوِيَ جَوىً وَشَلِلَ شللاً، ومعنى جوى أي حرق من عشق أو حزن."], [105, "صفحة 105\rالفصل السادس\rفي نبينا محمد صلى الله عليه وسلم"], [107, "صفحة 107\rخاتمةٌ في ذِكْرِ باقي الواجبِ…مِمَّا على مُكَلَّفٍ مِنْ واجبِ\r\rأي هذه خاتمة نسأل الله حُسْنَهَا؛ فالخاتمة هي ما تُذكر لإفادة ما يتعلق بالمقصود، وكان ذلك التعلقُ تعلقَ اللاحق بالسابق، أي التعلق من حيث زيادة التوضيح والتكميل، وكذلك المقدمة، لكن كان ذلك التعلق فيها تعلقَ السابق باللاحق، أي التعلق من حيث الإعانة في الشروع على وجه البصيرة، بخلاف التقسيم، فإنه يُذكر لإفادة المقصود.\r\rقوله: (مما على مكلف) من للتعليل لقوله (ذِكْر) على حد قوله تعالى: {مِّمَّا خَطِيئَاتِهِمْ أُغْرِقُوا} وما موصولة. وقوله: (على مكلف) متعلق بقوله من واجب. قوله: (من واجب) من زائدة، وواجب خبر لمبتدأ محذوف، والجملة من المبتدأ والخبر صلة الموصول، وتقدير الكلام: وإنما ذكرت باقي الواجب لأجل الذي هو واجب على مكلف."], [108, "صفحة 108\rنبيُّنا محمدٌ قد أُرْسِلَا…لِلْعَالَمِيْنَ رحمةً وَفُضِّلَا\r\rأي يجب على كل مكلف أن يعتقد أن سيدنا محمداً صلى الله عليه وسلم أرسله الله تعالى رحمة للعالمين، وقد أرسله الله تعالى إلى جميع المكلفين من الثقلَين أي الإنس والجن إجماعاً معلوماً من الدين بالضرورة، فيكفر جاحده، وخرج بالثقلين الملائكة؛ فإنه لم يُرْسَلْ إليهم إرسالَ تكليف، بل أرسل إليهم وإلى غيرهم من سائر الحيوانات والجمادات إرسال تشريف؛ لأن طاعاتهم جِبِلِّيَّةٌ لا يكلفون بها، وهذا هو الذي اعتمده محمد الرملي وخالفه الشيخ ابن حجر تبعاً لجمع محققين كالسبكي ومن تبعه فقال: إنه صلى الله عليه وسلم مرسلٌ إليهم إرسالَ تكليف لما يليق بهم، فإن منهم الراكع والساجد إلى يوم القيامة، وما كُلِّفَ به الإنسُ تفصيلاً وإجمالاً فقد كُلِّفَ به الجن كذلك، وشمل ذلك يأجوج ومأجوج، والتحقيق أنه صلى الله عليه وسلم مرسل لجميع الأنبياء والأمم السابقة لكن باعتبار عالم الأرواح، فإن روحه خُلقت قبل الأرواح، وأرسلها الله إليهم فبلغت الجميع، والأنبياء نُوَّابُهُ في عالم الأجسام، فهو صلى الله عليه وسلم مرسلٌ لجميع الناس من لدن آدم إلى يوم القيامة، حتى إلى نفسه لدخول الجميع تحت قوله: بعثت إلى الناس كافة، وقوله تعالى: {وَمَا أَرْسَلْنَاكَ إِلَّا كَافَّةً لِّلنَّاسِ}، فمن نفى عموم بعثته صلى الله عليه وسلم فقد كفر، قال ذلك الباجوري، وقال أيضاً: والراجح أنه مرسل إلى الملائكة إرسال تشريف،"], [109, "صفحة 109\rوإن رَجَّحَ بعضُهم هنا خلافه .. وأما إرساله إلى سائر الحيوانات فإرسال تشريف قطعاً أي بلا خلاف.\r\rقوله: (للعالمين) اسم جمع لعالَم بفتح اللام وهو اسم لما سوى الله وصفاته من الموجودات، فيشمل الملائكة والإنس والجن والجمادات، لكن إرساله إلى الملائكة إرسال تشريف لهم لعدِّهم من أمته لا تكليف بشريعته، وإلى الجمادات إرسال تأمين لها من الخسف بها ونحوه. قاله محمد بن أحمد عليش. قوله: (وَفُضِّلَا) أي ويجب على كل مكلف أن يعتقد أنه صلى الله عليه وسلم أفضل الأنبياء والمرسلين، وسيدهم بشهادة قوله تعالى: {وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ}، وقوله صلى الله عليه وسلم: (أنا سيد العالمين يوم القيامة ولا فخر، أنا صاحب لواء الحمد يوم القيامة ولا فخر .. آدمُ فمَن دونَه تحت لوائي يوم القيامة ولا فخر)، أي أعظم من هذا، أو المعنى: لا أقول ذلك فخراً بل تحدثاً بالنعمة. قال عمر بن الفارض من بحر الرجز:\r\rمن ذا الذي ما ساء قط…ومن له الحسنُ فقط\r\rفأجابه الهاتف وهو الذي يُسمع صوتُه ولا يُرَى شخصُه بقوله:\r\rمحمدُ الهادي الذي…عليهِ جبريلُ هَبَطْ\r\rفقول الناظم: (نبينا) مبتدأ، و (محمد) عطف بيان عليه أو بدل كل، وجملة قوله: (قد أرسلا) من الفعلِ ونائبِ الفاعل"], [110, "صفحة 110\rخبرُ المبتدأ، وقوله: (للعالمين) متعلق برحمة بعده، ورحمة: حال من نائب فاعل أُرسل."], [111, "صفحة 111\rأبوهُ عبدُ اللهِ عبدُ المطلبْ…وهاشمٌ عبدُ منافٍ يَنْتَسِبْ\r\rوَأُمُّهُ آمنةُ الزُّهْرِيَّةْ…أَرْضَعَهُ حليمةُ السعديةْ\r\rأي يجب على كل مكلف معرفة نسبه صلى الله عليه وسلم من جهة أبيه إلى عدنان فقط، ومن جهة إمه إلى كلاب فقط، إذ ما بعده يشترك فيه نسب أبيه وأمه، قاله البيجوري. وقد نظم بعضهم نسبه صلى الله عليه وسلم من جهة أبيه ومن جهة أمه من بحر الرجز في عشرة أبيات فقال:\r\rعِشرونَ جَدّاً مِنْ جُدُوْدِ المصطفى…يَجِبْ علينا حِفْظُهُمْ بلا خَفَا\r\rخُذْهُمْ على الترتيبِ عبدُ المُطَّلِبْ…فهاشمٌ عبدُ منافِ افهمْ تُصِبْ\r\rقُصَيُّ مع كلابٍ ثم مُرَّهْ…كعبٌ لؤيٌّ غالبٌ ذو مُرَّهْ\r\rفِهْرٌ يَليه مالكٌ وَالنَّضْرُ…كِنانةٌ خُزيمةٌ مُشْتَهَرُ\r\rمُدْرِكَةٌ إلياسُ منهمْ مَعْ مُضَرْ…نزارُ مع مَعَدٍّ جاء في الخبرْ\r\rوَضِفْ لهم عدنانَ يا فصيحُ…كيما يَتِمُّ النسبُ الصحيحُ\r\rمن جهةِ الآبا وأيضاً نسبتُهْ…من جهةِ الأم تجبْ معرفتُهْ\r\rأُمُّ النبيِّ صاحبِ المفاخرِ…آمنةٌ بنتٌ لوهبِ الطاهرِ\r\rابْنٌ لعبدِ منافٍ عالي القَدْرِ…ابْنٌ لزهرةَ مع كلابٍ فَادْرِ\r\rفَأُمُّ طه مع أبيهِ تجتمعْ…في جَدِّهِ كلابِ يا هذا اسْتَمِعْ\r\rفاسم عبد المطلب عامر وقيل شيبة الحمد، واسم"], [112, "صفحة 112\rهاشم عمرو العلا لعلو مرتبته، وَلُقِّبَ بهاشم لهشمه الثريد للناس في مجاعة أصابتهم، واسم عبد مناف المغيرة، ومناف أصله بالتاء المثناة فوق اسم صنم كان أعظم أصنامهم، وكانت أمه جعلته خادماً لذلك الصنم، واسم قصي زيد وقيل يزيد، وقيل مُجَمِّع منقول من اسم فاعل (جمَّع) المشدد لأنه كان يجمع قومه يوم العروبة - أي الجمعة - فيذكرهم ويأمرهم بتعظيم الحرم، ويخبرهم أنه سيبعث فيه نبي، وبه جمع الله القوم من بني فهر في مكة بعد تفرقهم في البلاد، واسم كلاب حكيم وقيل عروة وقيل المهدب وقيل اسمه المغيرة، ولقب بكلاب لأنه كان يحب الصيد وكان أكثر صيده بالكلاب، ولؤي بالهمزة أكثر من عدمها، تصغير (لِئْيٍ) كفلس وهو البطء عند العجلة، وَفِهْرٌ بكسر فسكون، وهو في الأصل اسم للحجر الطويل، وسُمي به لطوله، وكان يسمى قريشاً لأنه كان يقرش أي يفتش عن خلة المحتاج فيسدها بماله، ومالك هو اسمه، سُمي به لأنه ملك العرب، وكان يُكنى بأبي الحرث، واسم النضر قيس، وإنما لُقِّبَ بذلك لنضارته وحسنه، واسم مدركة عمرو، وكان فيه نور النبي صلى الله عليه وسلم ظاهراً، وإلياس بهمزة قطع مكسورة وقيل مفتوحة وقيل همزة وصل، ونسب للجمهور، واسمه حسين، وسُمي بذلك لأنه ولد بعد كبر سن أبيه، واسم مُضَرَ بضم ففتح عمرو وكنيته أبو إلياس، وإنما قيل له ذلك لأنه كان يحب شرب اللبن الماضر أي الحامض، واسم نزار خلذان،"], [113, "صفحة 113\rوإنما سمي بذلك لأنه لما نظر أبوه إلى نور النبي بين عينيه فرح فرحاً شديداً ونحر وأطعم وقال: هذا نزر - أي قليل - لحق هذا المولود، ومعد كنيته أبو قضاعة، وإنما قيل له ذلك لأنه كان معداً للحروب، وعدنان هو من العَدْنِ أي الإقامة، وسمي بذلك تفاؤلاً بأنه يقيم ويسلم من أعين الجن والإنس التي يموت بها غالب من في القبور، وكان في زمن موسى عليه السلام.\r\rتنبيه\rقوله: (أبوه عبد الله) أي أبو نبينا محمد صلى الله عليه وسلم عبد الله، ومات بالمدينة حال رجوعه من غزة، وكان سافر لتجارة وعمره ثماني عشرة سنة، وقيل عشرون وقيل خمس وعشرون وقيل ثمان وعشرون وقيل ثلاثون، وأمه وقت ذلك حبلى به لشهرين، وقيل وهو ابن سبعة أشهر، وقيل ابن تسعة أشهر، وقيل ابن ثمانية وعشرين شهراً، والراجح المشهور الأول، وعن ابن عباس: أنه لما توفي عبد الله قالت الملائكة: إلهنا وسيدنا بقي نبيك يتيماً، فقال الله تعالى: (أنا حافظ له ونصير)؛ وسئل جعفر الصادق عن حكمة ذلك فقال: لئلا يكون عليه صلى الله عليه وسلم حق واجب لمخلوق، وقال ابن العماد: لينظر النبي صلى الله عليه وسلم إذا وصل إلى مدارج عزه إلى أوائل أمره، ويعلم أن العزيز من أعزه الله تعالى، وإن قوته ليست من الآباء والأمهات، ولا من المال، بل قوته من الله تعالى، وأيضاً ليرحم الفقراء والأيتام. قال صلى الله عليه وسلم: (ارحموا"], [114, "صفحة 114\rاليتامى وأكرموا الغرباء، فإني في حال الصغر كنت يتيماً وفي الكبر غريباً .. إن الله لينظر للغريب كل يوم ألف نظرة).\r\rثم اعلم أن التي أرضعته صلى الله عليه وسلم أولاً أمه ثلاثة أيام، وقيل سبعة، وقيل تسعة، ثم أرضعته ثويبة أياماً قلائل قبل قدوم حَليمة، ثم أرضعته حَليمة بنت أبي ذؤيب عبد الله بن الحرث، وقيل الحرث بن عبد الله.\r\rذُكِرَ أنه لمّا ولد صلى الله عليه وسلم قيل: من يكفل هذه الدرة اليتيمة التي لا يوجد لمثلها قيمة؟ فقالت الطيور: نحن نكفله، ونغتنم خدمته العظيمة، وقالت الوحوش: نحن أولى بذلك ننال شرفه وتعظيمه، فنادى لسان القدرة: أن يا جميع المخلوقات إن الله كتب في سابق حكمته القديمة أن نبيه الكريم يكون رضيعاً لحليمة بنت أبي ذؤيب، وذكر أن عبد المطلب سمع وقت دخول حليمة هاتفاً يقول شعراً من بحر الكامل:\r\rإِنَّ ابْنَ آمنةَ الأمينَ محمداً…خَيْرُ الأنامِ وخيرةُ الأخيارِ\r\rمَا إِنْ لَهُ غيرُ الحَليمةِ مُرْضِعٌ…نِعْمَ الأمينةُ هِيْ على الأبرارِ\r\rمأمونةٌ مِنْ كُلِّ عَيْبٍ فاحشٍ…وَنَقِيَّةُ الأثوابِ والآزارِ\r\rلا تُسْلِمَنْهُ إلى سِواها إنهُ…أمرٌ وَحُكْمٌ جَا مِنَ الجَبَّارِ\r\rفرع\rقال الباجوري: فالحق الذي نلقى الله عليه أن أبويه صلى الله عليه وسلم ناجيان، على أنه قيل إنه تعالى أحياهما حتى آمنا"], [115, "صفحة 115\rبه، ثم أماتهما لحديث ورد في ذلك، وهو ما روي عن عروة عن عائشة: أن رسول الله صلى الله عليه وسلم سأل ربه أن يحيي له أبويه فأحياهما فآمنا به ثم أماتهما. قال السهيلي: والله قادر على كل شيء له أن يخص نبيه بما شاء من فضله، وينعم عليه بما شاء من كرامته، وقد أنشد بعضهم من بحر الوافر فقال:\r\rحَبَا اللهُ النبيَّ مزيدَ فضلٍ…على فضلٍ وكان به رَؤوفا\r\rفأحيا أُمَّهُ وكذا أباهُ…لإيمانٍ به فضلاً مُنِيْفَا\r\rفَسَلِّمْ فالقديمُ بذا قديرٌ…وإن كان الحديثُ به ضعيفَا\r\rولعل هذا الحديث صح عند أهل الحقيقة بطريق الكشف، كما أشار إليه بعضهم من بحر الكامل:\r\rأيقنتُ أَنَّ أبا النبيِّ وَأُمَّهُ…أحياهُما الرَّبُّ الكريمُ الباري\r\rحتى له شَهِدَا بصدقِ رسالةٍ…صَدِّقْ فتلكَ كرامةُ المختارِ\r\rهذا الحديثُ وَمَنْ يقولُ بِضَعْفِهِ…فَهْوَ الضعيفُ عَنِ الحقيقةِ عاري\r\rقوله: (الزُّهْرِيَّةُ) منسوبة لزُهْرة بضم الزاي وسكون الهاء، وهو اسم رجل على الصواب، وأخطأ من جعله اسم امرأة، وهو الجد الثاني لآمنة، وقوله: (السَّعْدِيَّةُ) بفتح السين المهملة وسكون العين المهملة وشد المثناة تحت، أي المنسوبة إلى سعد بن أبي بكر، وهو اسم أبي قبيلة حليمة، وقوله: (أرضعه) بحذف تاء التأنيث للوزن."], [116, "صفحة 116\rثم اعلم أن الفعل إن لم يفصل بينه وبين فاعله الظاهر الحقيقي التأنيث وجب تأنيثه ليدل على تأنيث الفاعل، وإن فصل بينهما بغير (إلا) جاز تأنيثه وعدمه، لكن الأحسن تأنيثه، وأما في هذه المنظومة فيتعين التذكير للوزن، قال ابن مالك في الخلاصة:\r\rوَتَاءُ تأنيثٍ تَلِيْ الماضي إذا…كَانَ لأنثى كَأَبَتْ هندُ الأذى\r\rوقد يُبِيْحُ الفَصْلُ تَرْكَ التَّاءِ فِيْ…نَحْوِ أتى القاضيَ بنتُ الوَاقِفِ\r\rقوله: (أتى) فعل ماض، والقاضي مفعول مقدم على فاعله، وبنت فاعل أتى. واعلم أن اسم الفاعل من أرضع يقال فهو مرضع بالتذكير، ومرضعة بالتأنيث أيضاً، قال الفراء وجماعة: إن قصد حقيقة الوصف بالإرضاع فمرضع بغير هاء، وإن قصد مجاز الوصف بمعنى أنها محل الإرضاع فيما كان أو سيكون فبالهاء."], [117, "صفحة 117\rمولدُهُ بمكةَ الأمينةْ…وفاتُهُ بطَيبةَ المدينةْ\r\rأي يجب على كل مكلف أن يعتقد أن النبي صلى الله عليه وسلم ولد بمكة وأرسل فيها، وتوفي بالمدينة ودفن فيها. قوله: (الأمينة) صفة لمكة، وصفت بالأمينة لأمن الناس فيها جاهلية وإسلاماً، ولأن الله تعالى جعلها حرماً لا يُسْفَكُ فيه دم إنسان، ولا يظلم فيه أحد، ولا يصاد صيده، ولا يقطع حشيشه الرطب إلا لدواء. قوله: (المدينة) بَدَلٌ من طيبة، بدل كل من كل، لأن طيبة اسم من أسماء مدينة الرسول، ولها أسماء كثيرة نحو ثمانين اسماً مذكورة في خلاصة الوفاء. قوله: (بمكة) و (بطيبة) هما ممنوعان من الصرف للتأنيث والعلمية، فالباء فيهما بمعنى في.\r\rواعلم أنه صلى الله عليه وسلم ولد على الصحيح عند طلوع الفجر، يوم الاثنين لاثنتي عشرة ليلة مضت من ربيع الأول عام الفيل، قيل يوم الفيل، وقيل قبله. وقال القرطبي بعده بخمسين يوماً، وولد صلى الله عليه وسلم رافعاً بصره إلى السماء واضعاً يديه بالأرض مكحولاً نظيفاً مسروراً، أي مقطوع السرة، مختوناً أي على صورة المختون، وقيل ختنه جَدُّهُ سابع ولادته، وجمع بينهما بأنه يجوز أن يكون ولد مختوناً ختاناً غير تام، كما هو الغالب في المولود مختوناً، فتمم جده ختانه، وقيل ختنه جبريل يوم شق قلبه عند مرضعته حليمة. وروي أنه صلى الله عليه وسلم تكلم عند خروجه"], [118, "صفحة 118\rمن بطن أمه فقال: جلال ربي الرفيع، وقيل: قال: الله أكبر كبيراً، والحمد لله كثيراً، وسبحان الله بكرة وأصيلاً. ويمكن الجمع بينهما. وروي الخلاف في محل خروجه صلى الله عليه وسلم من بطن أمه، فقيل إنه خرج من المحل المعتاد، وقيل إنه خرج من تحت سرتها، فالتأمت في الحال، ومال إلى هذا شيخُنا محمد حسب الله. وروي الخلاف أيضاً في حمل أمه صلى الله عليه وسلم به، فقيل إنها لم تجد لحمله صلى الله عليه وسلم أعظم الثقل، والرواية المشهورة أنها لم تجد لذلك شيئاً، وجُمع بين الروايتين بأن الأول في أول الحمل والآخر في آخره؛ لتقع مخالفة العادة فيهما حتى يُعلم أن كل أموره صلى الله عليه وسلم خارقةٌ للعادة، كما قال ابن حجر: قالت آمنة: لما مضى لي من الليالي والأيام تسعة أشهر على التمام، أخذني ما يأخذ النساء من الطلق ولم يدر بي أحد من الخلق، وإني وحيدة في منزلي، وعبد المطلب في طوافه لا يعلم انقضاء حَبَلِيْ، رأيت قطعة من الطير مناقيرها من الياقوت الأحمر، قد غطت حجرتي بأجنحة كالزمرد الأخضر.\r\rتنبيه\rقد انعقد الإجماع على أن مكة والمدينة أفضل البقاع، واتفق الأئمة الثلاثة على أن مكة أفضل من المدينة، وَعَكَسَ مالك، والخلاف في غير البقعة الشريفة التي تضمنت أعضاءه صلى الله عليه وسلم. وإلا فهي أفضل من السماوات والأرض جميعاً قطعاً، ومن خواص اسم مكة"], [119, "صفحة 119\rأنه إذا كتب على جبين المرعوف بدم الرعاف: مكة وسط البلاد والله رؤوف بالعباد، انقطع الدم، ذكره البيجوري في حاشيته على الشمائل."], [120, "صفحة 120\rأتمَّ قبلَ الوحيِ أربعينا…وعمرُه قد جاوزَ الستينا\r\rأي والصحيح الذي عليه الجمهور أنه صلى الله عليه وسلم بُعث عند استكمال أربعين من غير زيادة ولا نقص، ولكن هذا لا يتم إلا إذا كانت البعثة في شهر الولادة، مع أن المشهور أنه ولد في ربيع الأول، وبعث في رمضان الواقع بعد السنة المتممة لأربعين، فمن قال: أربعون سنة، ألغى الكسر على الأول أو جبره على الثاني، قال بعضهم: كان ابتداء الوحي بالمنام في ربيع، ومكث ستة أشهر، ومن قال: كان ابتداؤه في رمضان، أراد أن مجيء جبريل يقظة، فرجع الخلاف لفظياً ولا كسر، والصحيح أن نبوته ورسالته صلى الله عليه وسلم مقترنتان، وقال ابن عبد البر وغيره: أرسله الله لما بلغ ثلاثاً وأربعين سنة، فكانت النبوة سابقة بنزول اقرأ، وكانت الرسالة بأمره بالإنذار لما نزلت آية المدثر، فهو في زمن فترة الوحي نبي لا رسول، وأجاب القائلون باقترانهما بأن آية المدثر تبيان للمراد من سورة اقرأ؛ لأن المعنى اقرأ على قومك ما سأبينه لك، وإنما كان الإرسال على رأس الأربعين لأنه عادة مستمرة في أكثر الأنبياء أو جميعهم، كما جزم بالثاني كثير، منهم شيخ الإسلام في حواشي البيضاوي، قاله الباجوري. ومكث صلى الله عليه وسلم بعد البعثة بمكة ثلاث عشرة سنة يوحى إليه، أي باعتبار مجموعها، لأن مدة فترة الوحي وهي ثلاث سنين من جملتها وهو"], [121, "صفحة 121\rالأصح. وروي أنه لبث بعد البعثة في مكة عشر سنين، وهو محمول على ما عدا مدة فترة الوحي، وأقام صلى الله عليه وسلم بالمدينة عشراً، وتوفي وهو ابن ثلاث وستين، أي فإنهم اتفقوا على أنه صلى الله عليه وسلم أقام بالمدينة بعد الهجرة عشر سنين، كما اتفقوا على أنه صلى الله عليه وسلم أقام بمكة قبل البعثة أربعين سنة، وإنما الخلاف في قدر إقامته بمكة عند البعثة، والصحيح أنه ثلاث عشرة سنة، فيكون عمره الشريف ثلاثاً وستين سنة، قاله البيجوري عن المواهب اللدنية."], [122, "صفحة 122\rوسبعةٌ أولادُه فمنهمُ…ثلاثةٌ مِنَ الذكورِ تُفْهَمُ\r\rقاسمْ وعبدُ اللهِ وهو الطيبُ…وطاهرٌ بذينِ ذا يُلَقَّبُ\r\rأَتَاهُ إبراهيمُ من سُرِيَّةْ…فَأُمُّهُ مَارِيَّةُ القِبْطِيَّةْ\r\rوغيرُ إبراهيمَ مِنْ خديجةْ…هم ستةٌ فخذْ بهمْ وَلِيْجَةْ\r\rوأربعٌ مِنَ الإناثِ تُذْكَرُ…رضوانُ ربي للجميعِ يُذْكَرُ\r\rفاطمةُ الزهراءُ بعلُها عليْ…وابناهما السِّبْطَانِ فضلُهم جَلِيْ\r\rفزينبٌ وبعدَها رُقَيَّةْ…وَأُمُّ كُلثومٍ زَكَتْ رَضِيَّةْ\r\rقال الشيخ محمد الفضالي في كفاية العوام: قال العلماء: وينبغي أن يعرف كُلُّ شخص عدة أولاده صلى الله عليه وسلم وترتيبهم في الولادة، لأنه ينبغي للشخص أن يعرف ساداته أي عدة وترتيباً، لكن لم يصرحوا فيما رأيت بوجوب ذلك وندبه، بل صرحوا بأنه ينبغي فقط، وهو محتمل للوجوب والندب، لكن القياس على نظائره كَنَسَبِهِ صلى الله عليه وسلم الوجوب، وأولاده صلى الله عليه وسلم سبعة: ثلاثة ذكور، وأربع إناث على الصحيح، وترتيبهم في الولادة: القاسم، وَكُنِّيَ صلى الله عليه وسلم به، ثم زينب، ثم رُقَيَّة، بضم الراء وفتح القاف والياء المشددة وهي ذات جمال، ثم فاطمة، ثم أم كُلثوم بضم الكاف، وقال البيجوري: فلا يُعرف لها اسم، وقال الصبان: واسمها كنيتها، ثم عبد الله، وهو"], [123, "صفحة 123\rالملقب بالطيب والطاهر، فهما لقبان لعبد الله لا اسما شخصين مغايرين له، وكلهم من سيدتنا خديجة، والرابع سيدنا إبراهيم من مارية القبطية. انتهى.\r\rوقد نظم بعضهم من الرجز أولاده صلى الله عليه وسلم على ترتيبهم في الولادة، وَذَيَّلَهَا ببيت ذكر فيه أن كلهم من سيدتنا خديجة إلا سيدنا إبراهيم فمن مارية القبطية فقال:\r\rأولادُ طه قاسمٌ فزينبُ…رُقَيَّةٌ ذَاتُ الجمالِ البَاسِمَةْ\r\rفَأُمُّ كُلثومٍ ففاطمةٌ فعبدُ الله إبراهيمُ وهو الخاتِمةْ\r\rوَأُمُّهُمْ خديجةٌ إلا ابْرَهَمْ…فَأُمُّهُ مَارِيَّةٌ كُنْ عَالِمَهْ\r\rففي هذا النظم تقديم أم كلثوم على فاطمة بخلاف ما نقل عن محمد الفضالي، فإنه بعكس. قوله: (إلا ابرهم) في هذا النظم بدرج الهمزة وبحذف الألف بعد الراء وحذف الياء بعد الهاء للوزن. انتهى. فأما القاسم فمات بمكة وقد بلغ سنتين، وقيل أقل، وقيل أكثر، وهو أول ميت مات من ولده، ثم عبد الله مات أيضاً بمكة صغيراً، ولما مات قال العاص بن وائل: قد انقطع ولده فهو أبتر، فأنزل الله تعالى: {إِنَّ شَانِئَكَ هُوَ الأبْتَرُ}، أي مبغضك يا أشرف الخلق هو المنقطع عن كل خير، أو المنقطع النسل، وأما إبراهيم فولد في ذي الحجة سنة ثمان من الهجرة، وَعَقَّ صلى الله عليه وسلم عنه يوم سابعه بكبشين، وَسَمَّاهُ يومئذ، وحلق شعره وتصدق بزنة شعره فضة، ودفنوا شعره في الأرض، ومات"], [124, "صفحة 124\rسنة عشر وقد بلغ سنة وعشرة أشهر، وقيل سنة وستة أشهر، ودفن بالبقيع.\r\rوأما زينب فتزوجها ابن خالتها أبو العاص بن الربيع وأمه هالة بنت خويلد، فوَلدت له علياً وأمامة، فأما علي فأردفه النبي صلى الله عليه وسلم وراءه يوم الفتح ومات مراهقاً، وأما أمامة فتزوجها علي بن أبي طالب بعد خالتها فاطمة بوصية من فاطمة، وتزوجها المغيرة بن نوفل بعد موت علي بوصية من علي، فولدت له يحيى بن المغيرة، وماتت عنده، وكان صلى الله عليه وسلم يحبها كثيراً حتى حملها في الصلاة. وُلدت زينب سنة ثلاثين من مولده صلى الله عليه وسلم وماتت سنة ثمان من الهجرة، وأما رقية فتزوجها عثمان بن عفان، وَلدت له عبد الله، مات بعدها وقد بلغ ست سنين، نَقَرَهُ ديكٌ في عينه فورم وجهه فمات. وُلدت رقية سنة ثلاث وثلاثين من مولده صلى الله عليه وسلم، وماتت يوم قدوم زيد بن حارثة المدينة بقتلى بدر من المشركين، ولما عُزِّيَ فيها رسول الله صلى الله عليه وسلم قال: (الحمد لله، دفن البنات من المكرمات). [1] وأما أم كلثوم فتزوجها"], [125, "صفحة 125\rعثمان بعد موت رقية، ولهذا سمي ذا النورين. روى ابن ماجه وابن حبان عن أبي هريرة قال: أتى النبي صلى الله عليه وسلم عثمان عند باب المسجد فقال: (يا عثمان هذا جبريل لقد أمرني أن أزوجك أم كلثوم بمثل صداق رقية)، ولم تلد له. ماتت سنة تسع من الهجرة، ولما ماتت قال عليه الصلاة والسلام: (زوجوا عثمان .. لو كان لي ثالثة زوجته إياها، وما زوجته إلا بوحي من الله تعالى).\r\rوأما فاطمة فتزوجها علي وهو ابن إحدى وعشرين سنة وخمسة أشهر، وهي بنت خمس عشرة سنة وخمسة أشهر عقب رجوعهم من بدر، وتوفيت بعد أبيها بستة أشهر على الصحيح ليلة الثلاثاء لثلاث مضين من رمضان سنة إحدى عشرة، ودفنها علي ليلاً. وحُكي أن فاطمة الزهراء بنتَ النبي صلى الله عليه وسلم لما ماتت حمل جنازتَها أربعةُ نفر: زوجها علي وابناهما الحسن والحسين وأبو ذر الغفاري رضي الله تعالى عنهم أجمعين، فلما وضعوها على شفير القبر قام أبو ذر فقال: يا قبر أتدري من التي جئنا بها إليك؟ هذه فاطمة الزهراء بنت رسول الله صلى الله عليه وسلم، وزوجة علي المرتضى، وأم الحسن والحسين، فسمعوا نداءً من القبر يقول: ما أنا موضع حسب ونسب، وإنما أنا موضع العمل الصالح، فلا"], [126, "صفحة 126\rينجو مني إلا من كَثُرَ خيره، وسلم قلبه، وخلص عمله. انتهى. وقد كان خَطَبَهَا أبو بكر ثم عمر، فأعرض صلى الله عليه وسلم عنهما، فلما خطبها علي أجابه وجعل صداقَها دِرْعَهُ، ولم يكن له غيرُها، وبيعت بأربعمائة درهم وثمانين درهماً. وقد وَلدت فاطمة من علي رضي الله عنهما ستة: ثلاثة ذكور، وثلاث إناث. فالذكور: الحسن والحسين وَالمُحَسِّنُ بضم الميم وفتح الحاء وتشديد السين مكسورة. والإناث: زينب وأم كلثوم ورقية. كذا زاد الليث بن سعد رقية، قال: وماتت ولم تبلغ، نقله ابن الجوزي، ونقل الشيخ حسن العدوي عن المواهب اللدنية أن الزهراء وَلَدَتْ لعلي حسناً وحسيناً ومحسناً، فمات صغيراً، وأم كلثوم وزينب، فجملة ولدها خمسة، وأما سيدنا الحسن سبط رسول الله صلى الله عليه وسلم فولد قبل وفاة جده بثمان سنين، وولد الحسين قبلها بسبع. وفي رواية: وُلِدَ الحسين لخمس بقين من شعبان سنة أربع على الأصح، وكانت فاطمة علقت به بعد ولادة الحسن بخمسين ليلة، حنكه صلى الله عليه وسلم بريقه، وَأَذَّنَ في أذنه، وتفل في فمه، ودعا له، وسمَّاه حسيناً يوم السابع، وَعَقَّ عنه. ونقل الزرقاني عن ابن الأثير: وُلدتْ زينب في حياة جَدِّهَا، وكانت لبيبةً جزلةً عاقلةً لها قوة جنان. قال ابن عبد البر: وُلدت أم كلثوم قبل وفاة جدها صلى الله عليه وسلم. ثم اعلم أن أم كلثوم تزوجها عمر بن الخطاب، فولدت له زيداً ورقية. ورُوي أن عمر خطب إلى علي بنته أم كلثوم، فذكر له صِغَرَهَا، فعاوده، فقال"], [127, "صفحة 127\rعليّ: أبعث بها إليك، فإن رَضِيْتَ فهي امرأتك، فأرسلها إليه، فكشف عن ساقها فقالت: مه، ولولا أنك أمير المؤمنين للطمت عينك. وفي رواية: لمّا خطبها من علي قال له: إنها صغيرة، فقال عمر: زوِّجنيها يا أبا الحسن، فإني أرصد من كرامتها ما لا يرصده أحد. قال: فلما قال له ذلك، قال علي: أبعثها إليك، فإن رضيتَ فقد زَوَّجْتُكَهَا، فبعثها إليه ببردة وقال لها: قولي له: هذه البردة التي قلتُ لك عليها، فقالت لعمر رضي الله تعالى عنه ذلك، فقال لها: قولي له: قد رضيتُ رضي الله عنك، ووضع يده على ساقها فكشفها، فقالت: أتفعل هذا؟ لولا أنك أمير المؤمنين لكسرت عينك، ثم خرجت حتى جاءت إلى أبيها فأخبرته بذلك فقالت: بعثتَني إلى شيخ سوء، فقال: يا بنية إنه زوجك، ثم بعد موت عمر تزوجها عون بن جعفر بن أبي طالب، وبعد موت عون تزوجها محمد أخوه، وبعد موت محمد تزوجها أخوه عبد الله بن جعفر، وبعد موتها تزوَّج أختها زينب فولدت له علياً وعوناً الأكبر وعباساً ومحمداً وأم كلثوم، وذريتُها موجودة إلى الآن بكثرة.\r\rتنبيه\rقوله: (وسبعة) خبر مقدم، وقوله: (أولاده) مبتدأ مؤخر، وقوله: (تُفهم) تكملة للبيت، وقوله: (من سُرية) بضم السين وهي الأمَة المنسوبة إلى السِّرِّ بالكسر وهو الجماع، وهو من تغيير النسب كما في القاموس، وقال في المصباح:"], [128, "صفحة 128\rوالسُرية قيل مأخوذة من السر وهو النكاح، فالضم على غير قياس فرقاً بينها وبين الحرة إذا نُكِحَتْ سراً، فإنه يقال لها سِرِّية بالكسر على القياس. وقيل من السُّر بمعنى السرور لأن مالكها يُسَرُّ بها فهو على القياس. وقوله: (فأمه مارية القبطية) أي أن سيدتنا ماريةَ سُريةٌ له صلى الله عليه وسلم، أهداها له المقوقس القبطي صاحب مصر والإسكندرية، وأهدى معها أختها سيرين وخصياً يقال له مأبور، وألف مثقال من ذهب، وعشرين ثوباً ليناً، وبغلة شهباء وهي دلدل، وحماراً أشهب وهو عفير ويقال له يعفور، وَهَبَ رسولُ الله صلى الله عليه وسلم سيرين لحسان بن ثابت الأنصاري، وكان عليه الصلاة والسلام معجباً بمارية لأنها كانت بيضاء جميلة، وتوفيت هي في خلافة أمير المؤمنين عمر بن الخطاب رضي الله عنه، وذلك في شهر الله المحرم، وكان عمر يحشر الناس إلى جنازتها بنفسه، وصلى عليها عمر رضي الله عنه.\r\rقوله: (خديجة) وهي بنت خويلد، وهي أول أزواج النبي صلى الله عليه وسلم وعمره حين تَزَوُّجِهِ إياها إحدى وعشرون سنة، أو خمس وعشرون سنة، وعليه الأكثر. ولها من العمر يومئذ أربعون سنة، خَطَبَتْهُ بلا واسطة، أي عَرَضَتْ عليه نفسَها، فقالت: يا ابن عم، إني قد رغبت فيك لقرابتك وعدلك في قومك، وأمانتك وحسن خلقك وصدق حديثك، فذكر ذلك عليه الصلاة والسلام لأعمامه فخرج معه حمزة حتى دخل على خويلد بن أسد فخطبها،"], [129, "صفحة 129\rهذا عند ابن إسحاق، أو بواسطة كما رواه ابن سعد من طريق الواقدي، عن نفيسة بنت منية: كانت خديجة امرأةً حازمةً جَلِدَةً أي قوية شريفة، مع ما أراد الله تعالى بها من الكرامة والخير، وهي يومئذ أوسطُ قريش نسباً، وأعظمُهم شرفاً، وأكثرُهم مالاً، وكل قومها كان حريصاً على نكاحها لو قدر على ذلك، قد طلبوها وبذلوا لها الأموال، فأرسلتني دسيساً إلى محمد صلى الله عليه وسلم بعد أن رجع في عِيرها من الشام - والعِير بكسر العين هي الإبل التي تحمل الميرة - فقلت: يا محمد ما يمنعك أن تتزوج؟ فقال: ما بيدي ما أتزوج به! قلت: فإن كُفِيْتَ ذلك، وَدُعِيْتَ إلى المال والجمال والشرف والكفاءة، ألا تجيب؟ قال: فمن هي؟ قلت: خديجة، قال: وكيف لي بذلك؟ فذهبتُ فأخبرتُها فأرسلتْ إليه أَنِ ائْتِ الساعة كذا. انتهى. قال شيخ الإسلام في شرح البهجة في زوجاته صلى الله عليه وسلم: أفضلهم خديجة وعائشة. وفي أفضلهما خلاف، صَحَّحَ ابْنُ العماد تفضيلَ خديجة لما صح أنه عليه الصلاة والسلام قال لعائشة حين قالت له: قد رزقك الله خيراً من خديجة، قال: لا والله ما رزقني الله خيراً منها .. آمنت بي حين كذَّبني الناس، وأعطتني مالها حين حرمني الناس، وَرُزِقْتُ منها الولدَ وَحُرِمْتُهُ من غيرها. وسُئل الإمام أبو بكر ابن الإمام المجتهد داود: أخديجة أفضل أم عائشة؟ فقال: خديجة، أقرأها النبي صلى الله عليه وسلم السلام عن جبريل من قِبَلِ"], [130, "صفحة 130\rنفسه، وخديجة أقرأها جبريل السلام من ربها على لسان محمد صلى الله عليه وسلم، فهي أفضلهن، فقيل له: فمن أفضل؟ أخديجة أم فاطمة؟ فقال: إن رسول الله صلى الله عليه وسلم قال: فاطمة بَضعة مني، فلا أساوي ببضعة رسول الله صلى الله عليه وسلم أحداً. قال السهيلي: وهذا أتقن وأحسن. انتهى.\r\rوكان سيدنا مالك بن سنان يقول: لا أُفَضِّلُ على بَضعة رسول الله صلى الله عليه وسلم أحداً، وهو الذي يجب اعتقاده ونلقى الله عليه إن شاء الله تعالى، وروي أن عائشة قالت لفاطمة: يا فاطمة أنا خير من أمك، لأن رسول الله صلى الله عليه وسلم تزوَّج أمك وهي ثيِّب، وتزوَّجني وأنا بكر، فحصل لفاطمة شيء، فأتت إلى النبي صلى الله عليه وسلم وأخبرته بما قالت عائشة، فقال لها رسول الله صلى الله عليه وسلم: قولي لها: صدقتِ، إن رسول الله تزوج أمي وهي ثيِّب، وتزوَّجك وأنت بكر، ولكن رسول الله حين تزوج أمي هو بكر، وحين تزوجك هو ثيب! فبكارة رسول الله صلى الله عليه وسلم خير من بكارتك. فقالت فاطمة لعائشة ذلك، فقالت عائشة: اشكري يا فاطمة من علَّمك هذا الجواب. قال الشرقاوي: وأفضل نساء العالَم مريم بنت عمران، ثم فاطمة بنت رسول الله صلى الله عليه وسلم، ثم خديجة، ثم عائشة. قال البرهان الحلبي: وسكتوا عن بقية الزوجات أيتهن أفضل، والذي يظهر أن أفضلهن بعد خديجة وعائشة هي زينب بنت جحش.\r\rقوله: (فخذ بهم وليجة) أي خذ واكسب بمعرفة أولاده صلى الله عليه وسلم محبة"], [131, "صفحة 131\rمستمرة إلى الموت، فمعنى الوليجة هي البطانة أي المحبة في الظاهر والباطن.\r\rقوله: (وأربع) معطوف على قوله ثلاثة، وقوله: (من الإناث) متعلق بمحذوف صفة له، وقوله: (تُذْكَرُ) تكملة للبيت لأجل القافية. قوله: (رضوان ربي) مبتدأ ومضاف، وقوله: (للجميع) متعلق بمحذوف خبره، فاللام بمعنى عن أو على، قال في المصباح: ورضيت عنه ورضيت عليه لغة أهل الحجاز، والرضوان بكسر الراء وضمها لغة قيس وتميم .. بمعنى الرضا وهو خلاف السخط. انتهى. والمقصود بذلك طلب الرضوان من الله عن جميع الأولاد السبعة. وقوله: (يُذكر) تكملة للبيت فلا معنى له. قوله: (فاطمة) بدل من أربع، بدل بعض من كل، أو خبر مبتدأ محذوف تقديره وهي فاطمة. وقوله: (الزهراء) صفة أو بدل أو عطف بيان، ومعناه الأبيض الوجه، وقوله: (بعلها علي) مبتدأ وخبر، وقوله: (وابناهما السبطان) مبتدأ وخبر، ومعناه أن ابني فاطمة وعلي وهما الحسن والحسين سبطان لرسول الله صلى الله عليه وسلم، والسبط هو ولد الولد. قوله: (فضلهم جلي) مبتدأ وخبر، ومعناه أن فضل هؤلاء الأربعة الذين هم علي وفاطمة وحسن وحسين ظاهر عند كل واحد من المسلمين.\r\rرُوِيَ: إنما سميت فاطمة لأن الله تعالى فطمها وذريتها عن النار، وتسمى الزهراء، لأنها لم تَحِضْ طول عمرها، وتسمى"], [132, "صفحة 132\rالبتول من البتل، وهو القطع لانقطاعها عن الدنيا، وقيل لانقطاعها عن نساء زمانها حسباً وديناً. وكانت أحب أهله صلى الله عليه وسلم إليه، وكان إذا أراد سفراً يكون آخر عهده بها، وإذا قدم كان أول ما يدخل عليها. وروي أنه عليه الصلاة والسلام قال في حق علي: (أعطيتُ خير النساء لخير الرجال)، وقال أيضاً: (من أراد أن ينظر إلى آدم عليه السلام وإلى يوسف وحسنه، وإلى موسى وصلاته، وإلى عيسى وزهده، وإلى محمد وخَلْقه - أي صورته -، فلينظر إلى علي). وأخرج الطبراني حديث: (إن الله جعل ذرية كل نبي في صلبه، وجعل ذريتي في صلب علي بن أبي طالب).\r\rتوفي كرم الله وجهه عن ثلاث وستين سنة، ضربه ابْنُ مُلْجَمٍ - بفتح الجيم وكسرها - في جبهته ليلة الجمعة سابع عشر رمضان سنة أربعين، وهو خارج إلى صلاة الصبح، ومات ليلة الأحد، وَاخْتُلِفَ في موضع قبره لأنه أخفي خوفاً من أن تنبشه الخوارج، وفي رواية أنهم حملوه ليدفنوه مع رسول الله صلى الله عليه وسلم، فندّ الجمل الذي حمله فلم يُدْرَ أين ذهب. [2] وروي عن عبد الله بن الزبير قال: أَشْبَهُ أهل النبي صلى الله عليه وسلم به وأحبهم إليه الحَسَنُ، رأيته يجيء وهو ساجد، فيركب ركبته أو قال ظهره، فما كان يُنْزِلُهُ حتى يكون هو الذي يَنزل - أي بنفسه - ولقد رأيته"], [133, "صفحة 133\rوهو صلى الله عليه وسلم راكع يفرج له بين رجليه حتى يخرج من الجانب الآخر.\r\rهذا في حق سيدنا الحسن رضي الله عنه، وأما في حق سيدنا الحسين، فروي عن جابر بن عبد الله قال: سمعت رسول الله صلى الله عليه وسلم يقول: (من سرَّه أن ينظر إلى رجل من أهل الجنة - وفي لفظ آخر: إلى سيد شباب أهل الجنة - فلينظر إلى الحسين بن علي). ورُوي أن الحسن كان أشبه الناس برسول الله صلى الله عليه وسلم من رأسه إلى صدره، والحسين أشبه به من صدره إلى رجليه. وقال صلى الله عليه وسلم: (ابناي الحسن والحسين سيدا شباب أهل الجنة، وأبوهما خير منهما). وفي هذا الحديث حجة لما عليه أهل السنة أن الأئمة الأربعة أفضلُ من أهل البيت، نعم، ما فيهم من البضعة الكريمة لا يماثله ولا يقابله أحد بسبب أعماله الصالحة. ذكره سليمان الجمل.\r\rفرع\rبقي مناقب الأئمة الثلاثة وهم أبو بكر وعمر وعثمان. قال رسول الله صلى الله عليه وسلم في حق سيدنا أبي بكر: (من أراد أن ينظر إلى صدر الخليل إبراهيم، فلينظر إلى صدر أبي بكر الصديق)، وقال أيضاً: (إذا كان يومُ القيامة يجيء رضوان خازن الجنان بمفاتيح الجنة، ومفاتيح النار، ويقول يا أبا بكر، الرب جل جلاله يقرئك السلام، ويقول لك: هذه مفاتيح الجنة ومفاتيح النار ابعث من شئت إلى الجنة وابعث من شئت إلى النار). وقال أيضاً: (إن أهل السماوات"], [134, "صفحة 134\rمن الكروبيين والروحانيين والملأ الأعلى لَينظرون في كل يوم إلى أبي بكر الصديق) رضي الله عنه، وجعلنا من أهل شفاعته.\r\rوقال رسول الله صلى الله عليه وسلم في حق سيدنا عمر بن الخطاب رضي الله تعالى عنه: (عمر سراج أهل الجنة)، وقال أيضاً: (نعم الرجل عمر، يفتقد الأرامل والأيتام، ويحمل لهم الطعام وهم نيام)، ومعنى يفتقد الأرامل والأيتام أي يطلبهم عند غيبتهم وقال أيضاً: (أعز الله الإسلام بعمر بن الخطاب).\r\rوقال رسول الله صلى الله عليه وسلم في حق سيدنا عثمان بن عفان: (نعم الرجل عثمان، صهري وزوّجتُه بنتي .. وقد جمع الله به نوري). وقال أيضاً: (عثمان جمع الله به نوري، وهو سعيد في حياته، وشهيد في مماته). وقال أيضاً: (عثمان تستحي منه الملائكة).\r\rقوله: (زكت رضية) تكملة للبيت فمعنى زكت أي صلحت، ومعنى رضية أي مَرْضِيَّة فلا معنى له.\r____________\r[1] أخرج الحديث الخطيب من حديث محمد بن معمر عن حميد بن حماد، وحميد بن حماد أورده الذهبي في الضعفاء، وقال أحمد: ابن عدي يحدث عن الثقات بالمناكير. اهـ. ورواه الطبراني في الأوسط من حديث ابن عباس، وأورد ابن الجوزي هذا الحديث من هذا الطريق وحكم بوضعه وأقره عليه الذهبي والسيوطي في مختصر الموضوعات. وقال بعضهم: حاشاه أن يقول ذلك كراهة للبنات؛ بل خرج مخرج التعزية للنفس. اهـ مناوي على الجامع الصغير باختصار. وروي أن ابن عباس - رضي الله عنهما - ماتت له ابنة فجاءه المهاجرون يعزونه، فقال: الحمد لله، عورة سترها الله، وأجر ساقه الله، ومؤونة كفاها الله.\r[2] هنا تم حذف فقرة من الأصل."], [135, "صفحة 135\rعن تِسْعِ نسوةٍ وفاةُ المصطفى…خُيِّرْنَ فاخترنَ النبيَّ المُقْتَفَى\r\rقوله: (عن تسع) متعلقٌ بمحذوف خبر مقدم، وقوله: (وفاة) مبتدأ مؤخر، وقوله: (المصطفى) من الصفوة بتثليث الصاد وهي الخلوص أي المختار. قال صلى الله عليه وسلم: (إن الله اصطفى كنانة من ولد إسماعيل، واصطفى قريشاً من كنانة، واصطفى من قريش بني هاشم، واصطفاني من بني هاشم .. فأنا خيار من خيار). قوله: (خُيِّرْنَ) بالبناء للمفعول أي أُمرن بالخيار بين زينة الدنيا والجنة. قوله: (اخترن النبي المقتفى) أي لمّا أمرهن صلى الله عليه وسلم بالخيار بين ذلك بأمر من الله، لأنهن طلبن منه صلى الله عليه وسلم ما ليس عنده من زينة الدنيا، فاخترن النبي المقتفى، أي فاختار هؤلاء الأزواجُ التسع الآخرةَ على الدنيا باتباع النبي المتبع، فمعنى المقتفى المتبع، قال الله تعالى: {يَا أَيُّهَا النَّبِيُّ قُل لِّأَزْوَاجِكَ إِن كُنتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ وَأُسَرِّحْكُنَّ سَرَاحًا جَمِيلًا. وَإِن كُنتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنكُنَّ أَجْرًا عَظِيمًا}. ومعنى هذا البيت أن النبي صلى الله عليه وسلم فارق الدنيا وعنده يومئذ تسع زوجات، وهؤلاء التسع هن اللواتي خيرن بين ذلك، وهذا من خصائصه صلى الله عليه وسلم، أي أن التخييرَ على النساء في نفسه صلى الله عليه وسلم بين مفارقته لهن طلباً للدنيا، والإقامة معه طلباً للآخرة، واجبٌ عليه"], [136, "صفحة 136\rصلى الله عليه وسلم، والتزوج أكثر من أربع إلى غير نهاية جائز له صلى الله عليه وسلم، لأنه مأمون من الجور، وكانت الزيادة على تسع حُرِّمَتْ بقوله تعالى: {لا يَحِلُّ لَكَ النِّسَاءُ مِنْ بَعْدُ}، ثم نُسخ ذلك بقوله تعالى: {إِنَّا أَحْلَلْنَا لَكَ أَزْوَاجَكَ اللَّاتِي آتَيْتَ أُجُورَهُنَّ} الآية، لكن لم يقع منه تزوج بعد النهي عن الزيادة عليها. ومن الخصائص أيضاً عقده صلى الله عليه وسلم بلا ولي وبلا شهود، وبلا مهر ابتداءً وانتهاءً، وجملة ما خص به صلى الله عليه وسلم أربعة أنواع:\r\r(أحدها): المباحات أي التخفيفات، منها: إباحة الوصال، وهو أن يوصل صوم النهار بإمساك الليل مع صوم الذي بعده من غير أن يَطْعم شيئاً، ويقضي بعلمه، ويحكم ويشهد لنفسه وفرعه وعلى عدوه، وتجوز له الشهادة بما ادَّعاه، وله أخذ طعام غيره إن احتاج إليه، ويجب إعطاؤه له، ولا ينتقض وُضوؤه بالنوم، وأكثر هذه المباحات لم يفعله.\r\r(الثاني): المحرمات منها: تحريم صدقة التطوع عليه، وتحريم خَط، وشِعر، ومد العين إلى متاع الناس، وخائنة الأعين، وهي الإيماء بما يظهر خلافه من مباح دون الخديعة في الحرب، والمن أي الإعطاء ليستكثر.\r\r(الثالث): الواجبات منها: وجوب الضحى والوتر والأضحية والسواك لكل صلاة، والمشاورة وتغيير منكر"], [137, "صفحة 137\rرآه، وإن خاف، وإن علم أن فاعله يزيد فيه عناداً على المعتمد، ومصابرة العدو وإن كثر، وقضاء دين مسلم مات معسراً، وزاد في العباب وجوب راتبة الصبح.\r\r(الرابع): الفضائل والإكرام، منها: أن النكاح في حقه عبادة مطلقاً بخلافه في حقنا فإنه مباح، والعبادة عارضة له، وتفضيل نسائه على سائر النساء، وثوابهن وعقابهن مضاعف، وهن أمهات المؤمنين إكراماً فقط، كالإكرام في الأبوة للرجال والنساء، وتحريم سؤالهن إلا من وراء حجاب. ذكر ذلك الشرقاوي ثم قال: فهو صلى الله عليه وسلم خاتم النبيين، وسيد ولد آدم أجمعين، وأول من تنشق الأرض عنه يوم البعث، وأول من يقرع باب الجنة، وأول شافع، وأول مشفَّع (بفتح الفاء أي مقبول الشفاعة)، وأمته خير الأمم، وشريعته مؤبدة ناسخة لغيرها، ومعجزاته باقية، وهي القرآن، وجُعلت له الأرض مسجداً وترابها طهوراً، أي تصح الصلاة في سائر بقاع الأرض، ويجوز التيمم بالتراب في شريعته خاصة، ولم يورث، وتركته صدقة على المسلمين، وأُرسل إلى الإنس والجن والملائكة، وهو أكثر الأنبياء أتباعاً، وكان لا ينام قلبُه، ويرى مَنْ خَلْفَهُ. وتطوعه قاعداً كتطوعه قائماً، ولا تبطل صلاة من خاطبه بالسلام، وتجب إجابته في الصلاة، ولا تبطل بها ولو فعلاً كثيراً، ويحرم رفع الصوت فوق صوته، ونداؤه من وراء الحجرات، ونداؤه"], [138, "صفحة 138\rباسمه نحو: يا أحمد ويا محمد ونحو ذلك، بل يقال: يا رسول الله ونحوه، والتكني بكنيته مطلقاً على المذهب وهي أبو القاسم، أي فلا يجوز ذلك عند الشافعي سواءً كان اسمه محمداً أو لا، وسواءً قبل مفارقته صلى الله عليه وسلم للدنيا أو بعدها، وعند الأئمة الثلاثة يجوز ذلك بعد مفارقته للدنيا. وتحل له الهدية مطلقاً، ولا يجوز الجنون على الأنبياء بخلاف الإغماء، ولا الاحتلام لأنه من تَلاعُب الشيطان، ورؤيته في النوم حق، ولا يُعمل بها في الأحكام لعدم ضبط النائم، ولا تأكل الأرضُ لحومَ الأنبياء، والكذب عليه عمداً كبيرة، وَنَبَعَ الماءُ الطهور من بين أصابعه، وصلى بالملائكة ليلة الإسراء، ولا يجوز عليه الخطأ، ويبلُغُه سلامُ الناس بعد موته، ويشهد لجميع الأنبياء بأداء رسالتهم يوم القيامة. وكان إذا مشى في الشمس والقمر لا يظهر له ظل، ولا يقع عليه الذباب، ولا يمتص دمه البعوض، وكل موضع صلى فيه وضبط موقفه امتنع الاجتهاد فيه يمنة ويسرة. ووجوب الصلاة عليه في التشهد الأخير، وعرض عليه جميع الخلق من آدم إلى من بعده. وكان لا يتثاءب، ولا يظهر منه الغائط، بل تبتلعه الأرض، ومن كان في قلبه حرج في حكمه عليه يكفر به، ولم يصلَّ عليه جماعةً بل صلى الناس عليه أفذاذاً صلى الله عليه وسلم، وزاده فضلاً وشرفاً لديه."], [139, "صفحة 139\rعائشةٌ وحَفصةٌ وسَودةْ…صَفيةٌ مَيمونةٌ ورَملةْ\r\rهندٌ وزينبٌ كذا جُوَيْرِيَةْ…للمؤمنينَ أمهاتٌ مُرْضِيَةْ\r\rأي الأولى من الأزواج التسع اللاتي توفي رسول الله صلى الله عليه وسلم عنهن: عائشة بنت أبي بكر الصديق رضي الله تعالى عنهما، فتزوجها في شوال سنة اثنتي عشرة من النبوة على قول، وكانت بنت سبع على قول، وبنى بها في شوال على رأس ثمانية أشهر من الهجرة على قول، وهي بنت تسع، وَقُبِضَ عنها وهي بنت ثماني عشرة سنة، ولم يتزوج بكراً غيرها، وكانت أحب نسائه إليه. توفيت سنة ست أو سبع أو ثمان وخمسين، وصلى عليها أبو هريرة، ودُفنت بالبقيع ليلاً بوصية منها في ذلك المكان والوقت، وقد قاربتْ سبعاً وستين سنة، ورأت جبريلَ يتحدث مع النبي صلى الله عليه وسلم في صورة دحية الكلبي، وقال: (هذا جبريل يسلم عليك).\r\r(والثانية): حفصة بنت عمر الفاروق ابن الخطاب، فتزوجها في شعبان على رأس ثلاثين شهراً من الهجرة على الأشهر، وقد كان صلى الله عليه وسلم طلَّقها لأنها أفشت أمراً أَسَرَّهُ إليها لعائشة، وكان بينهما مصادقة ومصافاة، فنزل عليه جبريل عليه السلام وقال له: راجع حفصة فإنها صوَّامة قوَّامة، وإنها زوجتك في الجنة."], [140, "صفحة 140\r(والثالثة): سودة بنت زمعة، فتزوجها في السنة العاشرة من النبوة، كانت تحب ابن عمها السكران بن عمر، وأسلم معها قديماً وهاجر إلى الحبشة الهجرة الثانية، فلما مات تزوَّجها صلى الله عليه وسلم، ولما كبرت أي أسنَّت عنده صلى الله عليه وسلم أراد طلاقها فقالت: لا تطلقني وأنت في حل من شأني، وإنما أريد أن أُحشر في نسائك، وإني قد وهبت يومي لعائشة، فأمسكها رسول الله صلى الله عليه وسلم حتى توفي عنها، وقيل فيها نزل قوله تعالى: {وَإِنِ امْرَأَةٌ خَافَتْ مِن بَعْلِهَا نُشُوزًا أَوْ إِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَا أَن يُصْلِحَا بَيْنَهُمَا صُلْحًا}. وماتت في آخر خلافة عمر على المشهور.\r\r(والرابعة): صفية بنت حيي بن أخطب، من سبط هارون بن عمران عليهما السلام، كان أبوها سيد بني النضير، فقتل مع بني قريظة. اصطفاها صلى الله عليه وسلم لنفسه من سبي خيبر، فأعتقها وتزوجها وجعل عتقها صداقها، وكانت جميلة لم تبلغ سبع عشرة سنة، وروي أن رسول الله صلى الله عليه وسلم دخل على صفية وهي تبكي فقال: (ما يبكيك؟)، فقالت: بلغني أن عائشة وحفصة تقولان: نحن خير من صفية، نحن بنات عم النبي وأزواجه، قال: ألا قلتِ لهن: كيف تكن خيراً مني وأبي هارون، وعمي موسى، وزوجي محمد صلى الله عليه وسلم؟). ماتت في رمضان سنة خمسين أو اثنتين وخمسين في زمن معاوية، ودفنت بالبقيع."], [141, "صفحة 141\r(والخامسة): ميمونة بنت الحارث، تزوجها في شوال سنة سبع، وتزوجها صلى الله عليه وسلم وهو مُحْرِمٌ بعمرة القضاء كما عليه الجمهور، وكان اسمها بَرَّة فسماها صلى الله عليه وسلم ميمونة. وتوفيت في سرْف وهو (بسكون الراء وفتحها) الموضع الذي دخل عليها فيه رسول الله صلى الله عليه وسلم، وهو قريب من التنعيم، ودفنت فيه وماتت سنة إحدى وخمسين، وقيل ست وستين، وقد بلغت ثمانين سنة، وصلى عليها عبد الله بن عباس رضي الله عنهما، وهي آخر من تزوّج بها صلى الله عليه وسلم، وآخر من توفي من أزواجه.\r\r(والسادسة): أم حبيبة رملة بنت أبي سفيان صخر بن حرب، هاجرت مع زوجها عبد الله بن جحش إلى الحبشة الهجرة الثانية، فولدت له حبيبة، وتنصَّر هو وثبتت هي على الإسلام، فبعث النبي صلى الله عليه وسلم عمرو بن أمية الضمري إلى النجاشي، فزوَّجه إياها وأمهرها عنه أربعمائة دينار، وتولى عقد نكاحها خالد بن سعيد بن العاص، لكونه ابن عمها. ماتت سنة أربع وأربعين، وقيل تولى تزويجها عثمان بن عفان وهي ابنة عمه. وتوفيت سنة أربعين.\r\r(السابعة): أم سلمة هند بنت أبي أمية بن المغيرة، تزوَّجها في آخر شوال سنة أربع، ولما أَرسل إليها صلى الله عليه وسلم يخطبها قالت: مرحباً برسول الله ثلاثاً، ألا إن فِيَّ خلالاً ثلاثاً: أنا امرأة شديدة الغَيرة، وأنا امرأة مصبية (أي ذات صبيان)، وأنا امرأة ليس هنا أحد من أوليائي. فأتاها رسول الله صلى الله عليه وسلم"], [142, "صفحة 142\rفقال لها: (أَمَّا ما ذكرت من غَيرتك فإني أرجو الله أن يُذْهِبَهَا، وأما ما ذكرت من صبيتك فإن الله سيكفيهم، وأما ما ذكرت من أوليائك فليس أحد من أوليائك يكرهني)، فقالت لابنها زوِّج رسول الله صلى الله عليه وسلم، فزوَّجه بها، وَاسْتُدِلَّ به على أن الابن يلي عقد أمه، وهو بخلاف مذهبنا معشر الشافعية، ويشهد لمالك، وَدُفِعَ بأنه إنما زوَّجها بالعصوبة لأنه ابن عمها. وروي أن رسول الله صلى الله عليه وسلم أعطاها القارورة التي فيها تربة مقتل الحسين، وتُرِكت عندها، وذلك لما جاءه صلى الله عليه وسلم جبريل وأخبره أن الحسين مقتول في هذا التراب، وأراه من تربة الأرض التي يقتل فيها، وشم صلى الله عليه وسلم ذلك التراب فقال: ويح كربلاء! وقال لها: إذا صار هذا التراب دَماً فقد قُتِلَ ابني الحسين، فانتبهت وقالت لجاريتها: اذهبي إلى السوق فانظري ما الخبر؟ فرجعت إليها الجارية وقالت: قتل الحسين بن علي رضي الله عنه. وتوفيت هند في خلافة يزيد بن معاوية سنة ستين على الصحيح، وقد بلغت أربعاً وثمانين سنة، وصلى عليها أبو هريرة، وقيل سعيد بن زيد، ودفنت بالبقيع.\r\r(الثامنة): زينب بنت جحش بنت عمته صلى الله عليه وسلم أميمة، وكان اسمها بَرَّة، فسماها رسول الله صلى الله عليه وسلم زينب، وكانت قبله عند مولاه زيد بن حارثة، فطلقها، فلما حلت زوجه الله إياها سنة أربع على أحد الأقوال، وهي يومئذ بنت خمس"], [143, "صفحة 143\rوثلاثين سنة بقوله تعالى: {فَلَمَّا قَضَى زَيْدٌ مِنْهَا وَطَرًا زَوَّجْنَاكَهَا}، قوله: {وَطَرًا} أي حاجة، والمراد به هنا الطلاق، أي فلما طلقها وانقضت عدتها زوجناكها. وكانت تفتخر على نسائه صلى الله عليه وسلم، تقول: إن آباءكن أنكحوكن، وإن الله تعالى أنكحني إياه من فوق سبع سماوات. وفيها نزل الحجاب، وغضب عليها رسول الله صلى الله عليه وسلم لقولها في صفية بنت حيي: تلك اليهودية، فهجرها في ذي الحجة والمحرم وبعض صفر. وهي أول نسائه وفاة ولحوقاً به صلى الله عليه وسلم، ففي حديث مسلم عن عائشة: أن بعض أزواج النبي صلى الله عليه وسلم قلن له: أيُّنا أسرع بك لحوقاً؟ قال: (أسرعكن لحوقاً بي أطولكن يداً)، فكان أسرعهن به لحوقاً زينب بنت جحش، قيل أن طول يدها بسبب أنها كانت تعمل وتتصدق كثيراً. توفيت سنة عشرين وفيها فُتحت مصر، وقيل إحدى وعشرين وقد بلغت ثلاثاً وخمسين سنة، ودُفنت بالبقيع، وصلى عليها عمر بن الخطاب، وكانت عائشة تقول: هي التي تساويني في المنزلة عنده صلى الله عليه وسلم، وما رأيت امرأةً قط خيراً في الدين من زينب، وأتقى لله وأصدق حديثاً وأوصل للرحم وأعظم صدقة.\r\rوأما زينب بنت خزيمة فتزوجها سنة ثلاث، وكانت تُدعى في الجاهلية أم المساكين لإطعامها إياهم، ولم تلبث عنده إلا شهرين أو ثلاثة، ثم ماتت وصلى عليها رسول الله صلى الله عليه وسلم ودفنها بالبقيع. وقد بلغت نحو ثلاثين سنة، ولم يمت من أزواجه صلى الله عليه وسلم في"], [144, "صفحة 144\rحياته إلا هي وخديجة وريحانة على القول بأنها زوجته.\r\r(والتاسعة): جويْرية بنت الحارث، وقعت يوم المريسيع في سهم ثابت بن قيس بن شماس، فكاتبها على تسع أواقٍ من الذهب فأدَّاها عنها وتزوَّجها. وكانت اسمها بَرَّة فسماها صلى الله عليه وسلم جويرية، وكانت ذات جمال. قالت عائشة: فلم نعلم امرأة أكثر بركة على قومها منها، وتوفيت بالمدينة في ربيع الأول سنة ست وخمسين، وقد بلغت سبعين سنة، وصلى عليها مروان بن الحكم.\r\rتنبيه\rقوله: (سودة ورملة) يُقرآن بغير تنوين، وقوله: (جويريةْ) يقرأ بالسكون، وأما بقية الأسماء فتُقرأ بالتنوين للوزن، وقوله: (للمؤمنين) متعلق بمحذوف صفة لأمهات، وقوله: (أمهات) خبر لمبتدأ محذوف، والمعنى: وكلهن مثل أمهات المؤمنين في الاحترام والإجلال، وحرمة نكاحهن على جميع الأمم حتى على بقية الأنبياء والمرسلين عليهم السلام، لأنهم من أمته صلى الله عليه وسلم. قوله: (مرضية) بتخفيف الياء للوزن، وهو خبر لمبتدأ محذوف أيضاً، أي وكلهن مرضية لله ولرسوله لطاعتهن لهما.\r\rخاتمة\rقال الشرقاوي: وقد مات صلى الله عليه وسلم عن تسع، وَعَقَدَ على خمسَ عشرةَ، واجتمع في عصمته إحدى عشرة، وطلق اثنتين، والتسع التي توفي عنهن: سودة بنت زمعة، وعائشة، وحفصة، وأم سلمة، وزينب بنت"], [145, "صفحة 145\rجحش، وأم حبيبة، وجويرية، وصفية، وميمونة. هذا ترتيب تزوجه إياهن. انتهى. قال حسن العدوي الحمزاوي في مشارق الأنوار: قال في المواهب: والمتفق عليه أن أزواجه اللاتي دخل بهن ولم يطلقهن إحدى عشرة امرأة، ست من قريش وهن: خديجة بنت خويلد، وعائشة بنت أبي بكر، وحفصة بنت عمر، وأم حبيبة بنت أبي سفيان، وأم سلمة بنت أبي أمية، وسودة بنت زمعة، وأربع عربيات (أي من حلفاء قريش، وإلا فالكل عربيات): زينب بنت جحش، وميمونة بنت الحارث، وزينب بنت خزيمة، وجويرية بنت الحارث، وواحدة إسرائيلية وهي صفية بنت حيي النضيرية. انتهى. ثم قال الحمزاوي: ولم يذكر ريحانة من الزوجات، وذكرها من السراري، وأما مع عدها زوجة فهن اثنتا عشرة امرأة. وتوفي عن تسع منهن، وأما غيرهن ممن وهبت نفسها وخطبها ولم يعقد عليها أو عقد ولم يدخل بها لموت أو طلاق فنحو ثلاثين امرأة، ولم يتزوج صلى الله عليه وسلم إلا بوحي، قال صلى الله عليه وسلم: (ما تزوجت أحداً من نسائي ولا زوجت شيئاً من بناتي إلا بوحي جاءني به جبريل من ربي جل وعز) انتهى.\r\rثم اعلم أن نكاحه صلى الله عليه وسلم لا بد فيه من الصيغة ولو بلفظ الهبة، فيقول: زوَّجت نفسي وقبلت، هذا في غير نكاح الواهبة نفسها له صلى الله عليه وسلم، أما هي فلا يحتاج لها كما قاله الشرقاوي."], [146, "صفحة 146\rحمزةُ عَمُّهُ وعباسٌ كذا…عَمَّتُهُ صَفِيَّةٌ ذاتُ احْتِذَا\r\rاعلم أن أعمامه صلى الله عليه وسلم اثنا عشر:\r\r(الأول حمزة) وأمه هالة بنت أهيب.\r\r(والثاني العباس) وأمه قيلة بنت حبان.\r\rفأما حمزة فهو عمه صلى الله عليه وسلم وأخوه من الرضاعة، أرضعتهما ثويبة، وكان أسن منه صلى الله عليه وسلم بأربع سنين، وقيل بسنتين، وكان أسدَ الله وأسدَ رسوله، شهد بدراً وأحداً وبها استشهد أي وبأحد قتل شهيداً على يد وحشي، ووجدوا فيه يومئذ بضعاً وثمانين جرحاً ما بين ضربة سيف وطعنة رمح ورجعة سهم، ورُوي أنه سيد الشهداء، وفي رواية: (خير الشهداء يوم القيامة حمزة)، أي الشهداء من هذه الأمة، فلا ينافي ما جاء أن سيد الشهداء يوم القيامة يحيى بن زكريا، وورد أيضاً: (خير أعمامي حمزة). وأما العباس فكان أصغر أعمامه وأسن منه عليه الصلاة والسلام بسنتين أو ثلاث، حضر بدراً مع المشركين مُكرَهاً، وأُسر مع من أسر، وفدى يومئذ نفسه، وأسلم قبل فتح خيبر، وكان يكتم إسلامه إلى يوم فتح مكة، وقيل أسلم قبل يوم بدر، وكان يكتم ذلك، وحضر يوم حنين، توفي سنة اثنتين وثلاثين وهو ابن ثمان وثمانين سنة، وصلى عليه عثمان.\r\r(والثالث أبو طالب): وأمه فاطمة بنت عمرو بن عابد، وهي أم عبد الله أبي رسول الله. والصحيح أنه مات كافراً"], [147, "صفحة 147\rواسمه عبد مناف، وأما أبو طالب فهو كنيته، وقيل: اسمه كنيته، قال البراوي: والذي نقله سيدي عبد الوهاب الشعراني عن السبكي أن عمه صلى الله عليه وسلم أبا طالب بعد أن توفي على الكفر أحياه الله تعالى وآمن به صلى الله عليه وسلم، قال شيخنا العلامة السجيني: وهذا هو اللائق بحبه صلى الله عليه وسلم، وهو الذي اعتقده وألقى اللهَ به، وأما إحياء الله تعالى لأبويه صلى الله عليه وسلم فللدخول في أمته فقط، وإن كانا من الناجين لأنهما من أهل الإسلام.\r\r(والرابع أبو لهب) وأمه لين بنت هاجر، وَكُنِّيَ بأبي لهب لأنه كان يتلهب حسناً، وقيل كني به لتلهب وجهه إشراقاً وحمرة، وكانت كنيته أبا عتبة، واسمه عبد العزى، وهو كافر بنص القرآن. وقد رآه في النوم بعد موته بسنة أخوه العباس فقال له: ما حالك؟ فقال: في النار، إلا أنه خُفِّفَ عني كل ليلة اثنين، وأمص من بين أصبعي هاتين ماء، وأشار برأس أصبعه إلى النقرة التي تحت إبهامه، وأن ذلك بإعتاقي ثويبة حين بشرتني بولادة النبي صلى الله عليه وسلم، وبأمري لها بإرضاعه.\r\r(والخامس الحارث) وأمه ثمرة بنت جندب، وهو أكبر أولاد عبد المطلب، وبه كان يكنى، فلم يدرك الإسلام، أي لم يدرك زمن بعثته صلى الله عليه وسلم.\r\r(والسادس الزبير) وأمه أم عبد الله، ولم يدرك الإسلام.\r\r(والسابع جَحْل) بتقديم الجيم المفتوحة على الحاء الساكنة المهملة، وقيل بتقديم الحاء المهملة المفتوحة على الجيم الساكنة، وأمه أم حمزة.\r\r(والثامن"], [148, "صفحة 148\rعبد الكعبة) وأمه أم عبد الله، ولم يدرك الإسلام، ولم يكن له نسل.\r\r(والتاسع قُثَم) بقاف مضمومة فمثلثة مفتوحة، وأمه أم الحارث، وهو مات صغيراً.\r\r(العاشر ضرار) وأمه أم العباس، مات في أيام أوحي إلى النبي صلى الله عليه وسلم ولم يُسلِم، وكان من فتيان قريش جمالاً وسخاءً.\r\r(والحادي عشر الغَيْداق) بفتح الغين المعجمة، وهو لقبه، واسمه مصعب وقيل نوفل، فكان أجود قريش وأكثرهم طعاماً ومالاً ولهذا لقب بالغيداق.\r\r(والثاني عشر المقوَم) بفتح الواو وكسرها، وأمه أم حمزة. ومن الناس من يعدهم عشرة، ويجعل عبد الكعبة والمقوم واحداً، وجحلاً والغيداق واحداً. والأشقاء لعبد الله والد النبي صلى الله عليه وسلم من هؤلاء ثلاثة: أبو طالب، والزبير، وعبد الكعبة.\r\rواعلم أن عماتِه سِتٌّ: إحداها صفية وهي أم الزبير بن العوام، وأمها هالة بنت أهيب أم حمزة، توفيت في المدينة في خلافة عمر بن الخطاب في سنة عشرين، ولها ثلاث وسبعون سنة، ودفنت بالبقيع، قيل لم يُسلم من عمات النبي صلى الله عليه وسلم غيرها، وقيل بل أسلمت أيضاً أروى وعاتكة. وثانيها أروى، وثالثها عاتكة، وفي إسلام هاتين خلاف كما علمت، ورابعها أم حكيم وهي البيضاء، وخامسها برة، وسادسها أميمة، ولا خلاف في عدم إسلام هذه الثلاث الأخيرة، وهذه الخمس الأخيرة شقيقات عبد الله والد النبي صلى الله عليه وسلم."], [149, "صفحة 149\rفائدة\rلسيدتنا آمنة ثلاثة إخوة وأختان، فأخواله صلى الله عليه وسلم وخالاته خمسة، وقد نظمها الشيخ محمد الفضالي بقوله:\r\rخَالُ النبيِّ أَسْوَدٌ عُمَيْرُ…عبدُ يغوثَ ليسَ فيهمْ ضَيْرُ\r\rفَريضةٌ فاختةٌ خالاتُ…وَالكُلُّ قبلَ بِعثةٍ قد ماتوا\r\rتنبيه\rقول الناظم: (حمزة عمه) مبتدأ وخبر، وقوله: (وعباس كذا) مبتدأ وخبر، أي وعباس مثل ذا أي مثل حمزة، وقوله: (عمته) خبر مقدم، وقوله: (صفية) مبتدأ مؤخر، ويجوز عكسه. قوله: (ذات احتذا) أي صاحبة اقتداء لله ولرسوله، أي لأن صفية مسلمة بلا خلاف، فذات بالرفع خبرٌ لمبتدأ محذوف والتقدير هي ذات احتذا، ويجوز النصب على الحال من صفية.\r\rثم اعلم أن لفظ ذات إن دلت على الوصفية نحو ذات جمال وذات حسن، كتبت بالتاء لأنها اسم، والاسم لا يلحقه الهاء الفارقة بين المذكر والمؤنث نحو زيد، فلا يلحقه الهاء ولو علماً لمؤنث، وجاز كتابته بالهاء لأن فيها معنى الصفات، فأشبه المشتقات نحو قائمة، كذا في المصباح."], [150, "صفحة 150\rوقبلَ هجرةِ النبيِّ الإسرا…من مكةٍ ليلاً لقدسٍ يُدْرَى\r\rوبعدَ إسراءٍ عُرُوْجٌ للسما…حتى رأى النبيُّ رَبّاً كَلَّمَا\r\rمِنْ غَيْرِ كيفٍ وانحصارٍ وافترضْ…عليهِ خمساً بعدَ خمسينَ فَرَضْ\r\rأي يجب على كل مكلف أن يعتقد أن الله تعالى أكرمَ نبيَّه صلى الله عليه وسلم بالإسراء والمعراج ليلاً في نحو أربع ساعات أو ثلاث أو أقل من ذلك، وفي رواية أنه رجع وخديجة لم تتحول عن جنبها، وفي رواية أنه رجع قبل أن يبرد محله صلى الله عليه وسلم، وكان ذلك ليلة الاثنين أو الجمعة أو السبت، أقوال. وكان من رمضان أو شوال أو رجب أو ذي الحجة أو ربيع الأول أو الثاني، أقوال. وكان بعد المبعث بخمس سنين أو بعشر أو إحدى عشرة أو اثنتي عشرة، أقوال. لكن المشهور: كان ذلك ليلة الاثنين ليلة السابع والعشرين من شهر رجب قبل الهجرة بسنة، وقد وقع الإسراء من مكة إلى بيت المقدس على البراق، وجبريل عن يمينه وميكائيل عن يساره، كما قال زين العابدين البرزنجي نظماً من بحر الطويل:\r\rوأَسرى به ربي من الحِجْرِ ليلةً…إلى المسجدِ الأقصى لرؤيةِ حَنَّانِ\r\rكما البدرِ في دَاجٍ من الليلِ قد سرى…وجبريلُ مَعْ مِيْكَالَ مَعْهُ يَسِيْرَانِ\r\rأي أسرى الله تعالى بسيدنا محمد صلى الله عليه وسلم من الحِجْرِ بكسر الحاء وسكون الجيم، أو من عند الحطيم في ليلة"], [151, "صفحة 151\rإلى المسجد الأقصى لرؤية ذات الله سبحانه وتعالى، كَسَيْرِ البدر في ليل مظلم، ومعنى الحنان: الحليم أو الذي يُقبل على من أعرض عنه، قوله: (كما البدر) جار ومجرور فما زائدة.\r\rاعلم أن البُراق دابة من ذوات الأربع، وهو لا ذكر ولا أنثى، دون البغل وفوق الحمار، إذا سار يضع رجليه عند منتهى بصره من الأرض، ثم يضع كل واحدة من رجليه المؤخرتين موضعهما أو أسبق منهما، وهذا أبلغ من الطيران، مداوماً على تحريك الأذنين لشدته وقوته، فإذا صعد على جبل طالت رجلاه، وإذا هبط إلى وهدة طالت يداه شيئاً فشيئاً، وهذه خصوصيةٌ لنبينا، فلم تقع لنبي ممن ركبه قبله، وسُمي براقاً من البرق لشدة سرعة سيره، أو من البريق بمعنى البياض الذي هو أفضل الألوان لما في خِلال بياضها بعضُ السواد، أرسله الله له صلى الله عليه وسلم من الجنة إجلالاً وتعظيماً، على أنه عادة الملوك إذا استدعى واحد منهم إنساناً من خواصه بعث إليه بمركوب سني، أي رفيع، مع أعز خواصه ليُحضرَه إليه، فبعد وصوله صلى الله عليه وسلم إلى المسجد الأقصى ترك البُراق مربوطاً بالصخرة التي كان يجلس عليها داود عليه السلام، وبعده ابنه سليمان، إلى عَوْدِهِ صلى الله عليه وسلم ليركبه في رجوعه إلى مكة بعد عروجه إلى السماء، هذا هو المشهور عند أهل أحواله صلى الله عليه وسلم، والمعاريج، والذي دلت عليه رواية البخاري أنه صلى الله عليه وسلم صعد مع البراق فوقع العروج من تلك"], [152, "صفحة 152\rالصخرة إلى حيثما شاء الله، بعد أن أذّن جبريل عليه السلام وأقام وصلى رسول الله صلى الله عليه وسلم ركعتين إماماً بجميع الأنبياء والمرسلين عليهم السلام في بيت المقدس. كما قال زين العابدين البرزنجي في النظم من الطويل:\r\rوَمُذْ حَلَّ في البيتِ المُقَدَّسِ جُمِّعَتْ…له الرُّسْلُ والأملاكُ مَعْ كُلِّ رَوْحَانِيْ\r\rوَقَدَّمَهُ جبريلُ صَلَّى بِجَمْعِهِمْ…إماماً وَهُمْ لِلْحَقِّ أكثرُ إذعانِ\r\rفتحصَّل أن الإسراء: سيرُه صلى الله عليه وسلم من المسجد الحرام إلى المسجد الأقصى، والعروج: صعوده صلى الله عليه وسلم إلى السماوات حتى جاوزها منتهياً إلى العرش، ولم يجاوزه وَهْماً بل بجسده صلى الله عليه وسلم وروحه معاً يقظةً لا مناماً، مرة واحدة، في ليلة واحدة، عند جمهور المحدثين والفقهاء والمتكلمين، وتواردت عليه ظواهر الأخبار الصحيحة، ولا ينبغي العدول عنه. وقيل وقع الإسراء والمعراج مرة مناماً ومرة يقظة، وقيل الإسراء في ليلة والمعراج في ليلة، وقيل الإسراء يقظة والمعراج مناماً، وقيل الخلاف في أنه يقظة أو مناماً خاص بالمعراج، وقيل أسري به مرتين يقظة، الأولى بلا معراج، والثانية به. والإسراء ثابت بالكتاب والسنة وإجماع المسلمين، فمن أنكره كفر، والمعراج ثابت بالأحاديث المشهورة، فمن أنكره لا يكفر بل يفسق، هكذا قاله البيجوري.\r\rوتلخيص قصة الإسراء والمعراج: أنه أتاه صلى الله عليه وسلم جبريل وميكائيل، وملك ثالث لم يعرف اسمه قيل هو إسماعيل صاحب سماء الدنيا، وقيل هو إسرافيل،"], [153, "صفحة 153\rبالحطيم أو شِعب أبي طالب أو بيته أو بيت أم هانئ، روايات، جُمع بينها بأنهم أتوه في بيت أم هانئ، وبيتُها عند شِعب أبي طالب، وأضيف إليه صلى الله عليه وسلم لأنه كان يسكنه فأخرجه المَلَكُ منه إلى المسجد، فأضجعه في الحطيم لبقاء أثر نعاس به، ثم أخذه وأخرجه إلى المسجد بعد تمام تيقظه، وبعد شق صدره وقلبه وغسلهما، فأركبه البراق وسار به حتى انتهى إلى بيت المقدس، ووقع له في الطريق عجائب كثيرة، وجاء في رواية أن جبريل ركب معه على البراق، ومر صلى الله عليه وسلم بالمدينة فأمره أن ينزل ويصلي هناك، وبمدين فأمره بذلك، وببيت لحم الذي ولد فيه عيسى فأمره بذلك، فلما وصل إلى بيت المقدس دخل المسجد من الباب الشرقي، ثم صلى هو وجبريل ركعتين تحية المسجد، فلما فرغا من صلاتهما لم يلبث صلى الله عليه وسلم إلا زمناً يسيراً حتى رأى المسجد قد اجتمع فيه أناس كثير من الأنبياء والمرسلين والملائكة والإنس والجن بأبدانهم وأرواحهم أحياءً وأمواتاً، أي أن الأنبياء والمرسلين قيل حضروا بأرواحهم وأجسادهم، وهو الراجح لأن الأنبياء أحياء في قبورهم يصومون ويصلون ويحجون على الراجح، وقال بعضهم ينكحون، ولا مانع من أن غير النبيين من صلحاء أتباعهم معهم، وفي هذا الاجتماع كرامة لنبينا محمد صلى الله عليه وسلم، فعرف النبي صلى الله عليه وسلم النبيين من بين قائم وراكع وساجد، ثم أذّن جبريل وأقيمت الصلاة،"], [154, "صفحة 154\rفلما سمعت الناس ذلك قاموا على أقدامهم صفوفاً ينتظرون من يؤمهم، فأخذ جبريل بيده عليه السلام فقدّمه في المحراب، فصلّى إماماً بهم ركعتين، فكان الصفوف من المرسلين ثلاثة صفوف، ومن الأنبياء أربعة، والملائكة والإنس والجن صفوفهم لا تنحصر، ووسَّع الله عليهم المسجد إكراماً له عليه السلام، ولم يكمل فيه صف واحد أصلاً لا في جمعة ولا في عيد ولا غيرهما لأنه أكبر المساجد. وقيل حضر الأنبياء والمرسلون بأرواحهم فقط، تشكلت في صور أجسادهم، وقيل رفع الله الحجب بينه صلى الله عليه وسلم وبينهم في قبورهم فصلى بهم في المسجد وهم في قبورهم، ولما فرغ من إمامتهم نصب له جبريل المعراج الذي يراه المحتضر عند خروج روحه تعرج عليه أرواح المؤمنين من بني آدم، فهو لجسد نبينا خاصة، ولأرواح المؤمنين عامة، وذلك للتشريف والتعظيم؛ إذ يمكنه الصعود بدونه، أعلاه إلى فوق السماوات، وأسفله على الصخرة لأنها أفضل ما في المسجد، وهي من الجنة، ولم تر الخلائق أحسن منه لو نظرت إليه، له مراق متعددة، يقال له المعراج، ومراقيه مختلفة لأنها مَرقاة بفتح الميم من ذهب، وفوقها مرقاة من فضة، وهكذا، وأحد جانبيه ياقوتة حمراء، والآخر زمردة خضراء، وهو من جنة الفردوس، ومرصع باللؤلؤ وغيره من معادن الجنة، وعن يمينه ملائكة، وعن يساره ملائكة، تعظيماً لمطلوب المَلِكِ الأعظم، وكل مرقاة منه"], [155, "صفحة 155\rمسيرة خمسمائة عام قدر ما بين السماء والأرض، فجملته عشر مراق وهي عشرة معاريج، ثم صعد فيه هو وجبريل حتى انتهيا إلى سماء الدنيا، فاستفتحا ففتح لهما، وهكذا إلى السابعة، ورأى في السماء الأولى آدم، ورأى النيل والفرات، ورأى في الثانية يحيى وعيسى، وحكمة كونهما في سماء واحدة مع أن كل واحدة من السماوات غير الثانية فيها نبي واحد، أن عيسى ينزل آخر الزمان فيبقى فيها يحيى، فلا تخلو سماء عن نبي، وفي الثالثة يوسف عليه السلام، وفي الرابعة إدريس، وفي الخامسة هارون، وفي السادسة موسى، وفي السابعة إبراهيم. وروي أن إدريس في الثانية، وهارون في الرابعة، وإبراهيم في السادسة، وموسى في السابعة، والرواية الأولى أصح، أو يجمع بين الروايتين بأنه رآهم في الصعود على كيفيات، وفي الهبوط على كيفيات أخر.\r\rوحكمة تخصيص هؤلاء باللقاء: الإشارة بكل إلى ما سيقع له صلى الله عليه وسلم مما يناسب ما وقع لكل منهم، كالإخراج من مكة فريداً والعود إليها بجنود كثيرة، كما وقع لآدم حيث أخرج من الجنة وحيداً وسيعود لها بجنود لا تحصى، وكمعاداة اليهود له أوائل الهجرة كما عادت عيسى وأرادت قتله وكما عادت يحيى وقتلوه، وكمعاداة أهله صلى الله عليه وسلم له ورجوعهم إلى محبته، كما رجع قوم هارون إلى محبته، وكمعالجة قومه صلى الله عليه وسلم كما عالج"], [156, "صفحة 156\rموسى قومه، وكتمكنه من مكة والكعبة كما وقع لإبراهيم.\r\rوبعد أن جاوز السماء السابعة رفعت له سدرة المنتهى، أي كشف له عنها، فرآها وهي على هذه الرواية في السماء السابعة، وروي أنها في السماء السادسة، ورأى النيل والفرات وسيحان وجيحان، ثم جاوزها إلى مستوىً بفتح الواو والتنوين، وهو المكان العالي المتسع، والمراد هنا محل سماع الأقلام، ولهذا سَمِعَ فيه صوت حركة الأقلام بأذنيه، ولا يعلم كيفيتها إلا الله تعالى، وكذا كيفية جريانها على المكتوب، فوقف جبريل ولم يسر معه، ثم زج به في النور، فخرق سبعين ألف حجاب من نور، مسيرة كل حجاب خمسمائة عام، ففي رواية أنه صلى الله عليه وسلم قال لجبريل لما تأخر في المقام: أيترك الخليل خليله؟ فقال له جبريل: هذا مقامي ولو جاوزته لأحرقني النور، فقال صلى الله عليه وسلم لجبريل: ألك حاجة عند ربك؟ فقال له: سَلِ الله أن يأذن لي أن أبسط جناحي على الصراط لأمتك حتى تجوز عليه، فلما وقف صلى الله عليه وسلم في مقام الخطاب، قال الله تعالى له: أين حاجة جبريل يا محمد؟ فقال: يا رب أنت أعلم، فقال: قد أجبته، ولمن أحبك وصحبك. انتهى.\r\rفبعد خرقه صلى الله عليه وسلم حجاب النور دُلِّيَ رفرف أخضر فارتقى به حتى وصل إلى مكان تحت العرش، ولم يجاوزه، فرأى صلى الله عليه وسلم ربه في هذا المقام رؤية تليق بجنابه الأقدس بعيني رأسه، بقوة أودعها فيهما وهما في محلهما،"], [157, "صفحة 157\rوهو الأصح عن ابن عباس، ورجَّحه أكابر العلماء، وقيل بعيني قلبه فقط، أي أن الله خلق في قلبه عينين كعيني الرأس فرأى بهما، ولم يحجبهما قفص البدن ولا الثياب، وليس المراد برؤية القلب على هذا القول الحضور والشهود مع ربه، واشتغال البال به دون غيره، لأن هذا الحال والمقام لا ينفك عنه صلى الله عليه وسلم بل قد يصل إليه بعض الأولياء.\r\rونفت الرؤيةَ بالعين عائشةُ وابن مسعود، حتى قالت عائشة: من زعم أن محمداً رأى ربه فقد كذب، وقالت لمن سألها عن ذلك: لقد قف شعري، معناه قد قام شعري من الفزع لكوني سمعت ما لا ينبغي أن يقال، وَرُجِّحَ القول بالوقف، وأسند لجماعة من المحققين. انتهى.\r\rفَخَرَّ النبي صلى الله عليه وسلم ساجداً سجود تحية وإكرام وشكر على ذلك، من غير احتياج لنية وسلام، وكلمه ربه في ذلك السجود، فأجابه فيه، فقال: لبيك يا رب، فقال له: سَلْ تُعْطَ، فقال: إنك اتخذت إبراهيم خليلاً، وكلمت موسى تكليماً، وأعطيت داود ملكاً عظيماً، وألنت له الحديد وسخَّرت له الجبال، وأعطيت سليمان مُلْكاً عظيماً، وسخَّرت له الإنس والجن والشياطين، وسخَّرت له الرياح وأعطيته ملكاً لا ينبغي لأحد من بعده، وعلَّمت عيسى التوراة والإنجيل، وجعلته يُبرئ الأكمه (وهو الذي خُلق أعمى ممسوح العين بلا شق لها) والأبرص ويحيي الموتى بإذنك، وأعذته وأمه من الشيطان الرجيم، فلم يكن"], [158, "صفحة 158\rللشيطان عليهما سبيل، فقال الله سبحانه وتعالى: قد اتخذتك حبيباً، وأرسلتك للناس كافة بشيراً (أي بالثواب) ونذيراً (أي بالعقاب)، وشرحتُ لك صدرك، ووضعت عنك وزرك، ورفعت لك ذكرك (أي لا أُذْكَرُ إلا ذُكِرْتَ معي)، وجعلتُ أمتك أمة وسطاً (أي خياراً عدولاً)، وجعلت أمتك هم الأولون (أي في البعث والحساب والمرور على الصراط ودخول الجنة)، وهم الآخرون (أي في الوجود)، لا تجوز لهم الخطبة حتى يشهدوا أنك عبدي ورسولي، وجعلت من أمتك أقواماً قلوبهم أناجيلهم (أي واعظهم وآمرهم وناهيهم، والمعنى قرآنهم محفوظ في قلوبهم)، وجعلتك أول النبيين خلقاً (أي بحسب التقدير)، وآخرهم بعثاً، وجعلتك أول من يقضي لهم يوم القيامة، وأعطيتك سبعاً من المثاني لم أعطها نبياً قبلك، وأعطيتك خواتيم سورة البقرة من كنز تحت العرش لم أعطها نبياً قبلك، وأعطيتك الكوثر، وأعطيتك ثمانية أسهم: الإسلام، والهجرة، والجهاد، والصدقة، والصلاة، وصوم رمضان، والأمر بالمعروف، والنهي عن المنكر، وجعلتك فاتحاً (أي لكل خير) وخاتماً للأنبياء، وأعطيتك لواء الحمد، فآدم ومن دونه تحت لوائك، وإني يوم خلقت السماوات والأرض قد فرضت عليك وعلى أمتك خمسين صلاة في كل يوم وليلة، فقم بها أنت وأمتك.\r\rثم سأل رسول الله صلى الله عليه وسلم التخفيف، بأمر موسى عليه السلام بذلك بالرجوع إلى"], [159, "صفحة 159\rمقام المناجاة بعد رجوعه صلى الله عليه وسلم إلى موسى، فلم يزل يرجع بين مكان موسى ومكان خطاب ربه يحط عنه خمساً خمساً حتى قال الله: يا محمد، قال: لبيك وسعديك، قال: هن خمس صلوات كل يوم وليلة (أي فِعْلاً)، كل صلاة فيهن بعشر، فتلك خمسون (أي مضاعفةً)، لا يُبدل القول لدي ولا يُنسخ كتابي، ومن هم بحسنة فلم يعملها كتبت له حسنة واحدة، فإن عملها كتبت له عشراً، ومن هم بسيئة فلم يعملها لم يكتب عليه شيء، فإن عملها كتبت له سيئة، فنزل صلى الله عليه وسلم ونزل إلى المكان الذي كان نائماً فيه، ولم يبرد مكانه من حرارة جنبه.\r\rتنبيه\rقوله: (وقبل هجرة النبي) متعلق بمحذوف خبر مقدم، والواو فيه داخلة على قوله (الإسرا)، وقوله: (الإسرا) بحذف الهمزة الممدودة للوزن، وهو مبتدأ مؤخر، وتقدير الكلام والإسراء ثابت وحاصل قبل الهجرة. قوله: (من مكة) بالصرف للوزن، قوله: (ليلاً) أي في بعض قليل من الليل. قال الزمخشري: ويشهد لذلك قراءة عبد الله وحذيفة: (من الليل) أي بعضه في قوله تعالى: {سُبْحانَ الَّذِي أَسْرى بِعَبْدِهِ لَيْلًا}، وإنما خص الليل بذلك دون النهار لأنه وقت تفريغ البال وقطع العلائق، وقيل: لأن الله تعالى لما محا نور الليل بالظلام، وجعل النهار مُبْصَراً فيه بالضوء كان الليل حزيناً، فكان الإسراء بمحمد صلى الله عليه وسلم في الليل للعدالة، ولذلك قيل: افتخر"], [160, "صفحة 160\rالنهار على الليل بالشمس، فقال: لا تفتخر، فإن كانت شمس الدنيا تشرق فيك فسيُعرجُ بشمس الوجود في الليل إلى السماء، وقيل لأنه صلى الله عليه وسلم سراج، والسراج إنما يوقد في الليل، وقيل لأنه سُمِّيَ بدراً في قوله تعالى: {طه}؛ فإن الطاء بتسعة والهاء بخمسة، وذلك أربعة عشر، فكأنه تعالى قال: يا بدر.\r\rقوله: (لقدس) فاللام بمعنى (إلى)، كقوله تعالى: {كُلٌّ يَجْرِي لِأَجَلٍ مُّسَمًّى}، والقدس بسكون الدال للوزن، قال في المصباح: القُدُسُ بضمتين، وإسكان الثاني تخفيفٌ هو الطهر، والأرض المقدسة المطهرة وبيت المقدس منها معروف، وقيل إن إبراهيم الخليل دعا لتلك الأرض بالقدس فسميت بذلك. قوله: (يدرى) تكملة للبيت. قوله: (حتى رأى النبي رباً) وكان صلى الله عليه وسلم يراه في كل مرة من مرات المراجعة، والرؤية بالعين في الدنيا يقظة مخصوصة به صلى الله عليه وسلم، ولم تقع لغيره، وإن جازت لغيره أيضاً عقلاً لأن الله تعالى موجود، وكل موجود يصح أن يُرَى، قال الشيباني في قصيدته من بحر الطويل:\r\rوَكُلُّ نبيٍّ خَصَّهُ بفضيلةٍ…وَخَصَّ برؤياهُ النبيَّ محمدَا\r\rفلا عينَ في الدنيا تراهُ لقولِهِ…سوى المصطفى إِذْ كَانَ بِالقُرْبِ أُفْرِدَا\r\rوالمراد بقوله: (لقوله) هو قوله تعالى: {لَّا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ}، وأما الرؤية في الآخرة فهي جائزة عقلاً واجبة شرعاً، قال الشيباني:\r\rولكنْ يراهُ في الجِنَانِ عِبَادُهُ…كما صَحَّ في الأخبارِ نَرويهِ مُسْنَدَا"], [161, "صفحة 161\rقال الحمزاوي: ورؤيته تعالى في الآخرة بكل جزء على التحقيق.\r\rوعن الإمام مالك رضي الله عنه قال: إنما لم يُرَ في الدنيا لأنه بَاقٍ ولا يُرى الباقي بالفاني، فإذا كان في الآخرة ورزقوا أبصاراً باقية رؤي الباقي بالباقي.\r\rقوله: (كَلَّمَا) بفتح الكاف وتشديد اللام وهو فعل مَاضٍ، وألفه لإطلاق الصوت وامتداده، وفاعله مستتر فيه يعود إلى (رَبّاً) والجملة صفة لـ (رَبّاً). قوله: (من غير كيف) متعلق بمحذوف صفة ثانية لـ (رباً) أي بلا كيف للمرئي بكيفية من كيفيات الحوادث من مقابلة وجهة وتَحيُّز وغير ذلك. قوله: (وانحصار) أي ولا انحصار للمرئي عند الرائي، بحيث يحيط به؛ لاستحالة الحدود والنهايات عليه تعالى، وكذا الرؤية في الآخرة، فإنه تعالى يُرَى من غير تَكَيُّفٍ بكيفية من الكيفيات المعتبرة في رؤية الأجسام، ومن غير إحاطة، بل يَحَارُ العبد في العظمة والجلال، حتى لا يعرف اسمه ولا يشعر بمن حوله من الخلائق، فإن العقل يعجز هنالك عن الفهم، ويتلاشى الكل في جنب عظمته تعالى، فلا نعمة أعظم من رؤية ذاته تعالى، قال تعالى: {لِّلَّذِينَ أَحْسَنُوا الْحُسْنَى\rوَزِيَادَةٌ} أي للذين أحسنوا بالعمل الصالح الجنة والنظر لوجه الله الكريم، فَفُسِّرَ الحسنى بالجنة، والزيادة بالنظر لوجه الله الكريم. قال عوض الغمراوي:"], [162, "صفحة 162\rوأعظمُ النعيمِ في الجِنَانِ…رؤيتُهم وجهَ العَلِيْ المَنَّانِ\r\rوَالمَنَّانُ بفتح الميم وتشديد النون، ومعناه الذي يُشَرِّفُ عبادَه بالامتنان عليهم بما له عليهم من النعم. قاله الباجوري. وقوله: (العلي) بسكون الياء للوزن.\r\rثم اعلم أنه تعالى إنما خَصَّ حبيبه المصطفى بسماع كلامه الذي ليس بحرف ولا صوت، ورؤية ذاته سبحانه تبارك وتعالى في ذلك المقام الشريف المُعَدِّ للخطاب له صلى الله عليه وسلم، تعظيماً وتشريفاً له، وليس الله سبحانه وتعالى في مكان ولا جهة، تنزه الله عن ذلك، وإنما المكان منسوب إلى النبي صلى الله عليه وسلم، قال صلى الله عليه وسلم: (لا تفضِّلوني على يونس بن متى) أي لا تظنوا أني أقرب إلى الله من يونس بن متى، حيث ارتقى بي فوق السماوات السبع، ويونس في قعر البحر في بطن الحوت، فكلانا بالنسبة للقرب منه على حد سواء.\r\rقوله: (وافترض عليه خمساً بعد خمسين) أي وأوجب الله خمس صلوات عليه صلى الله عليه وسلم وعلى أمته أيضاً، بسؤاله صلى الله عليه وسلم له تعالى، بترجيع موسى عليه السلام بعد أن أوجب عليهم خمسين صلاة. وقوله: (فرض) تكملة للبيت وهو فعل ماض، أي: وقدَّر الله تلك الخمس وحكم بها.\r\rحكمة\rقال عثمان بن حسن الجوبري في درة الواعظين: وأما سبب المعراج فهو أن الأرض افتخرت على السماء فقالت الأرض: أنا خير مِنْكِ لأن الله تعالى"], [163, "صفحة 163\rزيَّنني بالبلاد والبحار والأنهار والأشجار والجبال وغيرها، فقالت السماء: أنا خير منكِ لأن الشمس والقمر والكواكب والأفلاك والبروج والعرش والكرسي والجنة فِيَّ، وقالت الأرض: فِيَّ بيت يزوره ويطوف به الأنبياء والمرسلون والأولياء والمؤمنون عامة، وقالت السماء: فيّ البيت المعمور يطوف به ملائكة السماوات، وفيّ الجنة التي هي مأوى أرواح الأنبياء والمرسلين، وأرواح الأولياء والصالحين، وقالت الأرض: إن سيد المرسلين وخاتم النبيين وحبيب رب العالمين وأفضل الموجودات عليه أكمل التحيات وَطَنَ فيّ، وأجرى شريعته عليّ. فلما سمعت السماءُ هذا عجزت وسكتت عن الجواب، وتوجهت إلى الله تعالى فقالت: إلهي أنت تجيب المضطر إذا دعاك، وأنا عجزت عن جواب الأرض، فأسألك أن يصعد محمدٌ إليّ فأتشرف به كما تشرفت الأرضُ بجماله وافتخرت، فأجاب دعوتها، وأوحى الله تعالى إلى جبريل فقال: اذهب إلى الجنة وخذ البراق واذهب إلى محمد، فذهب جبريل ورأى أربعين ألف براق يرتعون في رياض الجنة، وعلى جبهتهم اسم محمد، ورأى فيهم براقاً منكِّساً رأسَه يبكي وتسيل من عينيه الدموع، فقال جبريل: ما لك يا براق؟ قال: يا جبريل، إني سمعت منذ أربعين ألف سنة اسم محمدٍ، فوقع في قلبي محبة صاحب هذا الاسم وعشقته،"], [164, "صفحة 164\rوبعد ذلك لم أحتج إلى طعام ولا شراب، واحترقت بنار العشق، فقال جبريل: أنا أوصلك بمعشوقك، ثم أسرجه وألجمه، وجاء به إلى النبي صلى الله عليه وسلم…إلى آخر القصة المذكورة."], [165, "صفحة 165\rوَبَلَّغَ الأمةَ بالإسراءِ…وَفَرْضِ خمسةٍ بلا امتراءِ\r\rأي يجب على كل مكلف أن يعتقد أنه صلى الله عليه وسلم بلَّغ أمته بخبر الإسراء والمعراج، وبفرض خمس صلوات، وكان ذلك صبيحة ليلة الإسراء والمعراج، وكان أولَ صلاة ظهرت في الإسلام الظهرُ؛ لأنها أول صلاة علَّمها جبريل للنبي صلى الله عليه وسلم، وإنما لم تجب الصبح مع أن الصلاة فرضت ليلة الإسراء؛ لتوقف الوجوب على بيان الكيفية، ولم تبيَّن إلا عند الظهر.\r\rقوله: (وفرضِ خمسة) بالجر، معطوف على قوله بالإسراء، ولا يجوز أن يكون منصوباً معطوفاً على الأمة كما هو ظاهر عبارة الناظم في الشارح. قوله: (بلا امتراء) أي شك، قال في المصباح: وامترى في أمره أي شك، و (بلا امتراءِ) بالكسر وهو تكملة للبيت."], [166, "صفحة 166\rقَدْ فَازَ صِدِّيْقٌ بتصديقٍ لَهُ…وبالعُروجِ الصدقُ وافى أَهْلَهُ\r\rأي يجب على كل مكلف أن يعتقد أنه قد ظفر ونجا أبو بكر بتصديقه له صلى الله عليه وسلم، فيما أخبر به من الإسراء والمعراج، وهو أول من صدَّق النبي بهما، ولذلك لُقِّبَ بالصديق، واسمه عبد الله وهو صحابي ابن صحابي، وأبو بكر كنيته، قاله شيخنا يوسف. وقال ابن قاضي عجلون: إن أبا بكر صدَّق النبي صلى الله عليه وسلم في كل قوله، فإنه بادر إلى تصديق النبي صلى الله عليه وسلم وَلَازَمَ الصدقَ فلم يحصل منه وقفةٌ في حال من الأحوال، ولذلك يُلَقَّبُ بالصديق، واختُلف في اسمه فقيل عتيق، والصحيح أنه عبد الله، وعتيق لقب له لعتقه من النار، وقال محمد عليش: أبو بكر هو عبد الله بن عثمان بن أبي قحافة على المشهور. انتهى. وكان أبو بكر الصديق أفضل الأمة، قال رسول الله صلى الله عليه وسلم: (لو وُزِنَ إيمانُ أبي بكر وإيمان أهل الأرض (أي من هذه الأمة إلى يوم القيامة) لرجح عليهم)، وقال صلى الله عليه وسلم: (إن صفات المحبين ثلاثمائة وستون صفة، وكلها موجودة في أبي بكر).\r\rقوله: (وبالعروج) الواو داخلة على قوله: (الصدق)، و (بالعروج) متعلق به. قوله: (الصدق) مبتدأ، وجملة قوله: (وافى أهلَه) خبرُه، وتقدير الكلام: والصدق بالعروج وافى أهله، فمعنى قوله: (وافى) أي وافق، ومعنى قوله: (أهله) مستحقاً له، أي للإسراء والمعراج، وَمُتَّصِفاً بهما. قال في المصباح:"], [167, "صفحة 167\rوأهل العلم من اتُّصِفَ به، وأهل الإكرام أي المستحِقُّ له، ثم اعلم أن في كلام المصنف احتباكاً، وهو أن يحذف من كل نظير ما أثبته في الآخر، فالناظم حذف من البيت الأول المعراج لدلالة هذا البيت عليه، كما حذف الإسراء من هذا البيت لدلالة البيت الأول عليه."], [168, "صفحة 168\rوهذهِ عقيدةٌ مختصَرةْ…وللعوامِ سهلةٌ مُيَسَّرَةْ\r\rأي وهذه الألفاظ من أول المنظومة إلى آخرها عقيدة قليلة اللفظ، كثيرة المعنى، ولينةٌ عبارتُها، لا يَشُقُّ تحصيلُ معانيها، وخفيفةُ اللفظ فلا يعسر حفظُها، ولا يَصْعُبُ نطقُها على العوام.\r\rقوله: (عقيدة) هي ما يدين الإنسان به ويعقد عليه القلب، ويقال: عقيدة حسنة أي سالمة من الشك، وقوله: (مختصرة) قال السجاعي: إن المختصر لغةً: ما قل لفظه وكثر معناه، واصطلاحاً: ما قل لفظه سواء كثر معناه أو قل أو ساوى، فالقيد معتبر لغة لا اصطلاحاً.\r\rقوله: (وللعوام) متعلق بقوله (سهلة ميسرة)، فالواو داخلة على قوله سهلة ميسرة، أي وهذه عقيدة مختصرة وسهلة وميسرة للعوام، فالعوام جمع عامة بتشديد الميم فيهما، مثل دابة ودواب، والنسبة إلى العامة عامي، والهاء في العامة للتأكيد كما قال الفيومي في المصباح، والمراد بالعوام هنا: المبتدئون الآخذون في أوائل العلم، ومعنى قوله: (سهلة) أي لينة العبارة، فيقرب تحصيل معانيها، ومعنى قوله: (ميسرة) أي قليلة اللفظ، فلا يُسئِم نطقها، ولا يَعْسُرُ حفظها عن ظهر قلب."], [169, "صفحة 169\rناظمُ تلكَ أحمدُ المرزوقيْ…من ينتمي للصادقِ المَصْدُوْقِ\r\rقوله: (ناظم) مبتدأ وهو مضاف، وقوله: (تلك) مضاف إليه، وهو عائد إلى العقيدة، وقوله: (أحمد) خبر المبتدأ، وهو اسم الناظم الكريم، قوله: (المرزوقي) صفة أولى لأحمد، وهو لقبه نسبة إلى العارف بالله السيد مرزوق الكفافي، وأما كنيته فهو أبو الفوز، واسم أبيه محمد رمضان الحسني والحسيني. [1] قوله: (من ينتمي للصادق المصدوق) أي الذي ينتسب لرسول الله صلى الله عليه وسلم، فمَنْ اسم موصول صفة ثانية لأحمد، والصادق والمصدوق هما من أسمائه صلى الله عليه وسلم، ومعنى الصادق: الذي أخبر بالصدق، فلا يصدر منه كذب أصلاً، فلذلك سمَّته صلى الله عليه وسلم قريشٌ قبل الرسالة: الصادقَ الأمينَ. ومعنى المصدوق: أي الذي أخبر الناسُ بصدقه صلى الله عليه وسلم.\r\rثم اعلم أن ناظمَ هذه العقيدة العالمَ البارعَ اللوذعيَّ شرح عليها شرحاً لطيفاً سماه (تحصيل نيل المرام)، وأنا كتبت عليها أيضاً هذا الكتاب، وإن كنتُ لست من أَلَبِّ ذوي الألباب؛ رجاءً لدعائه المستجاب، فأنت أيها الواقف على هذا الكتاب إذا وجدت فيه شيئاً مخالفاً لشرح الناظم، فعليك بالميزان المعتدل، فالسيوطي قال: إن صاحب البيت أدرى بما فيه من متاعه، والأكثرون"], [170, "صفحة 170\rمن العلماء قالوا: فالحق أحق باتباعه، فأنا أطلب منك أن تبدِّل فسادَه بصلاحِه، فأعط كل شيء باستحقاقه، كما قال سيدنا علي كرم الله وجهه: لا تنظر إلى من قال، وانظر إلى ما قال، معناه: إذا سمعت كلاماً، فلا تنظر إلى حال قائله، ولكن انظر إلى أكثر طائله، فَرُبَّ جاهل يقول خيراً، ورب فاضل يقول شراً، قاله الشارح.\r\rتنبيه\rإنما ذكر الناظم اسمه الكريم لأنه مطلوب، ولذلك قال الشرقاوي: واعلم أنه يُطلب من كل بادئ في كل فن أربعةُ أمور على سبيل الوجوب الصناعي: البسملة، والحمدلة، والتشهّد، والصلاة على النبي صلى الله عليه وسلم، وثلاثة على سبيل الندب الصناعي: تسمية نفسه، وكتابه، والإتيان ببراعة الاستهلال، وهي أن يأتي المتكلم في ابتداء كلامه بما يشعر بمقصوده."], [171, "صفحة 171\rوالحمدُ للهِ وَصَلَّى سَلَّمَا…على النبيِّ خيرِ مَنْ قَدْ عَلَّمَا\r\rوَالآلِ والصحبِ وَكُلِّ مُرْشِدِ…وَكُلِّ مَنْ بخيرِ هديٍ يقتدي\r\rقوله: (سلما) معطوف على (وصلى) بحذف العاطف وألفه للإطلاق. قوله: (من قد علما) أي شخص قد عَلَّمَ الخير، فإن سيدنا محمداً خيرُ مَنْ علَّم الخلق الهداية. قال محمد البوصيري في البردة:\r\rلم يمتحنَّا بما تعيا العقولُ بِهِ…حِرْصاً علينا فلم نَرْتَبْ ولم نَهِمِ\r\rوالمعنى: لم يجرِّبنا صلى الله عليه وسلم بأمر تعجز عنه عقولُنا بحيث لا نهتدي لوجهه؛ لشدة رغبته صلى الله عليه وسلم في هدايتنا، بل أتى بالاستقامة الواضحة، فلم نشك فيما أتانا به، ولم نتحير فيه.\r\rقوله: (وكل مرشد) أي وكل مصلح وهادٍ إلى الخير. قوله: (وكل من بخير هدي يقتدي) أي كل من يتأسى بخير طريقة وجِهة. فقوله: (بخير) متعلق بـ (يقتدي). وقوله: (هَدْيٍ) بفتح الهاء وسكون الدال مثل فلس معناه الطريقة والجهة، ولما كان تمام التأليف من النعم حمد الناظمُ اللهَ عليه كما حمده في ابتدائه، فكأنه قال: الحمد لله الذي أقدرني على إتمامه، كما أقدرني على ابتدائه. وأيضاً إنما ختم كتابه الشريف بالحمد لِمَلِكِ الدارين، والصلاة على سيد الكونين، وعلى أتباعه من الفريقين، لقوله صلى الله عليه وسلم: (ما جلس قوم مجلساً لم يذكروا الله تعالى فيه، ولم يصلوا"], [172, "صفحة 172\rعلى نبيهم إلا كان عليهم تِرَة، فإن شاء عذَّبهم وإن شاء غفر لهم)، رواه الترمذي وابن ماجه. والتِّرَة مثل العِدَة معناه النقص، وفي رواية: إلا كان عليهم حسرة يوم القيامة وإن دخلوا الجنة."], [173, "صفحة 173\rوأسألُ الكريمَ إخلاصَ العملْ…ونفعَ كُلِّ مَنْ بِهَا قَدِ اشْتَغَلْ\r\rقوله: (وأسأل) أي وأطلب وأستعطي.\r\rواعلم أن سأل إن كان بمعنى استعطى كما هنا تعدى لمفعولين بنفسه، فالكريم مفعول أول وإخلاص العمل مفعول ثَانٍ، وإن كانت بمعنى استفهم تعدى للأول بنفسه، وللثاني بـ (عن) نحو: {يَسْأَلُونَكَ عَنِ الْأَنفَالِ}، أو بما في معناه نحو: {فَاسْأَلْ بِهِ خَبِيرًا} أي عنه.\r\rقوله: (الكريم) بفتح الكاف على المشهور ويجوز كسرها، وهو الذي يعطي النوال قبل السؤال، أو الذي عَمَّ عطاؤه الطائعَ والعاصيَ، لكونه المعطي لا لغرض، ولا لعوض. قوله: (إخلاص العمل)، اعلم أن الإخلاص له ثلاث درجات: الأولى: أن تعبد الله أو تعمل شيئاً لا طمعاً في الثواب ولا هرباً من العقاب، بل لكونه إلهك وأنت عبده، وهذه أعلاها، والثانية: أن تعبده أو تعمل بطاعته طلباً للثواب، وخوفاً من العقاب، أو طمعاً في الجنة وخوفاً من النار، وهي الوسطى، الثالثة: أن تعبده لتتشرف بعبادته وتُنسبَ إليه تعالى فيقال هذا عابد وصالح، أو تعمل لتحصيل الدنيا كما إذا قرأت سورة الواقعة للغنى ونحوه، وهو أدناها، فإذا عملت للرياء والسمعة كان حراماً عليك لفقد الإخلاص، قال الفضيل بن عياض: ترك العمل من أجل الناس رياء،"], [174, "صفحة 174\rوالعمل من أجل الناس شرك، والإخلاص أن يعافيك الله تعالى منهما. قوله: (ونفع) معطوف على الإخلاص، قوله: (بها) متعلق بـ (اشتغل) فالضمير عائد على العقيدة أي: وأسأل الكريم نفع كل من اشتغل بهذه العقيدة، مِنْ حِفظ لفظها أو تحصيلِ معناها. جعلنا الله ممن دخل تحت دعاء هذا الناظم رضي الله عنه، لأنه كان مجاب الدعوة."], [175, "صفحة 175\rأبياتُها مَيْزٌ بِعَدِّ الجُمَّلِ…تاريخُها لِيْ حَيُّ غُرٍّ جُمَّلِ\r\rأي عدد أبيات هذه العقيدة سبعة وخمسون بعدد حروف (مَيْز)؛ فالميم بأربعين والياء بعشرة والزاي بسبعة، وذلك بِعَدِّ الجُمَّلِ الكبير من قسمة حروف: أبجد هوز حطي كلمن سعفص قرشت ثخذ ضظغ.\r\rوانتهاءُ نظم هذه العقيدة في سنة ثمان وخمسين وألف ومائتين بعدد حروف (لي حي غر) بالجمل الكبير، فإن اللام بثلاثين والياء بعشرة والحاء بثمانية ثم الياء أيضاً بعشرة، والغين بألف والراء بمائتين، فالجمل الكبير تَعتبر من همزة أبجد إلى الطاء آحاداً، ومن الياء إلى الصاد أعشاراً، ومن القاف إلى الظاء مئاتٍ، والغين آحاد الألوف، وخرج بالجمل الكبير الجمل الصغير؛ فإن الآحاد والأعشار والمئات وآحاد الألوف كلها تعتبر آحاداً إلا الياء وحدها فتعتبر أعشاراً، فالكاف تعتبر باثنين واللام بثلاثة وهكذا، وكذلك القاف فتعتبر واحداً والراء باثنين، وهكذا، والغين بواحد، وخرج بذلك أيضاً عدد مرتب بأن يرتب من أول أبجد إلى آخرها، فالكاف بأحد عشر، واللام باثني عشر وهكذا بالترتيب.\r\rقوله: (أبياتها) جمع بيت وهو بيت النَّظْمِ، وهو ما يشتمل على أجزاء معلومة، وتسمى أجزاء التفاعيل، سمي بذلك لضم أجزائه بعضها إلى بعض على نوع خاص، كما تضم أجزاء البيت في عمارته على نوع خاص،"], [176, "صفحة 176\rويجمع أيضاً على بيوت. قوله: (الجُمَّل) بضم الجيم وتشديد الميم المفتوحة كَسُكَّر، هو حساب الجمل، وقد يُخَفَّفَ، كذا في القاموس. قوله: (تاريخها) مبتدأ وهو بالهمزة أو بالواو كما في القاموس، أَرَخَ الكتاب بتخفيف الراء وأرَّخه بتشديدها وآرخه بمد الهمزة: أي وقَّته، وَوَرَّخَ الكتاب بالواو وبتشديد الراء أي أرخه. انتهى. وقال في المصباح: أَرَّخْتَ الكتاب بالتثقيل في الأشهر، والتخفيفُ لغةٌ حكاها ابن القطاع، إذا جعلتَ له تاريخاً وهو بيان وقت انتهائه. ويقال ورخت على البدل، والتوريخ قليل الاستعمال.\r\rوسبب وضع التاريخ أول الإسلام أن عمر بن الخطاب رضي الله عنه أُتِيَ بصك مكتوب إلى شعبان، فقال: أهو شعبان الماضي أو شعبان القابل؟ ثم أَمَرَ بوضع التاريخ، واتفقت الصحابة على ابتداء التاريخ من هجرة النبي صلى الله عليه وسلم إلى المدينة، وجعلوا أول السنة المحرم، ويصير أول التاريخ الليلَ لأن الليل عند العرب سابق النهار؛ لأنهم أمّيون لا يحسنون الكتابة ولم يعرفوا حساب غيرهم من الأمم، فتمسكوا بظهور الهلال، وإنما يظهر بالليل فجعلوه ابتداء التاريخ، والأحسن ذكر الأقل ماضياً كان أو باقياً. انتهى.\r\rقوله: (حي غر) خبر لمبتدأ هو قوله: (لي). وقوله: (جُمَّلِ) تكملة للبيت، فهو حال من الخبر أي حال كونها جمل أي حساب جمل، وكسر اللام للضرورة."], [177, "صفحة 177\rفائدة\rقال صاحب (بدء الخلق): وروي أنه لما وُلِدَ عيسى بن مريم كان ابن يوم كأنه ابن شهرين، فلما صار ابن تسعة أشهر أخذته أمه وجاءت به إلى الكتَّاب وأقعدته بين يديه فقال له: قل بسم الله الرحمن الرحيم، قال عيسى: بسم الله الرحمن الرحيم، ثم قال: قل أبجد قال عيسى، وهل تدري ما أبجد؟ قال: لا، قال: الألف الله، والباء بهجة الله، والجيم جلال الله، والدال دين الله، (هوز) الهاء هوة جهنم، وهي الهاوية، والواو ويل لأهل النار، والزاي زفير جهنم، (حطي) حطت الخطايا عن المستغفرين، (كلمن) كلام الله لا مبدل لكلماته، (سعفص) صاع بصاع والخبز بالخبز، (قرشت) تقرشهم جهنم حين تحشرهم، فقال صاحب الكتَّاب لأمه: خذي ابنك فقد عُلِّمَ ولا حاجة له بالمعلم، وفي الخبر: أن عيسى لما أرسلته أمه إلى الكتَّاب قال له: قل بسم الله، فقال له عيسى: وما بسم الله؟ فقال معلم الكتَّاب: لا أدري، فقال: الباء بهاء الله، والسين سناء الله، والميم ملك الله، انتهى."], [178, "صفحة 178\rسَمَّيْتُهَا عقيدةَ العَوَامِ…مِنْ واجبٍ في الدينِ بالتمامِ\r\rقوله: (سميتها) الهاء مفعول أول وهي راجعة للعقيدة، وقوله: (عقيدة العوام) مفعول ثَانٍ لأن سمى يتعدى لمفعولين، لكن المفعول الثاني تارة يكون مجروراً بالياء وتارة يكون منصوباً، تقول: سمَّيت ولدي بزيد، وسميته زيداً، وكذلك كنيت ودعوت، كما ذكره محمد الأندلسي في كتابه المسمى بـ (المستقل بالمفهومية في حل ألفاظ الآجرومية)، وإنما ذكر الناظمُ اسْمَ هذه العقيدة لأنه مطلوب كما تقدم. قوله: (من واجب في الدين بالتمام) بيان لعقيدة العوام، أي التي هي واجبة في الدين بالتمام، وذلك لأنها اشتملت على العقائد الواجبة على المكلفين.\r\rفائدة\rأمور الدين أربعة، كما قاله النووي، أي علامات وجوده، وقد نظمها بعضهم من بحر الطويل فقال:\r\rأُمورٌ لِدِيْنٍ صدقُ قَصْدٍ وَفَا العَهْدِ…وتركٌ لمنهيٍّ كذا صحةُ العَقْدِ\r\rفصدق القصد: أداء العبادة بالنية والإخلاص، ووفاء العهد: الإتيان بالفرائض، وترك المنهي: اجتناب المحرمات، وصحة جزمه بعقائد أهل السنة.\r\rوهذا آخر ما يسره الله تعالى من غير رين ولا رهيق، بل هو كلام رقيق وتحقيق"], [179, "صفحة 179\rدقيق، واللهَ أسألُ وبنبيه أتوسلُ أن يجعل هذا الكتاب خالصاً لوجهه الكريم، وأن ينفع به النفع العميم. والمرجو من صاحب العقل السليم، وَالخُلُقِ القويم أن يرفعَ عثراتي، ويسترَ هفواتي، وكن يا أخي للعيوب ساتراً، واللهَ أسألُ أن يكون للذنوب غافراً، ولا حول ولا قوة إلا بالله العلي العظيم، وصلى الله وسلّم وشرّف وكرّم على النبي الرؤوف الرحيم، وعلى آله وصحبه أجمعين، سبحان ربك رب العزة عما يصفون، وسلام على المرسلين، والحمد لله رب العالمين.\r\rقال المؤلف: وكان ابتداء هذا الكتاب يوم الثلاثاء بعد الظهر في الثالث عشر من شهر شوال المبارك من شهور سنة 1277 هـ (ألف ومائتين وسبعة وسبعين من الهجرة النبوية على صاحبها أفضل الصلاة وأزكى التحية)، وقد وافق الكمالَ يوم السبت وقت الضحى في الرابع والعشرين من ذلك الشهر في مكة المشرفة، وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم.\r____________\r[1] الحسني من جهة أبيه، الحسيني من جهة أمه."]], "pg": [69, 179]}}, "units": {"1": {"tit": "صاحب قصيدة (عقيدة العوام)", "lvl": 1, "pg": [5, 6]}, "2": {"tit": "نور الظلام شرح منظومة عقيدة العوام", "lvl": 1, "pg": [6, 9]}, "5": {"tit": "منظومة عقيدة العوام", "lvl": 1, "pg": [9, 16]}, "12": {"tit": "أبدأ باسم الله والرحمن", "lvl": 1, "pg": [16, 19]}, "15": {"tit": "فالحمد لله القديم الأولِ", "lvl": 1, "pg": [19, 24]}, "20": {"tit": "ثم الصلاة والسلام سرمدا", "lvl": 1, "pg": [24, 33]}, "29": {"tit": "الفصل الأول في صفات الله تعالى", "lvl": 1, "pg": [33, 36]}, "32": {"tit": "فاللهُ موجودٌ قديمٌ باقي", "lvl": 2, "pg": [36, 42]}, "38": {"tit": "فقدرةٌ إرادةٌ سمعٌ بصرْ", "lvl": 2, "pg": [42, 47]}, "43": {"tit": "وجائزٌ بفضلهِ وعدلهِ", "lvl": 2, "pg": [47, 51]}, "47": {"tit": "أرسلَ أنبيا ذوي فطانةْ", "lvl": 2, "pg": [51, 52]}, "48": {"tit": "وجائزٌ في حقهمْ من عَرَضِ", "lvl": 2, "pg": [52, 55]}, "51": {"tit": "عِصمتُهم كسائرِ الملائكةْ", "lvl": 2, "pg": [55, 57]}, "53": {"tit": "والمستحيلُ ضِدُّ كُلِّ واجبِ", "lvl": 2, "pg": [57, 59]}, "55": {"tit": "تفصيلُ خمسةٍ وعشرينَ لَزِمْ", "lvl": 2, "pg": [59, 60]}, "56": {"tit": "لوطٍ وإلياسَ ذي الكِفْلِ أو اتَّحَدَا", "lvl": 2, "pg": [60, 61]}, "57": {"tit": "هُمْ آدَمٌ إدريسُ نوحٌ هودٌ معْ", "lvl": 2, "pg": [61, 65]}, "61": {"tit": "عليهمُ الصلاةُ والسلامُ", "lvl": 2, "pg": [65, 69]}, "65": {"tit": "الفصل الثالث في الملائكة عليهم السلام", "lvl": 1, "pg": [69, 179]}}};
